  // WhatsApp Webhook POST - Receive and store incoming messages
  app.post("/api/public/whatsapp/:companyId", async (req, res) => {
    try {
      const { companyId } = req.params;
      const payload = req.body;
      
      console.log("[WhatsApp Webhook] POST received for company:", companyId);
      console.log("[WhatsApp Webhook] Payload:", JSON.stringify(payload).substring(0, 500));
      
      // Respond immediately (WhatsApp requires response within 10 seconds)
      res.status(200).json({ status: "received" });
      
      // Process asynchronously
      try {
        // Parse Meta/WhatsApp webhook payload
        if (payload.object === "whatsapp_business_account" && payload.entry) {
          for (const entry of payload.entry) {
            for (const change of entry.changes || []) {
              if (change.field === "messages" && change.value) {
                const metadata = change.value.metadata || {};
                const contacts = change.value.contacts || [];
                const messages = change.value.messages || [];
                
                const displayPhoneNumber = metadata.display_phone_number || "";
                
                for (const message of messages) {
                  const contact = contacts.find((c: any) => c.wa_id === message.from) || contacts[0] || {};
                  
                  // Extract message text based on type
                  let messageText = "";
                  if (message.type === "text" && message.text) {
                    messageText = message.text.body || "";
                  } else if (message.type === "interactive") {
                    if (message.interactive?.button_reply) {
                      messageText = message.interactive.button_reply.title || "";
                    } else if (message.interactive?.list_reply) {
                      messageText = message.interactive.list_reply.title || "";
                    }
                  }
                  
                  // Store in whatsapp_message_logs
                  await storage.createWhatsAppMessageLog({
                    company_id: companyId,
                    webhook_request_id: entry.id || "",
                    sender_phone: message.from || "",
                    sender_name: contact.profile?.name || null,
                    sender_wa_id: message.from || contact.wa_id || "",
                    display_phone_number: displayPhoneNumber,
                    message_id: message.id || "",
                    message_text: messageText || null,
                    message_type: message.type || "unknown",
                    referral_data: message.referral || null,
                    outcome: "pending",
                    trigger_matched: false,
                    matched_rule_id: null,
                    outcome_details: null,
                    processed_at: null
                  });
                  
                  console.log("[WhatsApp Webhook] Message stored from:", message.from, "type:", message.type);
                }
              }
            }
          }
        } else if (payload.messages || payload.from || payload.text) {
          // Alternative simpler format (used by some providers like Wauper)
          const messages = payload.messages || [payload];
          
          for (const msg of messages) {
            await storage.createWhatsAppMessageLog({
              company_id: companyId,
              webhook_request_id: payload.id || payload.webhook_id || "",
              sender_phone: msg.from || payload.from || "",
              sender_name: msg.sender_name || payload.sender_name || null,
              sender_wa_id: msg.wa_id || msg.from || payload.from || "",
              display_phone_number: msg.display_phone_number || payload.display_phone_number || "",
              message_id: msg.id || msg.message_id || "",
              message_text: msg.text?.body || msg.body || msg.text || null,
              message_type: msg.type || "text",
              referral_data: msg.referral || null,
              outcome: "pending",
              trigger_matched: false,
              matched_rule_id: null,
              outcome_details: null,
              processed_at: null
            });
            
            console.log("[WhatsApp Webhook] Alternative format message stored");
          }
        } else {
          console.log("[WhatsApp Webhook] Unknown payload format, storing raw");
          // Store raw payload for debugging
          await storage.createWhatsAppMessageLog({
            company_id: companyId,
            webhook_request_id: "",
            sender_phone: "",
            sender_name: null,
            sender_wa_id: "",
            display_phone_number: "",
            message_id: "",
            message_text: JSON.stringify(payload).substring(0, 1000),
            message_type: "raw",
            referral_data: null,
            outcome: "pending",
            trigger_matched: false,
            matched_rule_id: null,
            outcome_details: { raw_payload: true },
            processed_at: null
          });
        }
      } catch (processError: any) {
        console.error("[WhatsApp Webhook] Processing error:", processError);
      }
    } catch (error: any) {
      console.error("[WhatsApp Webhook] POST error:", error);
      res.status(500).json({ error: "Internal server error" });
    }
  });

  // Public Webhook Ingestion Endpoint
  app.post("/api/public/webhooks/:token", webhookLimiter, async (req, res) => {
    let webhook;
    let requestStatus: "success" | "failed" | "pending_configuration" = "failed";
    let errorMessage: string | null = null;
    let createdLeadId: string | null = null;
    let targetSheetId: string | null = null;
    let alreadyLogged = false; // Track if we've already logged this request

    try {
      // Find webhook by token
      webhook = await storage.getCompanyWebhookByToken(req.params.token);
      
      if (!webhook) {
        errorMessage = "Invalid webhook token";
        return res.status(404).json({ error: errorMessage });
      }

      // Check if webhook is active
      if (!webhook.is_active) {
        errorMessage = "Webhook is inactive";
        return res.status(403).json({ error: errorMessage });
      }

      // Detect WhatsApp Cloud API payload structure
      const payload = req.body;
      const isWhatsAppPayload = !!(
        payload?.object === "whatsapp_business_account" &&
        Array.isArray(payload?.entry) &&
        payload?.entry?.length > 0
      );
      
      // For WhatsApp payloads, check if there's a matching phone allocation for this company
      // This supports multiple WhatsApp business numbers per company, each with their own webhook
      let shouldProcessAsWhatsApp = false;
      if (isWhatsAppPayload) {
        // Fetch allocations once, outside the loop for efficiency
        const allocations = await storage.getWhatsAppAllocations(webhook.company_id);
        
        // Extract the display_phone_number from the payload to check for allocations
        for (const entry of payload.entry) {
          const changes = entry.changes || [];
          for (const change of changes) {
            if (change.field === "messages" && change.value?.metadata?.display_phone_number) {
              const displayPhone = change.value.metadata.display_phone_number;
              // Check if there's a phone allocation for this WhatsApp business number
              const matchingAllocation = allocations.find(
                a => a.enabled && a.display_phone_number === displayPhone
              );
              if (matchingAllocation) {
                shouldProcessAsWhatsApp = true;
                break;
              }
            }
          }
          if (shouldProcessAsWhatsApp) break;
        }
      }
      
      // If this is a WhatsApp payload with matching allocation, process via WhatsApp flow
      if (shouldProcessAsWhatsApp) {
        let webhookRequestId: string | null = null;
        try {
          // Log the webhook request first
          const webhookRequest = await storage.createWebhookRequest({
            webhook_id: webhook.id,
            status: "pending",
            payload: req.body,
            headers: req.headers as any,
            error_message: null,
            lead_id: null,
            allocated_sheet_id: null,
          });
          webhookRequestId = webhookRequest.id;
          alreadyLogged = true;
          
          // Process WhatsApp messages
          for (const entry of payload.entry) {
            const changes = entry.changes || [];
            for (const change of changes) {
              if (change.field === "messages" && change.value) {
                const value = change.value;
                const messages = value.messages || [];
                const contacts = value.contacts || [];
                const metadata = value.metadata || {};
                
                for (let i = 0; i < messages.length; i++) {
                  const msg = messages[i];
                  const contact = contacts[i] || {};
                  
                  // Extract message text
                  let messageText = "";
                  if (msg.type === "text" && msg.text?.body) {
                    messageText = msg.text.body;
                  } else if (msg.type === "button" && msg.button?.text) {
                    messageText = msg.button.text;
                  } else if (msg.type === "interactive" && msg.interactive?.button_reply?.title) {
                    messageText = msg.interactive.button_reply.title;
                  }
                  
                  const senderPhone = msg.from || "";
                  const normalizedPhone = senderPhone.replace(/\D/g, "").slice(-10);
                  
                  // Create WhatsApp message log
                  const whatsappLog = await storage.createWhatsAppMessageLog({
                    company_id: webhook.company_id,
                    webhook_request_id: webhookRequest.id,
                    sender_phone: normalizedPhone,
                    sender_name: contact.profile?.name || null,
                    sender_wa_id: contact.wa_id || senderPhone,
                    display_phone_number: metadata.display_phone_number || "",
                    message_id: msg.id || "",
                    message_text: messageText,
                    message_type: msg.type || "unknown",
                    referral_data: msg.referral || null,
                    outcome: "pending",
                    trigger_matched: false,
                    matched_rule_id: null,
                    outcome_details: {},
                    processed_at: null
                  });
                  
                  // Process through WhatsApp processor
                  const { processWhatsAppMessage } = await import("./whatsapp-processor");
                  const result = await processWhatsAppMessage(whatsappLog);
                  
                  console.log("[Webhook] WhatsApp processor result:", { 
                    success: result.success, 
                    outcome: result.outcome,
                    leadId: result.leadId,
                    message: result.message 
                  });
                  
                  // Update webhook request status based on result - any successful outcome counts as success
                  if (result.success) {
                    requestStatus = "success";
                    if (result.leadId) {
                      createdLeadId = result.leadId;
                    }
                  }
                }
              }
            }
          }
          
          // Update webhook request status with proper statuses matching existing system
          console.log("[Webhook] Updating webhook request status:", { 
            webhookRequestId: webhookRequest.id, 
            requestStatus, 
            createdLeadId 
          });
          
          try {
            await storage.updateWebhookRequest(webhookRequest.id, { 
              status: requestStatus, 
              lead_id: createdLeadId 
            });
            console.log("[Webhook] Successfully updated webhook request status to:", requestStatus);
          } catch (statusUpdateError: any) {
            console.error("[Webhook] Failed to update webhook request status:", statusUpdateError);
            // Don't throw - the message was processed successfully, just log the status update failure
          }
          
          return res.status(200).json({ success: true, message: "WhatsApp message processed" });
        } catch (whatsAppError: any) {
          console.error("[Webhook] WhatsApp processing error:", whatsAppError);
          errorMessage = whatsAppError.message;
          requestStatus = "failed";
          
          // Update webhook request status to failed in error case
          if (webhookRequestId) {
            try {
              await storage.updateWebhookRequest(webhookRequestId, { 
                status: "failed", 
                error_message: errorMessage 
              });
              console.log("[Webhook] Updated webhook request status to failed");
            } catch (updateError) {
              console.error("[Webhook] Failed to update request status:", updateError);
            }
          }
          
          return res.status(200).json({ success: true, message: "Webhook received" });
        }
      }

      // Get field mappings and allocation rules
      const fieldMappings = await storage.getWebhookFieldMappings(webhook.id);
      const allocationRules = await storage.getWebhookAllocationRules(webhook.id);

      // Check if this webhook is configured for match_and_update mode with no_match_action=ignore
      // In this case, we don't need allocation rules - we only want to update existing leads
      const matchMode = webhook.match_mode || "create_only";
      const noMatchAction = webhook.no_match_action || "create_lead";
      const canProcessWithoutAllocation = 
        matchMode === "match_and_update" && noMatchAction === "ignore";
      
      // If no allocation rules configured and we can't process without them, accept the data but don't create a lead
      // This allows users to test webhooks and see field names before completing configuration
      if (allocationRules.length === 0 && !canProcessWithoutAllocation) {
        requestStatus = "pending_configuration";
        // Log request before returning so status is properly recorded
        await storage.createWebhookRequest({
          webhook_id: webhook.id,
          status: requestStatus,
          payload: req.body,
          headers: req.headers as any,
          error_message: null,
          lead_id: null,
          allocated_sheet_id: null,
        });
        alreadyLogged = true; // Prevent duplicate logging in finally block
        
        return res.status(200).json({ 
          success: true,
          message: "Webhook data received. Please configure allocation rules in your CRM to start creating leads.",
          status: "pending_configuration"
        });
      }

      // Helper function to extract value from nested object using dot notation
      const getNestedValue = (obj: any, path: string): any => {
        const keys = path.split('.');
        let current = obj;
        
        for (const key of keys) {
          if (current && typeof current === 'object' && key in current) {
            current = current[key];
          } else {
            return undefined;
          }
        }
        
        return current;
      };

      // Apply field mappings to transform webhook payload to lead data
      const incomingData = req.body;
      const leadData: any = {};

      // Map webhook fields to sheet column keys (supports dot notation for nested fields)
      // Also handles default values when configured
      for (const mapping of fieldMappings) {
        // Check for default value first (if configured)
        if ((mapping as any).use_default_value && (mapping as any).default_value !== undefined) {
          leadData[mapping.sheet_column_key] = (mapping as any).default_value;
        } else if (mapping.webhook_field) {
          const value = getNestedValue(incomingData, mapping.webhook_field);
          if (value !== undefined && value !== null) {
            leadData[mapping.sheet_column_key] = value;
          }
        }
      }

      // Helper function to evaluate a single condition
      const evaluateSingleCondition = (condition: { field: string; operator: string; value: string }, webhookData: any): boolean => {
        // Extract value from webhook data using dot notation
        const actualValue = getNestedValue(webhookData, condition.field);
        if (actualValue === undefined || actualValue === null) {
          return false;
        }

        // Convert to string for comparison
        const actualStr = String(actualValue).toLowerCase();
        const expectedStr = String(condition.value || '').toLowerCase();

        // Evaluate based on operator
        switch (condition.operator) {
          case "equals":
            return actualStr === expectedStr;
          case "contains":
            return actualStr.includes(expectedStr);
          case "starts_with":
            return actualStr.startsWith(expectedStr);
          case "ends_with":
            return actualStr.endsWith(expectedStr);
          case "not_equals":
            return actualStr !== expectedStr;
          case "not_contains":
            return !actualStr.includes(expectedStr);
          default:
            return false;
        }
      };

      // Helper function to evaluate conditions (supports both new JSON array and legacy fields)
      const evaluateCondition = (rule: any, webhookData: any): boolean => {
        // First check if rule has conditions JSON array (new format)
        if (rule.conditions && Array.isArray(rule.conditions) && rule.conditions.length > 0) {
          const logicalOp = (rule.logical_operator || 'and').toLowerCase();
          
          if (logicalOp === 'or') {
            // OR logic: at least one condition must match
            return rule.conditions.some((cond: any) => evaluateSingleCondition(cond, webhookData));
          } else {
            // AND logic (default): all conditions must match
            return rule.conditions.every((cond: any) => evaluateSingleCondition(cond, webhookData));
          }
        }
        
        // Fall back to legacy single-condition fields
        // Default rules (no condition fields) are NOT evaluated in the main filter
        // They are only used as fallback when no other rules match
        if (!rule.condition_field || !rule.condition_operator || !rule.condition_value) {
          return false;
        }

        // Use legacy single condition evaluation
        return evaluateSingleCondition({
          field: rule.condition_field,
          operator: rule.condition_operator,
          value: rule.condition_value
        }, webhookData);
      };

      // Filter allocation rules based on conditions
      let applicableRules = allocationRules.filter(rule => evaluateCondition(rule, incomingData));

      // If no rules match conditions, fall back to default rules
      if (applicableRules.length === 0) {
        applicableRules = allocationRules.filter(rule => rule.is_default === true);
      }

      // If still no rules, check if we can process without allocation (match_and_update mode)
      // Otherwise, store as pending and return success
      if (applicableRules.length === 0 && !canProcessWithoutAllocation) {
        const allocationIssue = "No allocation rules match the incoming data. Please configure allocation rules.";
        
        // Log webhook request with pending_allocation status
        await storage.createWebhookRequest({
          webhook_id: webhook.id,
          status: "pending_allocation",
          payload: req.body,
          headers: req.headers as any,
          error_message: allocationIssue,
          lead_id: null,
          allocated_sheet_id: null,
        });
        
        // Emit notification to company admins via Socket.io
        const io = (req as any).io;
        if (io) {
          io.to(`company:${webhook.company_id}`).emit("webhook_notification", {
            type: "allocation_issue",
            webhook_name: webhook.name,
            message: allocationIssue,
            timestamp: new Date().toISOString(),
          });
        }
        
        alreadyLogged = true;
        return res.status(200).json({ 
          success: true,
          message: "Data received successfully. Pending allocation - please configure allocation rules.",
          status: "pending_allocation"
        });
      }

      // Validate percentages sum to 100 for applicable rules (skip if processing without allocation)
      const totalPercentage = applicableRules.reduce((sum, rule) => sum + rule.percentage, 0);
      if (totalPercentage !== 100 && !canProcessWithoutAllocation) {
        const allocationIssue = `Allocation rules percentages must sum to 100% (current: ${totalPercentage}%). Please fix your rules.`;
        
        // Log webhook request with pending_allocation status
        await storage.createWebhookRequest({
          webhook_id: webhook.id,
          status: "pending_allocation",
          payload: req.body,
          headers: req.headers as any,
          error_message: allocationIssue,
          lead_id: null,
          allocated_sheet_id: null,
        });
        
        // Emit notification to company admins via Socket.io
        const io = (req as any).io;
        if (io) {
          io.to(`company:${webhook.company_id}`).emit("webhook_notification", {
            type: "allocation_issue",
            webhook_name: webhook.name,
            message: allocationIssue,
            timestamp: new Date().toISOString(),
          });
        }
        
        alreadyLogged = true;
        return res.status(200).json({ 
          success: true,
          message: "Data received successfully. Pending allocation - please fix allocation rules percentages.",
          status: "pending_allocation"
        });
      }

      // Determine which sheet to allocate to using weighted round-robin (only if we have allocation rules)
      // This ensures leads are distributed according to percentage weights over time
      let targetSheetId: string | null = null;
      let conditionGroupKey = 'default';
      
      // Only do allocation if we have applicable rules
      if (applicableRules.length > 0) {
        // Generate a unique key for this condition group based on the matching conditions
        const generateConditionGroupKey = (rules: typeof applicableRules): string => {
          if (rules.length === 0) return 'default';
          const firstRule = rules[0];
          if (firstRule.is_default) return 'default';
          
          // Use conditions array if available
          if (firstRule.conditions && firstRule.conditions.length > 0) {
            return firstRule.conditions.map(c => `${c.field}|${c.operator}|${c.value || ''}`).join('::');
          }
          // Fallback to legacy single condition fields
          return `${firstRule.condition_field || ''}|${firstRule.condition_operator || ''}|${firstRule.condition_value || ''}`;
        };
        
        conditionGroupKey = generateConditionGroupKey(applicableRules);
        
        // Get current allocation counts for this webhook
        let allocationCounts = (webhook.allocation_counts as Record<string, Record<string, number>>) || {};
        
        // MIGRATION: Consolidate legacy JSON-format keys to pipe format
        // This fixes the issue where old code used JSON.stringify for keys
        const migrateAllocationCounts = async () => {
          const allKeys = Object.keys(allocationCounts);
          const jsonKeys = allKeys.filter(k => k.startsWith('[{'));
          
          if (jsonKeys.length === 0) {
            return allocationCounts; // No migration needed
          }
          
          console.log(`[Webhook Allocation] Found ${jsonKeys.length} JSON-format keys to migrate`);
          const migratedCounts: Record<string, Record<string, number>> = {};
          const processedPipeKeys = new Set<string>();
          
          // Step 1: Process all JSON keys first, converting to pipe format
          for (const jsonKey of jsonKeys) {
            try {
              const conditions = JSON.parse(jsonKey) as Array<{field: string; operator: string; value?: string}>;
              const pipeKey = conditions.map(c => `${c.field}|${c.operator}|${c.value || ''}`).join('::');
              processedPipeKeys.add(pipeKey);
              
              // Initialize with existing pipe key counts if they exist
              if (!migratedCounts[pipeKey]) {
                migratedCounts[pipeKey] = { ...(allocationCounts[pipeKey] || {}) };
              }
              
              // Add JSON key counts
              const jsonCounts = allocationCounts[jsonKey];
              for (const sheetId of Object.keys(jsonCounts)) {
                migratedCounts[pipeKey][sheetId] = (migratedCounts[pipeKey][sheetId] || 0) + jsonCounts[sheetId];
              }
              console.log(`[Webhook Allocation] Migrated "${jsonKey.substring(0, 40)}..." → "${pipeKey}"`);
            } catch (e) {
              console.error(`[Webhook Allocation] Failed to migrate key: ${jsonKey}`, e);
              migratedCounts[jsonKey] = { ...allocationCounts[jsonKey] };
            }
          }
          
          // Step 2: Copy non-JSON keys that weren't already processed as part of migration
          for (const key of allKeys) {
            if (!key.startsWith('[{') && !processedPipeKeys.has(key)) {
              migratedCounts[key] = { ...allocationCounts[key] };
            }
          }
          
          console.log(`[Webhook Allocation] Persisting migrated allocation counts for webhook ${webhook.id}`);
          await storage.updateCompanyWebhook(webhook.id, { allocation_counts: migratedCounts });
          return migratedCounts;
        };
        
        // Run migration (for cleanup purposes only - we now use daily lead counts)
        allocationCounts = await migrateAllocationCounts();
        
        // DAILY LEAD-COUNT BASED WEIGHTED ROUND-ROBIN
        // Query actual leads created TODAY per sheet to ensure fair daily distribution
        // Each day resets naturally - 19% means 19% of TODAY's leads
        const webhookCompanyForAlloc = await storage.getCompany(webhook.company_id);
        const allocTimezone = getCompanyTimezone(webhookCompanyForAlloc);
        
        // Calculate today's date window in company timezone, converted to UTC for database query
        // 1. Get current time in company timezone
        const nowUtc = new Date();
        const nowInCompanyTz = toZonedTime(nowUtc, allocTimezone);
        // 2. Get start of day in company timezone
        const startOfTodayInCompanyTz = startOfDay(nowInCompanyTz);
        // 3. Get start of tomorrow in company timezone
        const startOfTomorrowInCompanyTz = new Date(startOfTodayInCompanyTz);
        startOfTomorrowInCompanyTz.setDate(startOfTomorrowInCompanyTz.getDate() + 1);
        // 4. Convert both to UTC for database query
        const todayStartUtc = fromZonedTime(startOfTodayInCompanyTz, allocTimezone);
        const tomorrowStartUtc = fromZonedTime(startOfTomorrowInCompanyTz, allocTimezone);
        
        // Get lead counts for today for each sheet in applicable rules
        const sheetIds = applicableRules.map(r => r.sheet_id);
        const todayLeadCounts: Record<string, number> = {};
        
        // Query leads created today per sheet (between start of today and before start of tomorrow)
        const leadCountResults = await db
          .select({ 
            sheet_id: dbSchema.leads.sheet_id, 
            count: sql<number>`count(*)::int` 
          })
          .from(dbSchema.leads)
          .where(
            and(
              inArray(dbSchema.leads.sheet_id, sheetIds),
              gte(dbSchema.leads.created_at, todayStartUtc),
              lt(dbSchema.leads.created_at, tomorrowStartUtc),
              isNull(dbSchema.leads.deleted_at)
            )
          )
          .groupBy(dbSchema.leads.sheet_id);
        
        // Build count map
        for (const row of leadCountResults) {
          todayLeadCounts[row.sheet_id] = row.count;
        }
        
        // Calculate which sheet is most behind its daily percentage target
        const totalPercentage = applicableRules.reduce((sum, r) => sum + r.percentage, 0);
        const totalTodayLeads = sheetIds.reduce((sum, id) => sum + (todayLeadCounts[id] || 0), 0);
        
        let selectedSheetId = applicableRules[0].sheet_id;
        
        // Error: if totalPercentage is invalid, log error and use first rule's sheet as fallback
        if (totalPercentage <= 0) {
          console.error(`[Webhook Allocation] Configuration error: totalPercentage is ${totalPercentage}. Check allocation rule percentages for webhook ${webhook.id}`);
          targetSheetId = selectedSheetId;
        } else {
          let bestGap = -Infinity;
          
          for (const rule of applicableRules) {
            const targetPercentage = rule.percentage / totalPercentage;
            const currentCount = todayLeadCounts[rule.sheet_id] || 0;
            let gap: number;
            
            if (totalTodayLeads === 0) {
              // First lead of the day - prioritize by target percentage
              gap = targetPercentage;
            } else {
              const actualShare = currentCount / totalTodayLeads;
              // Select sheet most behind its daily target
              gap = targetPercentage - actualShare;
            }
            
            if (gap > bestGap) {
              bestGap = gap;
              selectedSheetId = rule.sheet_id;
            }
          }
          
          targetSheetId = selectedSheetId;
        }
        console.log(`[Webhook Allocation] Daily allocation: Today's leads per sheet: ${JSON.stringify(todayLeadCounts)}, Total: ${totalTodayLeads}, Selected: ${selectedSheetId}`);

        // Verify target sheet exists and belongs to the company
        const targetSheet = await storage.getSheet(targetSheetId);
        if (!targetSheet) {
          errorMessage = "Target sheet not found";
          return res.status(404).json({ error: errorMessage });
        }

        if (targetSheet.company_id !== webhook.company_id) {
          errorMessage = "Sheet does not belong to webhook company";
          return res.status(403).json({ error: errorMessage });
        }
      }

      // Get webhook creator to use as lead owner
      const webhookCreator = await storage.getUser(webhook.created_by_user_id);
      if (!webhookCreator) {
        errorMessage = "Webhook creator not found";
        return res.status(500).json({ error: errorMessage });
      }

      // Enhanced match-and-update logic based on webhook configuration
      // Note: matchMode and noMatchAction are already defined above for canProcessWithoutAllocation check
      const matchRules = webhook.match_rules || [];
      // Backward compatibility: if no match_rules but match_field exists, create a single rule
      const effectiveMatchRules = matchRules.length > 0 
        ? matchRules 
        : webhook.match_field 
          ? [{ webhookField: webhook.match_field, crmFields: [webhook.match_field] }]
          : [{ webhookField: 'mobile_no', crmFields: ['mobile_no'] }];
      // Get the primary match field for logging purposes (first rule's webhook field)
      const matchField = effectiveMatchRules[0]?.webhookField || 'mobile_no';
      const matchValue = leadData[matchField] || getNestedValue(incomingData, matchField) || 'unknown';
      const updateFieldMappings = webhook.update_field_mappings || [];
      const sourceLabel = webhook.source_label || "Webhook";
      
      // Get company timezone for date/time defaults
      const webhookCompany = await storage.getCompany(webhook.company_id);
      const webhookCompanyTimezone = getCompanyTimezone(webhookCompany);
      const today = getTodayDateString(webhookCompanyTimezone);
      const currentTime = getCurrentTimeString(webhookCompanyTimezone);
      
      let lead: Lead;
      let existingLead: Lead | undefined = undefined;
      let isDuplicate = false;
      let isTransferred = false;
      let isUpdateAdded = false;
      let previousOwnerName = "";
      let oldSheetId: string | null = null;

      // Helper function to parse webhook timestamp with proper timezone handling
      // Respects company timezone settings for naive timestamps
      const parseWebhookTimestamp = async (timestamp: string | number | undefined | null): Promise<string | undefined> => {
        if (!timestamp) return undefined;
        
        try {
          let timestampStr = String(timestamp).trim();
          
          // Map of timezone abbreviations to their UTC offsets
          const tzAbbreviations: Record<string, string> = {
            'IST': '+05:30', // India Standard Time
            'GMT': '+00:00', // Greenwich Mean Time  
            'UTC': '+00:00', // Coordinated Universal Time
            'EST': '-05:00', // Eastern Standard Time
            'EDT': '-04:00', // Eastern Daylight Time
            'CST': '-06:00', // Central Standard Time
            'CDT': '-05:00', // Central Daylight Time
            'MST': '-07:00', // Mountain Standard Time
            'MDT': '-06:00', // Mountain Daylight Time
            'PST': '-08:00', // Pacific Standard Time
            'PDT': '-07:00', // Pacific Daylight Time
          };
          
          // Map of IANA timezone names to their typical UTC offsets
          // Note: These are approximate and don't account for DST transitions
          const ianaToOffset: Record<string, string> = {
            'Asia/Kolkata': '+05:30',
            'Asia/Calcutta': '+05:30', // Legacy name
            'UTC': '+00:00',
            'GMT': '+00:00',
            'America/New_York': '-05:00',
            'America/Chicago': '-06:00',
            'America/Denver': '-07:00',
            'America/Los_Angeles': '-08:00',
            'Europe/London': '+00:00',
            'Europe/Paris': '+01:00',
            'Europe/Berlin': '+01:00',
            'Asia/Dubai': '+04:00',
            'Asia/Singapore': '+08:00',
            'Asia/Tokyo': '+09:00',
            'Australia/Sydney': '+11:00',
          };
          
          // Determine the default timezone offset from company settings
          let defaultOffset = '+05:30'; // Fallback to IST for this India-based CRM
          const company = await storage.getCompany(webhook.company_id);
          if (company?.settings?.timezone) {
            const companyTz = company.settings.timezone;
            if (ianaToOffset[companyTz]) {
              defaultOffset = ianaToOffset[companyTz];
            }
          }
          
          // Check for trailing timezone abbreviation and extract offset
          let tzOffset = defaultOffset;
          const abbrevMatch = timestampStr.match(/\s+(IST|GMT|UTC|EST|EDT|CST|CDT|MST|MDT|PST|PDT)$/i);
          if (abbrevMatch) {
            const abbrev = abbrevMatch[1].toUpperCase();
            if (tzAbbreviations[abbrev]) {
              tzOffset = tzAbbreviations[abbrev];
            }
            // Strip the abbreviation from the timestamp
            timestampStr = timestampStr.replace(/\s+(IST|GMT|UTC|EST|EDT|CST|CDT|MST|MDT|PST|PDT)$/i, '');
          }
          
          // Handle numeric offsets without colon (e.g., "+0530" -> "+05:30")
          const numericOffsetMatch = timestampStr.match(/([+-])(\d{2})(\d{2})$/);
          if (numericOffsetMatch) {
            timestampStr = timestampStr.replace(/([+-])(\d{2})(\d{2})$/, '$1$2:$3');
          }
          
          // Check if the timestamp has explicit timezone info (Z or +/- offset)
          const hasExplicitTimezone = /[Z]$|[+-]\d{2}:?\d{2}$/i.test(timestampStr);
          
          if (!hasExplicitTimezone) {
            // Timestamp is timezone-naive (e.g., "2025-12-02 06:27:31")
            // Use company timezone or fallback to IST
            // Convert to valid ISO 8601 format: replace space with 'T' and append offset
            timestampStr = timestampStr.replace(' ', 'T') + tzOffset;
          }
          
          const parsed = new Date(timestampStr);
          if (!isNaN(parsed.getTime())) {
            return parsed.toISOString();
          }
        } catch (e) {
          console.log('Failed to parse webhook timestamp:', timestamp, e);
        }
        return undefined;
      };

      // Helper function to create a new lead (only called when targetSheetId is set)
      const createNewLead = async () => {
        if (!targetSheetId) {
          throw new Error("Cannot create lead without a target sheet");
        }
        
        // Parse webhook's created_at timestamp for use as lead creation time
        // This captures when the form was actually submitted, not when we processed it
        const webhookTimestamp = leadData.created_at || incomingData.created_at;
        const webhookCreatedAt = await parseWebhookTimestamp(webhookTimestamp);
        
        // Build custom_fields with lead data
        const customFields: Record<string, any> = {
          name: leadData.name || "",
          mobile_no: leadData.mobile_no || "",
          whatsapp_no: leadData.whatsapp_no || leadData.mobile_no || "",
          lang: leadData.lang || "",
          occupation: leadData.occupation || "",
          qualification: leadData.qualification || "",
          lead_date: leadData.lead_date || today,
          lead_time: leadData.lead_time || currentTime,
          lead_status: leadData.lead_status || "New",
          visit_status: leadData.visit_status || "Not Visited",
          ...leadData,
        };
        
        // AUTO-UPDATE: Set conversion_date if lead_status is "Converted"
        const leadStatus = customFields.lead_status;
        if (leadStatus && 
            typeof leadStatus === 'string' && 
            leadStatus.toLowerCase() === 'converted' &&
            !customFields.conversion_date) {
          customFields.conversion_date = new Date().toISOString();
        }
        
        return await storage.createLead({
          sheet_id: targetSheetId,
          owner_user_id: webhook.created_by_user_id,
          custom_fields: customFields,
          meta: leadData.meta || {},
          // Use webhook timestamp as lead creation time (fallback to system time if invalid)
          created_at: webhookCreatedAt,
        });
      };

      // Step 1: Check for existing lead if not create_only mode using multi-field matching rules
      if (matchMode !== "create_only") {
        // Try each match rule until we find a match (OR logic between rules)
        for (const rule of effectiveMatchRules) {
          if (existingLead) break; // Already found a match
          
          // Get the webhook field value from the incoming data
          const webhookValue = leadData[rule.webhookField] || getNestedValue(incomingData, rule.webhookField);
          if (!webhookValue) continue; // No value to match against
          
          // Try each CRM field in the rule (OR logic)
          for (const crmField of rule.crmFields) {
            // Use mobile number normalization for phone-related fields
            const isMobileField = ['mobile_no', 'whatsapp', 'whatsapp_no', 'phone', 'phone_no'].some(
              f => crmField.toLowerCase().includes(f.replace('_', '')) || rule.webhookField.toLowerCase().includes(f.replace('_', ''))
            );
            
            if (isMobileField) {
              // Normalize and find by mobile number (handles +91, spaces, dashes, etc.)
              // Pass includeDeleted=true to find soft-deleted leads for restoration
              const normalizedValue = normalizePhoneNumber(String(webhookValue));
              const found = await storage.findLeadByMobileNo(webhook.company_id, normalizedValue, crmField, true);
              if (found) {
                existingLead = found;
                break;
              }
            } else {
              // Exact match for non-mobile fields
              // Pass includeDeleted=true to find soft-deleted leads for restoration
              const found = await storage.findLeadByField(webhook.company_id, crmField, String(webhookValue), true);
              if (found) {
                existingLead = found;
                break;
              }
            }
          }
        }
      }

      if (existingLead) {
        isDuplicate = true;
        
        // Restore if soft-deleted
        if (existingLead.deleted_at) {
          await storage.restoreLead(existingLead.id);
          await storage.createLeadUpdate({
            lead_id: existingLead.id,
            update_via: "webhook",
            update_on: today,
            remark: `Restored due to new lead receipt via ${sourceLabel}`,
            created_by_user_id: webhook.created_by_user_id,
          });
        }

        // Step 2: Handle based on match_mode
        if (matchMode === "match_and_update" || matchMode === "match_or_create") {
          // Update lead fields based on field mappings or merge all data
          const mergedCustomFields = { ...existingLead.custom_fields };
          
          if (updateFieldMappings.length > 0) {
            // Use specific field mappings for updates
            for (const mapping of updateFieldMappings) {
              const sourceValue = getNestedValue(incomingData, mapping.source_field);
              if (sourceValue !== undefined && sourceValue !== null && sourceValue !== "") {
                mergedCustomFields[mapping.target_column] = sourceValue;
              }
            }
          } else {
            // Merge all incoming fields (default behavior)
            for (const [key, value] of Object.entries(leadData)) {
              if (value !== undefined && value !== null && value !== "") {
                mergedCustomFields[key] = value;
              }
            }
          }
          
          // Always update lead_date to today
          mergedCustomFields.lead_date = today;

          // Apply match_reset_status if enabled
          if (webhook.match_reset_status_enabled && webhook.match_reset_status_value) {
            mergedCustomFields.lead_status = webhook.match_reset_status_value;
          }

          // Enforce final value protection for automations (block_automations flag)
          const blockedMap = getAutomationBlockedFinalValues(webhookCompany?.settings);
          const filteredFields = filterBlockedAutomationFields(
            existingLead.custom_fields || {},
            mergedCustomFields,
            blockedMap
          );
          
          const updated = await storage.updateLead(existingLead.id, {
            custom_fields: filteredFields,
            deleted_at: null,
          });
          
          if (!updated) {
            errorMessage = "Failed to update existing lead";
            return res.status(500).json({ error: errorMessage });
          }
          
          lead = updated;
          
          // Create update log
          await storage.createLeadUpdate({
            lead_id: existingLead.id,
            update_via: "webhook",
            update_on: today,
            remark: `Lead updated via ${sourceLabel}`,
            created_by_user_id: webhook.created_by_user_id,
          });
          
          // Award PowerScore points for webhook dropdown changes
          if (webhookCompany) {
            const sheetForScoring = await storage.getSheet(existingLead.sheet_id);
            if (sheetForScoring) {
              const customColumns = await storage.getCustomColumns(existingLead.sheet_id);
              const allDropdownKeys = getAllDropdownKeys(customColumns);
              const dropdownChanges: { columnKey: string; oldValue: string | null; newValue: string | null }[] = [];
              
              for (const columnKey of allDropdownKeys) {
                const oldVal = existingLead.custom_fields?.[columnKey] ?? null;
                const newVal = filteredFields[columnKey];
                if (newVal !== undefined && oldVal !== newVal) {
                  dropdownChanges.push({
                    columnKey,
                    oldValue: oldVal,
                    newValue: newVal,
                  });
                }
              }
              
              if (dropdownChanges.length > 0) {
                awardLeadUpdatePoints({
                  userId: webhook.created_by_user_id,
                  companyId: webhook.company_id,
                  companyTimezone: webhookCompanyTimezone,
                  leadId: existingLead.id,
                }, dropdownChanges).catch(err => console.error("PowerScore webhook update error:", err));
                
                // Reversal protection for webhook updates
                for (const change of dropdownChanges) {
                  checkAndCancelReversedApprovals(existingLead.id, change.columnKey, change.newValue)
                    .catch(err => console.error("PowerScore webhook reversal check error:", err));
                }
              }
            }
          }
          
        } else if (matchMode === "match_and_add_update") {
          // Apply match_reset_status if enabled (change lead_status even in add_update mode)
          if (webhook.match_reset_status_enabled && webhook.match_reset_status_value) {
            let updatedFields: Record<string, any> = { ...existingLead.custom_fields, lead_status: webhook.match_reset_status_value };
            // Enforce final value protection for automations
            const blockedMapAddUpdate = getAutomationBlockedFinalValues(webhookCompany?.settings);
            updatedFields = filterBlockedAutomationFields(
              existingLead.custom_fields || {},
              updatedFields,
              blockedMapAddUpdate
            );
            await storage.updateLead(existingLead.id, { custom_fields: updatedFields });
            existingLead = { ...existingLead, custom_fields: updatedFields };
          }
          
          // Just add a Lead Update without modifying the lead fields
          lead = existingLead;
          isUpdateAdded = true;
          
          // Build update remark from incoming data
          const updateParts: string[] = [];
          if (updateFieldMappings.length > 0) {
            for (const mapping of updateFieldMappings) {
              const sourceValue = getNestedValue(incomingData, mapping.source_field);
              if (sourceValue !== undefined && sourceValue !== null && sourceValue !== "") {
                updateParts.push(`${mapping.target_column}: ${sourceValue}`);
              }
            }
          } else {
            // Include all mapped fields in the update
            for (const [key, value] of Object.entries(leadData)) {
              if (value !== undefined && value !== null && value !== "" && key !== matchField) {
                updateParts.push(`${key}: ${value}`);
              }
            }
          }
          
          const updateRemark = updateParts.length > 0 
            ? `${sourceLabel} update: ${updateParts.join(", ")}` 
            : `New activity from ${sourceLabel}`;
          
          await storage.createLeadUpdate({
            lead_id: existingLead.id,
            update_via: "webhook",
            update_on: today,
            remark: updateRemark,
            created_by_user_id: webhook.created_by_user_id,
          });
        } else {
          // Fallback for any other mode with existing lead
          lead = existingLead;
        }
        
        // Check if lead needs to be transferred to different sheet
        // If skip_allocation_on_match is true, don't transfer - keep lead in its current sheet
        // If targetSheetId is null (no allocation rules), don't transfer
        const skipAllocationOnMatch = webhook.skip_allocation_on_match === true;
        
        if (!skipAllocationOnMatch && targetSheetId && existingLead.sheet_id !== targetSheetId) {
          oldSheetId = existingLead.sheet_id;
          
          // Get source and target sheet names for the transfer log
          const sourceSheet = await storage.getSheet(existingLead.sheet_id);
          const targetSheet = await storage.getSheet(targetSheetId);
          const sourceSheetName = sourceSheet?.name || "Unknown Sheet";
          const targetSheetName = targetSheet?.name || "Unknown Sheet";
          
          // Determine the new owner for the transferred lead
          // Use target sheet's owner_id to maintain consistency with sheet ownership
          const newOwnerId = targetSheet?.owner_id || webhook.created_by_user_id;
          
          // Also get previous owner for reference
          const previousOwner = await storage.getUser(existingLead.owner_user_id);
          previousOwnerName = previousOwner?.name || "Unknown";
          
          await storage.updateLead(existingLead.id, {
            sheet_id: targetSheetId,
            owner_user_id: newOwnerId,
          });
          
          isTransferred = true;
          
          // Log the transfer with sheet names and source label
          await storage.createLeadUpdate({
            lead_id: existingLead.id,
            update_via: "transfer",
            update_on: today,
            remark: `Transferred from ${sourceSheetName} to ${targetSheetName} due to Re-application via ${sourceLabel}`,
            created_by_user_id: webhook.created_by_user_id,
          });
          
          const transferredLead = await storage.getLead(existingLead.id);
          if (transferredLead) {
            lead = transferredLead;
          }
        }
        
        createdLeadId = existingLead.id;
        
      } else {
        // No matching lead found - handle based on no_match_action
        if (matchMode === "create_only" || noMatchAction === "create_lead") {
          // Create new lead
          lead = await createNewLead();
          createdLeadId = lead.id;
        } else if (noMatchAction === "ignore") {
          // Silently ignore - return success without creating anything
          requestStatus = "success";
          await storage.createWebhookRequest({
            webhook_id: webhook.id,
            status: "success",
            payload: req.body,
            headers: req.headers as any,
            error_message: null,
            lead_id: null,
            allocated_sheet_id: null,
          });
          alreadyLogged = true;
          
          return res.status(200).json({
            success: true,
            message: `No matching lead found for ${matchField}=${matchValue}. Ignored as configured.`,
            matched: false,
            action: "ignored"
          });
        } else if (noMatchAction === "log_only") {
          // Log the request but don't create a lead
          requestStatus = "success";
          await storage.createWebhookRequest({
            webhook_id: webhook.id,
            status: "success",
            payload: req.body,
            headers: req.headers as any,
            error_message: `No match found for ${matchField}=${matchValue}`,
            lead_id: null,
            allocated_sheet_id: targetSheetId,
          });
          alreadyLogged = true;
          
          return res.status(200).json({
            success: true,
            message: `No matching lead found for ${matchField}=${matchValue}. Logged for review.`,
            matched: false,
            action: "logged"
          });
        } else {
          // Default: create new lead
          lead = await createNewLead();
          createdLeadId = lead.id;
        }
      }

      // Determine the effective sheet for events and response
      // If we updated an existing lead without allocation, use the lead's current sheet
      const effectiveSheetId = targetSheetId || lead.sheet_id;
      
      // Update webhook's allocation counts and last allocated sheet (only if we have allocation rules)
      if (targetSheetId) {
        const allocationCounts = (webhook.allocation_counts as Record<string, Record<string, number>>) || {};
        const updatedAllocationCounts = { ...allocationCounts };
        if (!updatedAllocationCounts[conditionGroupKey]) {
          updatedAllocationCounts[conditionGroupKey] = {};
        }
        updatedAllocationCounts[conditionGroupKey][targetSheetId] = 
          (updatedAllocationCounts[conditionGroupKey][targetSheetId] || 0) + 1;
        
        await storage.updateCompanyWebhook(webhook.id, {
          last_allocated_sheet_id: targetSheetId,
          allocation_counts: updatedAllocationCounts,
        });
      }

      // Emit real-time events for frontend sync
      const io = app.get("io") as SocketIOServer;
      if (isDuplicate) {
        if (isTransferred && targetSheetId) {
          // Lead was transferred - emit delete from old sheet and create in new sheet
          if (oldSheetId) {
            io.to(`sheet:${oldSheetId}`).emit("lead_deleted", { id: lead.id });
          }
          io.to(`sheet:${targetSheetId}`).emit("lead_created", lead);
        } else {
          // Lead was updated in same sheet
          io.to(`sheet:${effectiveSheetId}`).emit("lead_updated", lead);
        }
      } else if (targetSheetId) {
        // New lead created
        io.to(`sheet:${targetSheetId}`).emit("lead_created", lead);
      }
      
      // Award PowerScore points for new lead creation (dropdown values set on create)
      if (!isDuplicate && webhookCompany && lead.custom_fields) {
        const sheetForScoring = await storage.getSheet(lead.sheet_id);
        if (sheetForScoring) {
          const customColumns = await storage.getCustomColumns(lead.sheet_id);
          const allDropdownKeys = getAllDropdownKeys(customColumns);
          const dropdownChanges: { columnKey: string; oldValue: string | null; newValue: string | null }[] = [];
          
          for (const columnKey of allDropdownKeys) {
            const newVal = lead.custom_fields[columnKey];
            if (newVal !== undefined && newVal !== null && newVal !== "") {
              dropdownChanges.push({
                columnKey,
                oldValue: null, // New lead - old value is always null
                newValue: newVal,
              });
            }
          }
          
          if (dropdownChanges.length > 0) {
            awardLeadUpdatePoints({
              userId: webhook.created_by_user_id,
              companyId: webhook.company_id,
              companyTimezone: webhookCompanyTimezone,
              leadId: lead.id,
            }, dropdownChanges).catch(err => console.error("PowerScore webhook lead creation error:", err));
          }
        }
      }

      // Trigger outgoing webhooks for lead creation (for new leads only, not updates)
      if (!isDuplicate && targetSheetId) {
        triggerOutgoingWebhooks("lead_created", {
          lead,
          sheetId: targetSheetId,
          companyId: webhook.company_id,
        });
      }

      requestStatus = "success";
      
      // Send webhook received notification
      const sheet = await storage.getSheet(effectiveSheetId);
      const leadName = lead.custom_fields?.name || lead.custom_fields?.full_name || "New Lead";
      notifyWebhookReceived(
        webhook.company_id,
        leadName,
        sheet?.name || "Sheet",
        effectiveSheetId,
        lead.id
      ).catch(err => {
        console.error("Failed to send webhook notification:", err);
      });
      
      // Build response message based on what happened
      let message = "Lead created successfully";
      let action = "created";
      
      if (isDuplicate) {
        if (isUpdateAdded) {
          action = "update_added";
          message = isTransferred 
            ? `Update added to existing lead and transferred to ${webhookCreator.name}`
            : "Update added to existing lead";
        } else if (isTransferred) {
          action = "updated_and_transferred";
          message = `Lead updated and transferred to ${webhookCreator.name}`;
        } else {
          action = "updated";
          message = "Lead updated successfully";
        }
      }
      
      res.status(201).json({ 
        success: true, 
        lead_id: lead.id,
        sheet_id: effectiveSheetId,
        is_duplicate: isDuplicate,
        is_transferred: isTransferred,
        is_update_added: isUpdateAdded,
        action,
        message
      });
    } catch (error: any) {
      console.error("Webhook ingestion error:", error);
      errorMessage = error.message;
      res.status(500).json({ error: errorMessage });
    } finally {
      // Log webhook request regardless of success or failure (unless already logged)
      if (webhook && !alreadyLogged) {
        try {
          await storage.createWebhookRequest({
            webhook_id: webhook.id,
            status: requestStatus,
            payload: req.body,
            headers: req.headers as any,
            error_message: errorMessage,
            lead_id: createdLeadId,
            allocated_sheet_id: targetSheetId || null,
          });
        } catch (logError: any) {
          console.error("Failed to log webhook request:", logError);
        }
      }
    }
  });

