  // ============================================================================
  // SYSTEM COLUMNS MIGRATION (Super Admin Only)
  // ============================================================================
  
  // Dry-run migration report - shows what values need to be migrated
  app.get("/api/admin/system-columns/migration-report", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      // Define migration mappings
      const migrations = [
        { from: 'Talked', to: 'Contacted', field: 'lead_status' },
        { from: 'Talking', to: 'Follow Up', field: 'lead_status' },
        { from: 'Invalid No', to: 'Invalid Data', field: 'lead_status' },
        { from: 'Not Eligible', to: 'Lost', field: 'lead_status', addLostReason: 'Eligibility Issue' },
      ];
      
      const results = [];
      
      for (const migration of migrations) {
        // Count leads with the old value
        const countResult = await storage.executeRawQuery(
          `SELECT COUNT(*) as count FROM leads 
           WHERE deleted_at IS NULL 
           AND custom_fields->>'${migration.field}' = $1`,
          [migration.from]
        );
        
        const count = parseInt(countResult.rows[0]?.count || '0', 10);
        
        // Get breakdown by company and sheet
        const breakdownResult = await storage.executeRawQuery(
          `SELECT 
            s.company_id,
            c.name as company_name,
            l.sheet_id,
            s.name as sheet_name,
            COUNT(*) as count
           FROM leads l
           JOIN sheets s ON l.sheet_id = s.id
           JOIN companies c ON s.company_id = c.id
           WHERE l.deleted_at IS NULL 
           AND l.custom_fields->>'${migration.field}' = $1
           GROUP BY s.company_id, c.name, l.sheet_id, s.name
           ORDER BY c.name, s.name`,
          [migration.from]
        );
        
        results.push({
          from: migration.from,
          to: migration.to,
          field: migration.field,
          addLostReason: migration.addLostReason || null,
          totalCount: count,
          breakdown: breakdownResult.rows.map((row: any) => ({
            companyId: row.company_id,
            companyName: row.company_name,
            sheetId: row.sheet_id,
            sheetName: row.sheet_name,
            count: parseInt(row.count, 10),
          })),
        });
      }
      
      const totalAffected = results.reduce((sum, r) => sum + r.totalCount, 0);
      
      res.json({
        status: 'dry_run',
        totalLeadsAffected: totalAffected,
        migrations: results,
        message: totalAffected > 0 
          ? `Found ${totalAffected} leads that need migration. Review the breakdown and call POST /api/admin/system-columns/execute-migration to proceed.`
          : 'No leads found that need migration.',
      });
    } catch (error: any) {
      console.error("Migration report error:", error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Execute migration - actually performs the value changes
  app.post("/api/admin/system-columns/execute-migration", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      const { confirm } = req.body;
      
      if (confirm !== true) {
        return res.status(400).json({ 
          error: "Migration requires confirmation", 
          message: "Send { confirm: true } to execute the migration" 
        });
      }
      
      // Define migration mappings
      const migrations = [
        { from: 'Talked', to: 'Contacted', field: 'lead_status' },
        { from: 'Talking', to: 'Follow Up', field: 'lead_status' },
        { from: 'Invalid No', to: 'Invalid Data', field: 'lead_status' },
        { from: 'Not Eligible', to: 'Lost', field: 'lead_status', addLostReason: 'Eligibility Issue' },
      ];
      
      const results = [];
      let totalMigrated = 0;
      
      for (const migration of migrations) {
        // Simple status change migrations
        if (!migration.addLostReason) {
          const updateResult = await storage.executeRawQuery(
            `UPDATE leads 
             SET custom_fields = jsonb_set(custom_fields::jsonb, '{${migration.field}}', $1::jsonb),
                 updated_at = NOW()
             WHERE deleted_at IS NULL 
             AND custom_fields->>'${migration.field}' = $2
             RETURNING id`,
            [JSON.stringify(migration.to), migration.from]
          );
          
          const migratedCount = updateResult.rows.length;
          totalMigrated += migratedCount;
          results.push({
            from: migration.from,
            to: migration.to,
            field: migration.field,
            migratedCount,
          });
        } else {
          // Migration that also sets lost_reason
          const updateResult = await storage.executeRawQuery(
            `UPDATE leads 
             SET custom_fields = jsonb_set(
               jsonb_set(custom_fields::jsonb, '{${migration.field}}', $1::jsonb),
               '{lost_reason}', $2::jsonb
             ),
             updated_at = NOW()
             WHERE deleted_at IS NULL 
             AND custom_fields->>'${migration.field}' = $3
             RETURNING id`,
            [JSON.stringify(migration.to), JSON.stringify(migration.addLostReason), migration.from]
          );
          
          const migratedCount = updateResult.rows.length;
          totalMigrated += migratedCount;
          results.push({
            from: migration.from,
            to: migration.to,
            field: migration.field,
            addedLostReason: migration.addLostReason,
            migratedCount,
          });
        }
      }
      
      // Audit log
      await storage.createAuditLog({
        user_id: req.userId!,
        company_id: null,
        action: "system_column_migration",
        model: "lead",
        model_id: null,
        payload: { totalMigrated, results },
      });
      
      res.json({
        status: 'completed',
        totalMigrated,
        migrations: results,
        message: `Successfully migrated ${totalMigrated} leads.`,
      });
    } catch (error: any) {
      console.error("Migration execution error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Generate sync report - shows what system values need to be synced to companies
  app.get("/api/admin/system-columns/sync-report", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      // Get all system value definitions
      const systemValues = await storage.getSystemValueDefinitions();
      if (systemValues.length === 0) {
        return res.json({
          status: 'dry_run',
          message: 'No system value definitions found. Run seed first.',
          companies: [],
        });
      }
      
      // Group system values by column_type
      const systemValuesByType: Record<string, string[]> = {};
      for (const sv of systemValues) {
        if (!systemValuesByType[sv.column_type]) {
          systemValuesByType[sv.column_type] = [];
        }
        systemValuesByType[sv.column_type].push(sv.value);
      }
      
      // Get all companies
      const companies = await storage.getAllCompanies();
      
      const companyReports = [];
      
      for (const company of companies) {
        const companyReport: {
          companyId: string;
          companyName: string;
          toMarkAsSystem: { columnKey: string; value: string; optionId: string }[];
          toCreate: { columnKey: string; value: string }[];
        } = {
          companyId: company.id,
          companyName: company.name,
          toMarkAsSystem: [],
          toCreate: [],
        };
        
        // Check each column type
        for (const [columnType, systemValuesList] of Object.entries(systemValuesByType)) {
          // Get existing dropdown options for this company and column type
          const existingOptions = await storage.getDropdownOptionsByColumn(company.id, columnType);
          const existingValueMap = new Map(existingOptions.map(opt => [opt.value.toLowerCase(), opt]));
          
          for (const systemValue of systemValuesList) {
            const existingOpt = existingValueMap.get(systemValue.toLowerCase());
            
            if (existingOpt) {
              // Value exists - check if it needs to be marked as system
              if (!existingOpt.is_system) {
                companyReport.toMarkAsSystem.push({
                  columnKey: columnType,
                  value: existingOpt.value,
                  optionId: existingOpt.id,
                });
              }
            } else {
              // Value doesn't exist - needs to be created
              companyReport.toCreate.push({
                columnKey: columnType,
                value: systemValue,
              });
            }
          }
        }
        
        // Only include companies that need changes
        if (companyReport.toMarkAsSystem.length > 0 || companyReport.toCreate.length > 0) {
          companyReports.push(companyReport);
        }
      }
      
      const totalToMark = companyReports.reduce((sum, c) => sum + c.toMarkAsSystem.length, 0);
      const totalToCreate = companyReports.reduce((sum, c) => sum + c.toCreate.length, 0);
      
      res.json({
        status: 'dry_run',
        systemValueDefinitions: Object.entries(systemValuesByType).map(([type, values]) => ({
          columnType: type,
          values,
          count: values.length,
        })),
        companiesAffected: companyReports.length,
        totalCompanies: companies.length,
        totalToMarkAsSystem: totalToMark,
        totalToCreate: totalToCreate,
        companies: companyReports,
        message: totalToMark + totalToCreate > 0
          ? `Found ${totalToMark} values to mark as system and ${totalToCreate} missing values to create across ${companyReports.length} companies. Call POST /api/admin/system-columns/sync-execute to proceed.`
          : 'All companies are up to date with system values.',
      });
    } catch (error: any) {
      console.error("Sync report error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Execute sync - marks matching values as system and creates missing ones
  app.post("/api/admin/system-columns/sync-execute", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      const { confirm } = req.body;
      
      if (confirm !== true) {
        return res.status(400).json({ 
          error: "Sync requires confirmation", 
          message: "Send { confirm: true } to execute the sync" 
        });
      }
      
      // Get all system value definitions
      const systemValues = await storage.getSystemValueDefinitions();
      if (systemValues.length === 0) {
        return res.status(400).json({
          error: 'No system value definitions found',
          message: 'Run seed first before syncing.',
        });
      }
      
      // Group system values by column_type
      const systemValuesByType: Record<string, string[]> = {};
      for (const sv of systemValues) {
        if (!systemValuesByType[sv.column_type]) {
          systemValuesByType[sv.column_type] = [];
        }
        systemValuesByType[sv.column_type].push(sv.value);
      }
      
      // Get all companies
      const companies = await storage.getAllCompanies();
      
      let totalMarked = 0;
      let totalCreated = 0;
      const companyResults = [];
      
      for (const company of companies) {
        let markedCount = 0;
        let createdCount = 0;
        
        // Check each column type
        for (const [columnType, systemValuesList] of Object.entries(systemValuesByType)) {
          // Get existing dropdown options for this company and column type
          const existingOptions = await storage.getDropdownOptionsByColumn(company.id, columnType);
          const existingValueMap = new Map(existingOptions.map(opt => [opt.value.toLowerCase(), opt]));
          
          // Get max order_index for new entries
          let maxOrderIndex = existingOptions.reduce((max, opt) => Math.max(max, opt.order_index), -1);
          
          for (const systemValue of systemValuesList) {
            const existingOpt = existingValueMap.get(systemValue.toLowerCase());
            
            if (existingOpt) {
              // Value exists - mark as system if not already
              if (!existingOpt.is_system) {
                await storage.updateDropdownOption(existingOpt.id, { is_system: true });
                markedCount++;
              }
            } else {
              // Value doesn't exist - create it
              maxOrderIndex++;
              await storage.createDropdownOption({
                company_id: company.id,
                sheet_id: null, // Company-wide
                column_key: columnType,
                value: systemValue,
                order_index: maxOrderIndex,
                is_system: true,
              });
              createdCount++;
            }
          }
        }
        
        if (markedCount > 0 || createdCount > 0) {
          companyResults.push({
            companyId: company.id,
            companyName: company.name,
            markedAsSystem: markedCount,
            created: createdCount,
          });
          totalMarked += markedCount;
          totalCreated += createdCount;
        }
      }
      
      // Audit log
      await storage.createAuditLog({
        user_id: req.userId!,
        company_id: null,
        action: "system_values_sync",
        model: "dropdown_option",
        model_id: null,
        payload: { totalMarked, totalCreated, companiesAffected: companyResults.length },
      });
      
      res.json({
        status: 'completed',
        totalMarkedAsSystem: totalMarked,
        totalCreated: totalCreated,
        companiesAffected: companyResults.length,
        companies: companyResults,
        message: `Successfully marked ${totalMarked} values as system and created ${totalCreated} new system values across ${companyResults.length} companies.`,
      });
    } catch (error: any) {
      console.error("Sync execution error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Preview sync for a single company - shows what columns and values will be created/updated
  app.get("/api/admin/system-columns/sync-preview/:companyId", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      const { companyId } = req.params;
      
      // Get the company
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }
      
      // Get all system value definitions (only active ones)
      const systemValues = await storage.getSystemValueDefinitions();
      const activeSystemValues = systemValues.filter(sv => !sv.deprecated_at);
      
      if (activeSystemValues.length === 0) {
        return res.status(400).json({
          error: 'No active system value definitions found',
          message: 'Run seed first before previewing sync.',
        });
      }
      
      // Group system values by column_type
      const systemValuesByType: Record<string, string[]> = {};
      for (const sv of activeSystemValues) {
        if (!systemValuesByType[sv.column_type]) {
          systemValuesByType[sv.column_type] = [];
        }
        systemValuesByType[sv.column_type].push(sv.value);
      }
      
      // Get company's existing custom columns
      const companyColumns = await storage.getCompanyColumns(companyId);
      const columnsByKey = new Map(companyColumns.map(col => [col.column_key, col]));
      
      // System column type to display name mapping
      const columnDisplayNames: Record<string, string> = {
        lead_status: "Lead Status",
        visit_status: "Visit Status",
        visit_type: "Visit Type",
        lost_reason: "Lost Reason",
      };
      
      const columnsToCreate: Array<{
        column_key: string;
        name: string;
        values: string[];
      }> = [];
      
      const columnsExisting: Array<{
        column_key: string;
        name: string;
        current_type: string;
        current_values: string[];
        values_to_add: string[];
        values_to_mark_system: string[];
        will_convert_to_dropdown: boolean;
        hidden_system_values: string[];
      }> = [];
      
      // Check each system column type
      for (const [columnType, systemValuesList] of Object.entries(systemValuesByType)) {
        const existingColumn = columnsByKey.get(columnType);
        
        if (!existingColumn) {
          // Column doesn't exist - needs to be created
          columnsToCreate.push({
            column_key: columnType,
            name: columnDisplayNames[columnType] || columnType,
            values: systemValuesList,
          });
        } else {
          // Column exists - check values
          const existingDropdownOptions = await storage.getDropdownOptionsByColumn(companyId, columnType);
          const existingValueMap = new Map(existingDropdownOptions.map(opt => [opt.value.toLowerCase(), opt]));
          
          const currentValues = existingDropdownOptions.map(opt => opt.value);
          const valuesToAdd: string[] = [];
          const valuesToMarkSystem: string[] = [];
          
          for (const systemValue of systemValuesList) {
            const existingOpt = existingValueMap.get(systemValue.toLowerCase());
            if (existingOpt) {
              // Value exists - check if needs to be marked as system
              if (!existingOpt.is_system) {
                valuesToMarkSystem.push(systemValue);
              }
            } else {
              // Value doesn't exist - needs to be added
              valuesToAdd.push(systemValue);
            }
          }
          
          // Get hidden system values from column config
          const config = existingColumn.config as { hidden_system_values?: string[] } | null;
          const hiddenSystemValues = config?.hidden_system_values || [];
          
          columnsExisting.push({
            column_key: columnType,
            name: existingColumn.name,
            current_type: existingColumn.type,
            current_values: currentValues,
            values_to_add: valuesToAdd,
            values_to_mark_system: valuesToMarkSystem,
            will_convert_to_dropdown: existingColumn.type !== 'dropdown',
            hidden_system_values: hiddenSystemValues,
          });
        }
      }
      
      const totalColumnsToCreate = columnsToCreate.length;
      const totalValuesToAdd = columnsExisting.reduce((sum, col) => sum + col.values_to_add.length, 0) +
                               columnsToCreate.reduce((sum, col) => sum + col.values.length, 0);
      const totalValuesToMarkSystem = columnsExisting.reduce((sum, col) => sum + col.values_to_mark_system.length, 0);
      const totalColumnsToConvert = columnsExisting.filter(col => col.will_convert_to_dropdown).length;
      const totalHiddenSystemValues = columnsExisting.reduce((sum, col) => sum + col.hidden_system_values.length, 0);
      
      res.json({
        company: {
          id: company.id,
          name: company.name,
        },
        columns_to_create: columnsToCreate,
        columns_existing: columnsExisting,
        summary: {
          columns_to_create: totalColumnsToCreate,
          columns_to_convert: totalColumnsToConvert,
          total_values_to_add: totalValuesToAdd,
          total_values_to_mark_system: totalValuesToMarkSystem,
          total_hidden_system_values: totalHiddenSystemValues,
          has_changes: totalColumnsToCreate > 0 || totalValuesToAdd > 0 || totalValuesToMarkSystem > 0 || totalColumnsToConvert > 0,
        },
      });
    } catch (error: any) {
      console.error("Sync preview error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Sync system values to a single company (with column creation)
  // Query param: ?force=true to bypass "already synced" checks and force update system_values
  app.post("/api/admin/system-columns/sync-company/:companyId", authMiddleware, requireSuperAdmin, async (req: AuthRequest, res) => {
    try {
      const { companyId } = req.params;
      const forceSync = req.query.force === 'true';
      
      // Get the company
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }
      
      // Get all system value definitions (only active ones)
      const systemValues = await storage.getSystemValueDefinitions();
      const activeSystemValues = systemValues.filter(sv => !sv.deprecated_at);
      
      if (activeSystemValues.length === 0) {
        return res.status(400).json({
          error: 'No active system value definitions found',
          message: 'Run seed first before syncing.',
        });
      }
      
      // Group system values by column_type
      const systemValuesByType: Record<string, string[]> = {};
      for (const sv of activeSystemValues) {
        if (!systemValuesByType[sv.column_type]) {
          systemValuesByType[sv.column_type] = [];
        }
        systemValuesByType[sv.column_type].push(sv.value);
      }
      
      // System column type to display name mapping
      const columnDisplayNames: Record<string, string> = {
        lead_status: "Lead Status",
        visit_status: "Visit Status",
        visit_type: "Visit Type",
        lost_reason: "Lost Reason",
      };
      
      // Get company's existing custom columns
      let companyColumns = await storage.getCompanyColumns(companyId);
      const columnsByKey = new Map(companyColumns.map(col => [col.column_key, col]));
      
      // Get max order_index for new columns
      let maxColumnOrderIndex = companyColumns.reduce((max, col) => Math.max(max, col.order_index), -1);
      
      let columnsCreated = 0;
      let markedCount = 0;
      let valuesCreated = 0;
      
      // Check each column type
      for (const [columnType, systemValuesList] of Object.entries(systemValuesByType)) {
        const existingColumn = columnsByKey.get(columnType);
        
        // Get existing config dropdown_options (for merging later)
        let existingConfigOptions: string[] = [];
        
        // Step 1: Create or update column
        if (!existingColumn) {
          // Create new column with system values in config
          maxColumnOrderIndex++;
          await storage.createCustomColumn({
            company_id: companyId,
            sheet_id: null, // Company-wide
            name: columnDisplayNames[columnType] || columnType,
            column_key: columnType,
            type: 'dropdown',
            config: { dropdown_options: [...systemValuesList], is_system_column: true, system_values: [...systemValuesList] },
            order_index: maxColumnOrderIndex,
          });
          columnsCreated++;
        } else {
          // Column exists - get existing dropdown options from config
          existingConfigOptions = (existingColumn.config as any)?.dropdown_options || [];
          
          // Merge: existing custom values + system values (avoid duplicates, case-insensitive)
          const existingLower = new Set(existingConfigOptions.map(v => v.toLowerCase()));
          const mergedOptions = [...existingConfigOptions];
          for (const sysVal of systemValuesList) {
            if (!existingLower.has(sysVal.toLowerCase())) {
              mergedOptions.push(sysVal);
            }
          }
          
          if (existingColumn.type !== 'dropdown') {
            // Convert non-dropdown to dropdown type with merged values
            await storage.updateCustomColumn(existingColumn.id, {
              type: 'dropdown',
              config: { ...existingColumn.config, dropdown_options: mergedOptions, is_system_column: true, system_values: [...systemValuesList] },
            });
          } else {
            // Already dropdown - update config to add is_system_column, system_values and merge values
            const currentConfig = existingColumn.config || {};
            const hasSystemValues = Array.isArray((currentConfig as any).system_values) && (currentConfig as any).system_values.length > 0;
            const needsUpdate = forceSync || 
                               !(currentConfig as any).is_system_column || 
                               !hasSystemValues ||
                               mergedOptions.length !== existingConfigOptions.length;
            
            if (needsUpdate) {
              await storage.updateCustomColumn(existingColumn.id, {
                config: { ...currentConfig, dropdown_options: mergedOptions, is_system_column: true, system_values: [...systemValuesList] },
              });
            }
          }
        }
        
        // Step 2: Sync dropdown_options table (for is_system tracking)
        const existingOptions = await storage.getDropdownOptionsByColumn(company.id, columnType);
        const existingValueMap = new Map(existingOptions.map(opt => [opt.value.toLowerCase(), opt]));
        
        // Get max order_index for new entries
        let maxOrderIndex = existingOptions.reduce((max, opt) => Math.max(max, opt.order_index), -1);
        
        for (const systemValue of systemValuesList) {
          const existingOpt = existingValueMap.get(systemValue.toLowerCase());
          
          if (existingOpt) {
            // Value exists - mark as system if not already
            if (!existingOpt.is_system) {
              await storage.updateDropdownOption(existingOpt.id, { is_system: true });
              markedCount++;
            }
          } else {
            // Value doesn't exist - create it
            maxOrderIndex++;
            await storage.createDropdownOption({
              company_id: company.id,
              sheet_id: null, // Company-wide
              column_key: columnType,
              value: systemValue,
              order_index: maxOrderIndex,
              is_system: true,
            });
            valuesCreated++;
          }
        }
      }
      
      // Audit log
      await storage.createAuditLog({
        user_id: req.userId!,
        company_id: company.id,
        action: "system_values_sync_company",
        model: "dropdown_option",
        model_id: company.id,
        payload: { columnsCreated, markedAsSystem: markedCount, valuesCreated },
      });
      
      res.json({
        status: 'completed',
        companyId: company.id,
        companyName: company.name,
        columnsCreated,
        markedAsSystem: markedCount,
        valuesCreated,
        message: `Successfully synced ${company.name}: created ${columnsCreated} columns, marked ${markedCount} values as system, and created ${valuesCreated} new system values.`,
      });
    } catch (error: any) {
      console.error("Sync company error:", error);
      res.status(500).json({ error: error.message });
    }
  });

