  // Update company settings
  app.patch("/api/admin/company/settings", authMiddleware, requireCompanyAdmin, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "No company context" });
      }
      
      const company = await storage.getCompany(req.companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }

      const incomingSettings = req.body.settings;
      if (!incomingSettings || typeof incomingSettings !== 'object') {
        return res.status(400).json({ error: "Settings must be an object" });
      }

      // Validate mobile_card_columns if present and actually changed
      // Only validate when it's different from current value (to avoid blocking saves when other settings change)
      const currentMobileCardColumns = company.settings?.mobile_card_columns;
      const incomingMobileCardColumns = incomingSettings.mobile_card_columns;
      const mobileCardColumnsChanged = JSON.stringify(incomingMobileCardColumns) !== JSON.stringify(currentMobileCardColumns);
      
      if (incomingMobileCardColumns !== undefined && mobileCardColumnsChanged) {
        if (!Array.isArray(incomingMobileCardColumns)) {
          return res.status(400).json({ error: "mobile_card_columns must be an array" });
        }
        if (!incomingMobileCardColumns.every((key: any) => typeof key === 'string')) {
          return res.status(400).json({ error: "mobile_card_columns must be an array of strings" });
        }
        // Validate that columns exist for this company
        const companyColumns = await storage.getCompanyColumns(req.companyId);
        const validColumnKeys = new Set(companyColumns.map(c => c.column_key));
        const invalidKeys = incomingMobileCardColumns.filter((key: string) => !validColumnKeys.has(key));
        if (invalidKeys.length > 0) {
          return res.status(400).json({ error: `Invalid column keys: ${invalidKeys.join(', ')}` });
        }
      }

      // Validate timezone if present
      if (incomingSettings.timezone !== undefined) {
        if (typeof incomingSettings.timezone !== 'string') {
          return res.status(400).json({ error: "timezone must be a string" });
        }
        // Validate and canonicalize timezone - only accept canonical IANA IDs
        // This ensures we don't store aliases like US/Eastern, Asia/Calcutta, etc.
        let canonicalTimezone: string;
        try {
          // Get canonical form using Intl.DateTimeFormat
          const formatter = new Intl.DateTimeFormat(undefined, { timeZone: incomingSettings.timezone });
          canonicalTimezone = formatter.resolvedOptions().timeZone;
        } catch {
          return res.status(400).json({ error: `Invalid timezone: ${incomingSettings.timezone}` });
        }
        
        // Explicitly reject GMT - it should be UTC
        if (canonicalTimezone === 'GMT' || incomingSettings.timezone.toUpperCase() === 'GMT') {
          return res.status(400).json({ 
            error: `Please use "UTC" instead of "GMT"` 
          });
        }
        
        // Known legacy aliases that should be rejected with their canonical alternatives
        const legacyAliasMap: Record<string, string> = {
          'Asia/Calcutta': 'Asia/Kolkata',
          'Asia/Katmandu': 'Asia/Kathmandu',
          'Europe/Kiev': 'Europe/Kyiv',
          'US/Eastern': 'America/New_York',
          'US/Central': 'America/Chicago',
          'US/Mountain': 'America/Denver',
          'US/Pacific': 'America/Los_Angeles',
          'US/Alaska': 'America/Anchorage',
          'US/Hawaii': 'Pacific/Honolulu',
          'Canada/Eastern': 'America/Toronto',
          'Canada/Central': 'America/Winnipeg',
          'Canada/Pacific': 'America/Vancouver',
          'Australia/ACT': 'Australia/Sydney',
          'Australia/NSW': 'Australia/Sydney',
          'Australia/Victoria': 'Australia/Melbourne',
          'Australia/Queensland': 'Australia/Brisbane',
          'Australia/West': 'Australia/Perth',
          'Pacific/Samoa': 'Pacific/Pago_Pago',
          'Etc/UTC': 'UTC',
        };
        
        // Auto-canonicalize known legacy aliases instead of rejecting them
        if (legacyAliasMap[incomingSettings.timezone]) {
          canonicalTimezone = legacyAliasMap[incomingSettings.timezone];
        }
        
        // Store the canonical form (handles case variations like "asia/kolkata" -> "Asia/Kolkata")
        incomingSettings.timezone = canonicalTimezone;
      }

      // Validate weekly_off_days if present
      if (incomingSettings.weekly_off_days !== undefined) {
        if (!Array.isArray(incomingSettings.weekly_off_days)) {
          return res.status(400).json({ error: "weekly_off_days must be an array" });
        }
        // Validate that values are valid day numbers (0-6)
        const validDays = new Set([0, 1, 2, 3, 4, 5, 6]);
        const invalidValues = incomingSettings.weekly_off_days.filter((day: any) => 
          typeof day !== 'number' || !validDays.has(day)
        );
        if (invalidValues.length > 0) {
          return res.status(400).json({ error: "weekly_off_days must contain only numbers 0-6 (Sunday-Saturday)" });
        }
        // Remove duplicates and sort
        incomingSettings.weekly_off_days = [...new Set(incomingSettings.weekly_off_days)].sort((a: number, b: number) => a - b);
      }

      // Merge new settings with existing settings (only allow known fields)
      const allowedFields = ['mobile_card_columns', 'timezone', 'site_visit_config', 'site_visited_config', 'quick_update_fields', 'add_lead_form_fields', 'auto_fill_rules', 'weekly_off_days', 'quality_check_settings', 'final_value_settings', 'whatsapp_webhook_id', 'lead_transfer_config'];
      const sanitizedSettings: Record<string, any> = {};
      for (const field of allowedFields) {
        if (incomingSettings[field] !== undefined) {
          sanitizedSettings[field] = incomingSettings[field];
        }
      }

      const updatedSettings = {
        ...company.settings,
        ...sanitizedSettings,
      };

      const updated = await storage.updateCompany(req.companyId, { settings: updatedSettings });

      // Audit log
      await storage.createAuditLog({
        user_id: req.userId!,
        company_id: req.companyId,
        action: "update",
        model: "company_settings",
        model_id: req.companyId,
        payload: sanitizedSettings,
      });

      res.json({ settings: updated?.settings || {} });
    } catch (error: any) {
      console.error("Update company settings error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // ============================================================================
  // REMARK QUALITY CHECK - Standard (Blacklist) + AI (Sarvam)
  // ============================================================================
  app.post("/api/sarvam/check-remark", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "No company context" });
      }

      const { remark } = req.body;
      if (!remark || typeof remark !== 'string') {
        return res.status(400).json({ error: "Remark is required" });
      }

      // Get company settings to check if quality check is enabled
      const company = await storage.getCompany(req.companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }

      const qualitySettings = company.settings?.quality_check_settings;
      const normalizedRemark = remark.trim().toLowerCase();
      
      // Step 1: Standard blacklist check (instant, no API)
      if (qualitySettings?.standard_check_enabled) {
        const blacklist = qualitySettings.blacklist_words || [];
        for (const word of blacklist) {
          if (normalizedRemark === word.toLowerCase()) {
            return res.json({ 
              meaningful: false,
              skipped: false,
              warning_message: qualitySettings.standard_warning_message || 
                "Your remark appears to be too brief. Please provide more details about the conversation."
            });
          }
        }
      }
      
      // Step 2: AI check (if enabled and has API key)
      if (!qualitySettings?.enabled) {
        return res.json({ meaningful: true, skipped: true, reason: "AI quality check not enabled" });
      }

      // Check if API key is configured
      const apiKey = qualitySettings.sarvam_api_key;
      if (!apiKey) {
        return res.json({ meaningful: true, skipped: true, reason: "Sarvam API key not configured" });
      }

      const acceptanceLevel = qualitySettings.acceptance_level || 'moderate';
      
      // Build prompt based on acceptance level
      let levelDescription = '';
      switch (acceptanceLevel) {
        case 'lenient':
          levelDescription = 'Only reject single words like "ok", "done", "called", "yes", "no" or empty-like responses. Allow short but informative remarks.';
          break;
        case 'moderate':
          levelDescription = 'Reject lazy responses like "ok", "done", "called", "will call back", "no response" and require at least some specific information about the conversation outcome or next step.';
          break;
        case 'strict':
          levelDescription = 'Require detailed conversation summaries with specific information about what was discussed, customer response, and clear next steps. Reject anything vague or generic.';
          break;
      }

      const systemPrompt = `You are a CRM quality checker for a sales team. Your job is to determine if a lead update remark is meaningful or lazy/empty.

${levelDescription}

The remark may be in English, Hindi, Odia, Telugu, Tamil, Bengali, Kannada, Malayalam, Marathi, Gujarati, Punjabi or a mix. Understand the meaning regardless of language.

Respond with ONLY one word: "meaningful" or "not_meaningful"`;

      const userPrompt = `Remark: "${remark}"`;

      // Call Sarvam AI API with 2000ms timeout (increased from 500ms for reliability)
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000);

      try {
        const response = await fetch('https://api.sarvam.ai/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${apiKey}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: 'sarvam-m',
            messages: [
              { role: 'system', content: systemPrompt },
              { role: 'user', content: userPrompt }
            ],
            temperature: 0.1,
            max_tokens: 10
          }),
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          console.error('Sarvam API error:', response.status, await response.text());
          // On API error, allow the remark (fail-open)
          return res.json({ meaningful: true, skipped: true, reason: "API error" });
        }

        const data = await response.json();
        const answer = data.choices?.[0]?.message?.content?.toLowerCase()?.trim() || '';
        
        const isMeaningful = !answer.includes('not_meaningful');
        
        res.json({ 
          meaningful: isMeaningful,
          skipped: false,
          warning_message: !isMeaningful ? (qualitySettings.warning_message || "Please add more details about the conversation or outcome.") : undefined
        });
      } catch (fetchError: any) {
        clearTimeout(timeoutId);
        // On timeout or network error, allow the remark (fail-open)
        console.log('Sarvam API timeout or error:', fetchError.message);
        return res.json({ meaningful: true, skipped: true, reason: "Timeout or network error" });
      }
    } catch (error: any) {
      console.error("Check remark error:", error);
      // On any error, allow the remark (fail-open)
      res.json({ meaningful: true, skipped: true, reason: "Server error" });
    }
  });

