  // Company-wide batch AI rating - processes all leads with 3+ followups that haven't been rated
  app.post("/api/ai-ratings/batch-all", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "No company context" });
      }

      if (req.userRole !== 'super_admin' && req.userRole !== 'company_admin') {
        return res.status(403).json({ error: "Admin access required" });
      }

      const requestedLimit = Math.min(Math.max(1, Number(req.body.limit) || 100), 100);
      const startTime = Date.now();
      const MAX_PROCESSING_TIME_MS = 25000; // 25 seconds max to leave buffer before timeout

      // Get company for API key
      const company = await storage.getCompany(req.companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }

      const apiKey = process.env.SARVAM_API_KEY || company.settings?.quality_check_settings?.sarvam_api_key;
      if (!apiKey) {
        return res.status(400).json({ error: "Sarvam API key not configured. Please add it in Quality Check Settings or as SARVAM_API_KEY environment variable." });
      }

      // Bulk query: Get leads with 3+ followups that need rating across all sheets
      // Uses subquery to filter by followup count directly in SQL for efficiency
      const STALENESS_HOURS = 24;
      const stalenessThreshold = new Date(Date.now() - (STALENESS_HOURS * 60 * 60 * 1000));
      
      // Use raw SQL query to include followup count filter directly
      const eligibleLeadsResult = await db.execute(sql`
        SELECT l.id as "leadId", l.sheet_id as "sheetId"
        FROM leads l
        INNER JOIN sheets s ON l.sheet_id = s.id
        WHERE s.company_id = ${req.companyId}
          AND l.deleted_at IS NULL
          AND s.deleted_at IS NULL
          AND (
            l.ai_rating IS NULL
            OR l.ai_rating = 'New'
            OR l.ai_rating_updated_at IS NULL
            OR l.ai_rating_updated_at < ${stalenessThreshold}
          )
          AND (SELECT COUNT(*) FROM lead_updates WHERE lead_id = l.id) >= 3
        LIMIT ${requestedLimit}
      `);
      
      const leadsToRate = (eligibleLeadsResult.rows || []) as Array<{ leadId: string; sheetId: string }>;

      // Process ratings and emit socket updates with time guard
      const results: Array<{ leadId: string; sheetId: string; success: boolean; rating?: string; score?: number }> = [];
      let timedOut = false;
      
      for (const { leadId, sheetId } of leadsToRate) {
        // Check elapsed time before processing each lead
        if (Date.now() - startTime > MAX_PROCESSING_TIME_MS) {
          timedOut = true;
          break;
        }
        
        try {
          const result = await calculateAndUpdateLeadRating(leadId, apiKey);
          if (result && result.rating && result.score !== undefined) {
            // Emit socket update for real-time UI refresh only with valid payload
            emitAIRatingUpdate({
              leadId,
              sheetId,
              companyId: req.companyId,
              rating: result.rating,
              score: result.score,
              summary: result.summary || '',
              details: result.details || {},
              updatedAt: new Date().toISOString()
            });
            results.push({ 
              leadId, 
              sheetId,
              success: true, 
              rating: result.rating,
              score: result.score
            });
          } else {
            results.push({ leadId, sheetId, success: false });
          }
          // Small delay between API calls to avoid rate limiting
          await new Promise(r => setTimeout(r, 300));
        } catch (err) {
          console.error(`Batch rating error for lead ${leadId}:`, err);
          results.push({ leadId, sheetId, success: false });
        }
      }

      const successful = results.filter(r => r.success).length;
      
      // Get total count of leads still needing rating (for progress info)
      const totalRemainingResult = await db.execute(sql`
        SELECT COUNT(*) as count
        FROM leads l
        INNER JOIN sheets s ON l.sheet_id = s.id
        WHERE s.company_id = ${req.companyId}
          AND l.deleted_at IS NULL
          AND s.deleted_at IS NULL
          AND (
            l.ai_rating IS NULL
            OR l.ai_rating = 'New'
            OR l.ai_rating_updated_at IS NULL
            OR l.ai_rating_updated_at < ${stalenessThreshold}
          )
          AND (SELECT COUNT(*) FROM lead_updates WHERE lead_id = l.id) >= 3
      `);
      const totalRemaining = Number((totalRemainingResult.rows?.[0] as any)?.count || 0);
      
      res.json({
        message: totalRemaining > 0
          ? `Processed ${results.length} leads (${successful} successful). ${totalRemaining} leads remaining - run again to continue.`
          : `Processed ${results.length} leads, ${successful} successfully rated. All eligible leads have been rated!`,
        processed: results.length,
        successful,
        remaining: totalRemaining,
        timedOut,
        results
      });
    } catch (error: any) {
      console.error("Company batch AI rating error:", error);
      res.status(500).json({ error: "Failed to batch calculate ratings", details: error.message });
    }
  });

