  // Generate sample webhook payload based on company's custom columns
  // IMPORTANT: This must come BEFORE the /:id route to avoid matching "sample-payload" as an id
  app.get("/api/admin/company/webhooks/sample-payload", authMiddleware, requireCompanyAdmin, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      // Get company's custom columns
      const customColumns = await storage.getCompanyColumns(req.companyId);
      
      // Build sample payload with fixed fields + custom fields
      const samplePayload: Record<string, string> = {};
      
      // Add fixed CRM fields with labels - these are the core system fields
      const fixedFields = [
        { key: 'name', label: 'Full Name', type: 'text' },
        { key: 'mobile_no', label: 'Mobile No', type: 'text' },
        { key: 'whatsapp', label: 'WhatsApp No', type: 'text' },
        { key: 'lang', label: 'Language', type: 'text' },
        { key: 'occupation', label: 'Occupation', type: 'text' },
        { key: 'qualification', label: 'Qualification', type: 'text' },
        { key: 'lead_date', label: 'Lead Date', type: 'date' },
        { key: 'lead_time', label: 'Lead Time', type: 'text' },
        { key: 'lead_status', label: 'Lead Status', type: 'dropdown' },
        { key: 'visit_status', label: 'Visit Status', type: 'dropdown' },
      ];
      
      // Helper function to normalize field key for comparison
      // Strips ALL non-alphanumeric characters for robust matching
      const normalizeKey = (key: string): string => {
        return key.toLowerCase().trim().replace(/[^a-z0-9]/g, '');
      };
      
      // Create a set of normalized fixed field keys and all their aliases
      // This comprehensive list prevents any duplicates from appearing
      const normalizedFixedKeys = new Set([
        // Full Name variations
        'name', 'fullname', 'fname', 'firstname', 'lastname',
        // Mobile variations
        'mobileno', 'mobile', 'phone', 'phoneno', 'phonenumber', 'mobilenumber', 'mob',
        // WhatsApp variations
        'whatsapp', 'whatsappno', 'whatsappnumber', 'wa', 'wano',
        // Language variations
        'lang', 'language',
        // Occupation variations
        'occupation', 'job', 'work',
        // Qualification variations
        'qualification', 'education', 'degree',
        // Date/Time variations
        'leaddate', 'date', 'createddate',
        'leadtime', 'time', 'createdtime',
        // Status variations
        'leadstatus', 'status',
        'visitstatus', 'visit',
      ]);
      
      fixedFields.forEach(field => {
        samplePayload[field.key] = generateMockValue(field.key, field.type);
      });
      
      // Add custom columns from the company, but filter out any that duplicate fixed fields
      const customFieldOptions: Array<{ key: string; label: string }> = [];
      customColumns.forEach(column => {
        const fieldKey = column.column_key;
        const normalizedKey = normalizeKey(fieldKey);
        
        // Skip if this normalized key matches any fixed field or alias
        if (normalizedFixedKeys.has(normalizedKey)) {
          return;
        }
        
        samplePayload[fieldKey] = generateMockValue(fieldKey, column.type);
        customFieldOptions.push({ key: fieldKey, label: column.name });
      });
      
      // Return both sample payload and available field options (fixed + custom, deduplicated)
      res.json({
        samplePayload,
        availableFields: [
          ...fixedFields.map(f => ({ key: f.key, label: f.label })),
          ...customFieldOptions
        ]
      });
    } catch (error: any) {
      console.error("Generate sample payload error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get webhook details with mappings and allocation rules
