  // GET /api/company/reports/:reportId/data - Get report data (calculations and aggregations)
  app.get("/api/company/reports/:reportId/data", authMiddleware, async (req: AuthRequest, res) => {
    try {
      const report = await storage.getReport(req.params.reportId);
      if (!report) {
        return res.status(404).json({ error: "Report not found" });
      }

      // Verify company access
      if (req.userRole === "company_admin" && report.company_id !== req.companyId) {
        return res.status(403).json({ error: "Cannot access reports from other companies" });
      }
      
      // Get company timezone for date-based groupings
      const company = await storage.getCompany(report.company_id);
      const companyTimezone = getCompanyTimezone(company);

      // Get filter sheet IDs from query parameters (if provided)
      let filterSheetIds: string[] | null = null;
      if (req.query.sheet_ids) {
        const rawSheetIds = req.query.sheet_ids;
        if (Array.isArray(rawSheetIds)) {
          filterSheetIds = rawSheetIds.filter((id): id is string => typeof id === 'string');
        } else if (typeof rawSheetIds === 'string') {
          filterSheetIds = [rawSheetIds];
        }
      }

      // Get accessible sheet IDs for the user
      let accessibleSheetIds: string[] = [];
      if (req.userRole === "company_admin" || req.userRole === "super_admin") {
        // Admins can access all sheets (or filter by specific sheets if provided)
        // Super admins don't have companyId, so use report's company_id
        const companyId = req.companyId || report.company_id;
        
        if (filterSheetIds) {
          // Get all company sheets (excluding deleted)
          const companySheets = await storage.getSheetsByCompanyId(companyId);
          const activeCompanySheetIds = companySheets.filter(s => !s.deleted_at).map(s => s.id);
          // Only include requested sheets that exist in the company and are not deleted
          accessibleSheetIds = filterSheetIds.filter(sheetId => activeCompanySheetIds.includes(sheetId));
        } else {
          // No filter - use report's configured sheets or all company sheets (excluding deleted)
          if (Array.isArray(report.sheet_ids) && report.sheet_ids.length > 0) {
            // Filter out any deleted sheets from report configuration
            const companySheets = await storage.getSheetsByCompanyId(companyId);
            const activeSheetIds = companySheets.filter(s => !s.deleted_at).map(s => s.id);
            accessibleSheetIds = report.sheet_ids.filter((id: string) => activeSheetIds.includes(id));
          } else {
            accessibleSheetIds = (await storage.getSheetsByCompanyId(companyId))
              .filter(s => !s.deleted_at)
              .map(s => s.id);
          }
        }
      } else {
        // Regular users can only access sheets they have permissions for
        const userSheets = await storage.getSheetsByUserId(req.userId!);
        // Exclude deleted sheets from user's accessible sheets
        const userSheetIds = userSheets.filter(s => !s.deleted_at).map(s => s.id);
        
        if (filterSheetIds) {
          // Filter to only include requested sheets that the user has access to
          accessibleSheetIds = filterSheetIds.filter(sheetId => userSheetIds.includes(sheetId));
        } else {
          // No filter - use report's configured sheets intersected with user's sheets
          const reportSheetIds = Array.isArray(report.sheet_ids) ? report.sheet_ids : [];
          accessibleSheetIds = reportSheetIds.filter(sheetId => userSheetIds.includes(sheetId));
        }
        
        if (accessibleSheetIds.length === 0) {
          return res.status(403).json({ error: "No access to sheets in this report" });
        }
      }

      // Fetch all leads from accessible sheets (excluding soft-deleted)
      // Check if we need special column resolution (sheet_name or user_name)
      // Note: "sheet" is legacy, "sheet_name" is preferred - both work identically
      const xAxis = report.config?.x_axis;
      const columnField = report.config?.column_field;
      const rowFields = report.config?.row_fields || [];
      const needsSheetName = xAxis === "sheet_name" || xAxis === "sheet" || 
                             columnField === "sheet_name" || columnField === "sheet" || 
                             rowFields.includes("sheet_name") || rowFields.includes("sheet");
      const needsUserName = xAxis === "user_name" || columnField === "user_name" || rowFields.includes("user_name");
      
      // Build sheet ID to name map
      const sheetNameMap: Record<string, string> = {};
      if (needsSheetName) {
        const companyId = req.companyId || report.company_id;
        const sheets = await storage.getSheetsByCompanyId(companyId);
        sheets.forEach(s => { sheetNameMap[s.id] = s.name; });
      }
      
      // Build user ID to name map
      const userNameMap: Record<string, string> = {};
      if (needsUserName) {
        const companyId = req.companyId || report.company_id;
        const users = await storage.getUsersByCompanyId(companyId);
        users.forEach(u => { userNameMap[u.id] = u.name || u.email; });
      }
      
      const allLeads = (await Promise.all(
        accessibleSheetIds.map(async (sheetId) => {
          const leads = await storage.getLeadsBySheetId(sheetId);
          // Add derived fields to each lead
          return leads.map(l => {
            const enrichedLead: any = { ...l };
            // Add sheet_name field
            if (needsSheetName && sheetNameMap[sheetId]) {
              enrichedLead.sheet_name = sheetNameMap[sheetId];
              enrichedLead.sheet = sheetNameMap[sheetId]; // Also support legacy "sheet" field
            }
            // Add user_name field (from assigned_to user ID)
            if (needsUserName && l.assigned_to && userNameMap[l.assigned_to]) {
              enrichedLead.user_name = userNameMap[l.assigned_to];
            } else if (needsUserName) {
              enrichedLead.user_name = "Unassigned";
            }
            return enrichedLead;
          });
        })
      )).flat().filter(lead => {
        // Exclude soft-deleted leads
        if (lead.deleted_at) return false;
        
        // For user reports, regular users see all leads from their accessible sheets
        // Sheet-level access control is already applied above via accessibleSheetIds
        // (which is intersected with user's permitted sheets for non-admin users)
        
        return true;
      });

      // Apply date range filter (from query params or report config)
      // IMPORTANT: Interpret dates in company timezone and convert to UTC for filtering
      let filteredLeads = allLeads;
      const startDateStr = req.query.start_date as string || report.config?.date_range?.start;
      const endDateStr = req.query.end_date as string || report.config?.date_range?.end;
      
      if (startDateStr || endDateStr) {
        // Parse and validate dates (supports ISO and dd/MM/yy formats)
        let startDateLocal: Date | null = null;
        let endDateLocal: Date | null = null;
        
        if (startDateStr) {
          startDateLocal = parseDateFlexible(startDateStr);
          if (!startDateLocal) {
            return res.status(422).json({ 
              error: "Invalid start date format. Use ISO format (YYYY-MM-DD) or dd/MM/yy." 
            });
          }
        }
        
        if (endDateStr) {
          endDateLocal = parseDateFlexible(endDateStr);
          if (!endDateLocal) {
            return res.status(422).json({ 
              error: "Invalid end date format. Use ISO format (YYYY-MM-DD) or dd/MM/yy." 
            });
          }
        }
        
        // Validate start <= end (using local dates for comparison)
        if (startDateLocal && endDateLocal && startDateLocal > endDateLocal) {
          return res.status(422).json({ 
            error: "Start date must be before or equal to end date" 
          });
        }
        
        // Convert dates from company timezone to UTC for database comparison
        // Example: "2025-12-07" in Asia/Kolkata (IST) becomes:
        //   Start: 2025-12-06T18:30:00Z (midnight IST = 6:30 PM previous day UTC)
        //   End: 2025-12-07T18:29:59Z (11:59:59 PM IST = 6:29:59 PM UTC)
        let startDateUtc: Date | null = null;
        let endDateUtc: Date | null = null;
        
        if (startDateLocal) {
          // Build timezone-aware string for start of day, then convert to UTC
          const year = startDateLocal.getFullYear();
          const month = String(startDateLocal.getMonth() + 1).padStart(2, '0');
          const day = String(startDateLocal.getDate()).padStart(2, '0');
          const startOfDayStr = `${year}-${month}-${day}T00:00:00`;
          startDateUtc = fromZonedTime(startOfDayStr, companyTimezone);
        }
        
        if (endDateLocal) {
          // Build timezone-aware string for end of day, then convert to UTC
          const year = endDateLocal.getFullYear();
          const month = String(endDateLocal.getMonth() + 1).padStart(2, '0');
          const day = String(endDateLocal.getDate()).padStart(2, '0');
          const endOfDayStr = `${year}-${month}-${day}T23:59:59.999`;
          endDateUtc = fromZonedTime(endOfDayStr, companyTimezone);
        }
        
        filteredLeads = allLeads.filter(lead => {
          const leadDate = new Date(lead.created_at);
          if (startDateUtc && leadDate < startDateUtc) return false;
          if (endDateUtc && leadDate > endDateUtc) return false;
          return true;
        });
      }

      // Generate data based on report type
      let data: any;
      switch (report.report_type) {
        case "lead_status_distribution":
          data = generateLeadStatusDistribution(filteredLeads);
          break;
        case "leads_over_time":
          data = generateLeadsOverTime(filteredLeads, report.config);
          break;
        case "lead_source_analysis":
          data = generateLeadSourceAnalysis(filteredLeads, report.config);
          break;
        case "conversion_rate":
          data = generateConversionRate(filteredLeads);
          break;
        case "user_performance":
          data = await generateUserPerformance(filteredLeads, storage);
          break;
        case "lead_age_distribution":
          data = generateLeadAgeDistribution(filteredLeads);
          break;
        case "custom_field_analysis":
          data = generateCustomFieldAnalysis(filteredLeads, report.config);
          break;
        case "custom":
          data = generateDynamicReport(filteredLeads, report.config, companyTimezone);
          break;
        case "pivot_table":
          data = generatePivotTable(filteredLeads, report.config, companyTimezone);
          break;
        default:
          return res.status(400).json({ error: "Unknown report type" });
      }

      res.json({
        report,
        data,
        total_leads: filteredLeads.length,
        generated_at: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error("Get report data error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/company/reports/:reportId/drilldown - Get leads for a specific data point
  app.get("/api/company/reports/:reportId/drilldown", authMiddleware, async (req: AuthRequest, res) => {
    try {
      const report = await storage.getReport(req.params.reportId);
      if (!report) {
        return res.status(404).json({ error: "Report not found" });
      }

      // Verify company access
      if (req.userRole === "company_admin" && report.company_id !== req.companyId) {
        return res.status(403).json({ error: "Cannot access reports from other companies" });
      }

      // Parse filters from query params
      let filters: Record<string, any> = {};
      if (req.query.filters) {
        try {
          filters = JSON.parse(req.query.filters as string);
        } catch (e) {
          return res.status(400).json({ error: "Invalid filters format" });
        }
      }

      // Parse pagination
      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 50;
      const offset = (page - 1) * limit;

      // Get filter sheet IDs from query parameters (if provided)
      let filterSheetIds: string[] | null = null;
      if (req.query.sheet_ids) {
        const rawSheetIds = req.query.sheet_ids;
        if (Array.isArray(rawSheetIds)) {
          filterSheetIds = rawSheetIds.filter((id): id is string => typeof id === 'string');
        } else if (typeof rawSheetIds === 'string') {
          filterSheetIds = [rawSheetIds];
        }
      }

      // Get accessible sheet IDs for the user
      let accessibleSheetIds: string[] = [];
      if (req.userRole === "company_admin" || req.userRole === "super_admin") {
        const companyId = req.companyId || report.company_id;
        
        if (filterSheetIds) {
          const companySheets = await storage.getSheetsByCompanyId(companyId);
          // Exclude deleted sheets
          const activeCompanySheetIds = companySheets.filter(s => !s.deleted_at).map(s => s.id);
          accessibleSheetIds = filterSheetIds.filter(sheetId => activeCompanySheetIds.includes(sheetId));
        } else {
          if (Array.isArray(report.sheet_ids) && report.sheet_ids.length > 0) {
            // Filter out any deleted sheets from report configuration
            const companySheets = await storage.getSheetsByCompanyId(companyId);
            const activeSheetIds = companySheets.filter(s => !s.deleted_at).map(s => s.id);
            accessibleSheetIds = report.sheet_ids.filter((id: string) => activeSheetIds.includes(id));
          } else {
            accessibleSheetIds = (await storage.getSheetsByCompanyId(companyId))
              .filter(s => !s.deleted_at)
              .map(s => s.id);
          }
        }
      } else {
        const userSheets = await storage.getSheetsByUserId(req.userId!);
        // Exclude deleted sheets
        const userSheetIds = userSheets.filter(s => !s.deleted_at).map(s => s.id);
        
        if (filterSheetIds) {
          accessibleSheetIds = filterSheetIds.filter(sheetId => userSheetIds.includes(sheetId));
        } else {
          const reportSheetIds = Array.isArray(report.sheet_ids) ? report.sheet_ids : [];
          accessibleSheetIds = reportSheetIds.filter(sheetId => userSheetIds.includes(sheetId));
        }
        
        if (accessibleSheetIds.length === 0) {
          return res.status(403).json({ error: "No access to sheets in this report" });
        }
      }

      // Fetch all leads from accessible sheets (excluding soft-deleted)
      // Check if filters include special columns that need lookup
      const needsSheetName = filters.sheet_name !== undefined || filters.sheet !== undefined;
      const needsUserName = filters.user_name !== undefined;
      
      // Build sheet ID to name map (only active sheets)
      const sheetNameMap: Record<string, string> = {};
      const sheetIdByName: Record<string, string> = {};
      if (needsSheetName) {
        const companyId = req.companyId || report.company_id;
        const sheets = await storage.getSheetsByCompanyId(companyId);
        // Only include active (non-deleted) sheets in the map
        sheets.filter(s => !s.deleted_at).forEach(s => { 
          sheetNameMap[s.id] = s.name; 
          sheetIdByName[s.name] = s.id;
        });
      }
      
      // Build user ID to name map
      const userNameMap: Record<string, string> = {};
      const userIdByName: Record<string, string> = {};
      if (needsUserName) {
        const companyId = req.companyId || report.company_id;
        const users = await storage.getUsersByCompanyId(companyId);
        users.forEach(u => { 
          userNameMap[u.id] = u.name || u.email; 
          userIdByName[u.name || u.email] = u.id;
        });
      }
      
      const allLeads = (await Promise.all(
        accessibleSheetIds.map(async sheetId => {
          const leads = await storage.getLeadsBySheetId(sheetId);
          // Enrich leads with derived fields for filtering
          return leads.map(l => {
            const enrichedLead: any = { ...l };
            if (needsSheetName && sheetNameMap[sheetId]) {
              enrichedLead.sheet_name = sheetNameMap[sheetId];
              enrichedLead.sheet = sheetNameMap[sheetId];
            }
            if (needsUserName) {
              enrichedLead.user_name = l.assigned_to && userNameMap[l.assigned_to] 
                ? userNameMap[l.assigned_to] 
                : "Unassigned";
            }
            return enrichedLead;
          });
        })
      )).flat().filter(lead => !lead.deleted_at);

      // Helper to check if filter value is a formatted date and lead value is ISO datetime
      // Returns true if they represent the same period (day, week, month, quarter, year)
      const compareDateValues = (filterValue: string, leadValue: string): boolean => {
        // Check if lead value is ISO datetime or date format
        if (typeof leadValue !== 'string' || !leadValue.match(/^\d{4}-\d{2}-\d{2}/)) {
          return false;
        }
        
        const monthMap: Record<string, number> = {
          "Jan": 0, "Feb": 1, "Mar": 2, "Apr": 3, "May": 4, "Jun": 5,
          "Jul": 6, "Aug": 7, "Sep": 8, "Oct": 9, "Nov": 10, "Dec": 11,
          "January": 0, "February": 1, "March": 2, "April": 3, "May": 4, "June": 5,
          "July": 6, "August": 7, "September": 8, "October": 9, "November": 10, "December": 11
        };
        
        const leadDate = new Date(leadValue);
        
        // Match "Dec 13, 2025" or "December 13, 2025" format (day grouping)
        const dayMatch = filterValue.match(/^(\w{3,9})\s+(\d{1,2}),\s+(\d{4})$/);
        if (dayMatch) {
          const [, mon, day, year] = dayMatch;
          if (monthMap[mon] !== undefined) {
            return leadDate.getFullYear() === parseInt(year) &&
                   leadDate.getMonth() === monthMap[mon] &&
                   leadDate.getDate() === parseInt(day);
          }
        }
        
        // Match "12 Dec 2025" format (day first)
        const dayFirstMatch = filterValue.match(/^(\d{1,2})\s+(\w{3,9})\s+(\d{4})$/);
        if (dayFirstMatch) {
          const [, day, mon, year] = dayFirstMatch;
          if (monthMap[mon] !== undefined) {
            return leadDate.getFullYear() === parseInt(year) &&
                   leadDate.getMonth() === monthMap[mon] &&
                   leadDate.getDate() === parseInt(day);
          }
        }
        
        // Match "2025-12-13" ISO date format
        const isoMatch = filterValue.match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (isoMatch) {
          const [, year, month, day] = isoMatch;
          return leadDate.getFullYear() === parseInt(year) &&
                 leadDate.getMonth() === parseInt(month) - 1 &&
                 leadDate.getDate() === parseInt(day);
        }
        
        // Match "Dec 2025" or "December 2025" format (month grouping)
        const monthMatch = filterValue.match(/^(\w{3,9})\s+(\d{4})$/);
        if (monthMatch) {
          const [, mon, year] = monthMatch;
          if (monthMap[mon] !== undefined) {
            return leadDate.getFullYear() === parseInt(year) &&
                   leadDate.getMonth() === monthMap[mon];
          }
        }
        
        // Match "Week X, YYYY" format (week grouping)
        const weekMatch = filterValue.match(/^Week\s+(\d+),\s+(\d{4})$/);
        if (weekMatch) {
          const [, week, year] = weekMatch;
          // Calculate week of year for lead date
          const startOfYear = new Date(leadDate.getFullYear(), 0, 1);
          const days = Math.floor((leadDate.getTime() - startOfYear.getTime()) / (24 * 60 * 60 * 1000));
          const leadWeek = Math.ceil((days + startOfYear.getDay() + 1) / 7);
          return leadDate.getFullYear() === parseInt(year) && leadWeek === parseInt(week);
        }
        
        // Match "Week of Dec 08, 2025" format (week start date format)
        const weekOfMatch = filterValue.match(/^Week of (\w{3,9})\s+(\d{1,2}),\s+(\d{4})$/);
        if (weekOfMatch) {
          const [, mon, day, year] = weekOfMatch;
          if (monthMap[mon] !== undefined) {
            // Week start date - lead date should fall within 7 days of week start
            const weekStart = new Date(parseInt(year), monthMap[mon], parseInt(day));
            const weekEnd = new Date(weekStart.getTime() + 7 * 24 * 60 * 60 * 1000);
            return leadDate >= weekStart && leadDate < weekEnd;
          }
        }
        
        // Match "Q1 2025" format (quarter grouping)
        const quarterMatch = filterValue.match(/^Q(\d)\s+(\d{4})$/);
        if (quarterMatch) {
          const [, quarter, year] = quarterMatch;
          const leadQuarter = Math.floor(leadDate.getMonth() / 3) + 1;
          return leadDate.getFullYear() === parseInt(year) && leadQuarter === parseInt(quarter);
        }
        
        // Match pure year "2025" format (year grouping)
        if (/^\d{4}$/.test(filterValue)) {
          return leadDate.getFullYear() === parseInt(filterValue);
        }
        
        return false;
      };
      
      // Apply filters
      let filteredLeads = allLeads.filter(lead => {
        for (const [key, value] of Object.entries(filters)) {
          // Check direct properties (including enriched sheet_name, user_name), or custom_fields
          const leadValue = lead[key as keyof typeof lead] ?? lead.custom_fields?.[key];
          
          // Handle null/undefined comparisons - also treat "Unknown" as matching null/empty values
          const isNullFilter = value === null || value === "null" || value === "Unknown";
          const isNullValue = leadValue === null || leadValue === undefined || leadValue === "";
          
          if (isNullFilter) {
            // Filter wants null/Unknown values - only include leads with null/empty values
            if (!isNullValue) {
              return false;
            }
          } else if (isNullValue) {
            // Filter wants a specific value but lead has null - doesn't match
            return false;
          } else if (leadValue !== value) {
            // Direct comparison failed - try date comparison for datetime fields
            if (typeof value === 'string' && typeof leadValue === 'string' && compareDateValues(value, leadValue)) {
              // Date comparison matched - continue to next filter
              continue;
            }
            return false;
          }
        }
        return true;
      });

      // Apply date range filter if configured
      if (report.config?.date_range) {
        const { start, end } = report.config.date_range;
        filteredLeads = filteredLeads.filter(lead => {
          const leadDate = new Date(lead.created_at);
          if (start && leadDate < new Date(start)) return false;
          if (end && leadDate > new Date(end)) return false;
          return true;
        });
      }

      // Get total count before pagination
      const total = filteredLeads.length;
      const totalPages = Math.ceil(total / limit);

      // Apply pagination
      const paginatedLeads = filteredLeads.slice(offset, offset + limit);

      // Enrich leads with sheet, owner, and assigned user information
      const enrichedLeads = await Promise.all(
        paginatedLeads.map(async (lead) => {
          const sheet = await storage.getSheet(lead.sheet_id);
          const owner = await storage.getUser(lead.owner_user_id);
          const assignedUser = lead.assigned_to ? await storage.getUser(lead.assigned_to) : null;
          
          // Inject created_at into custom_fields for proper display
          const leadWithCreatedAt = injectSystemFieldsToCustomFields(lead);
          
          return {
            ...leadWithCreatedAt,
            sheet_name: sheet?.name || "Unknown",
            owner_name: owner?.name || "Unknown",
            user_name: assignedUser?.name || assignedUser?.email || "Unassigned",
          };
        })
      );

      res.json({
        leads: enrichedLeads,
        total,
        page,
        limit,
        total_pages: totalPages,
      });
    } catch (error: any) {
      console.error("Get report drilldown error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/company/executive-performance - Get executive performance data by dropdown column option
  app.get("/api/company/executive-performance", authMiddleware, async (req: AuthRequest, res) => {
    try {
      // Get parameters
      const columnKey = req.query.column_key as string;
      const optionValue = req.query.option_value as string;
      
      if (!columnKey || !optionValue) {
        return res.status(400).json({ 
          error: "Missing required parameters: column_key and option_value" 
        });
      }
      
      // Get company ID
      const companyId = req.companyId;
      if (!companyId) {
        return res.status(403).json({ error: "Company access required" });
      }
      
      // Get accessible sheet IDs for the user (excluding deleted sheets)
      let sheets: any[] = [];
      if (req.userRole === "company_admin" || req.userRole === "super_admin") {
        const allSheets = await storage.getSheetsByCompanyId(companyId);
        sheets = allSheets.filter(s => !s.deleted_at);
      } else {
        const userSheets = await storage.getSheetsByUserId(req.userId!);
        sheets = userSheets.filter(s => !s.deleted_at);
      }
      
      if (sheets.length === 0) {
        return res.json({
          column_key: columnKey,
          option_value: optionValue,
          sheets: [],
          generated_at: new Date().toISOString(),
        });
      }
      
      // Calculate date boundaries
      const now = new Date();
      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      
      // Start of current week (Monday)
      const dayOfWeek = now.getDay();
      const daysFromMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
      const weekStart = new Date(todayStart);
      weekStart.setDate(weekStart.getDate() - daysFromMonday);
      
      // Last 30 days
      const thirtyDaysAgo = new Date(todayStart);
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
      
      // Aggregate data per sheet
      const sheetData = await Promise.all(
        sheets.map(async (sheet) => {
          // Get all leads for this sheet (excluding soft-deleted)
          const allLeads = await storage.getLeadsBySheetId(sheet.id);
          const activeLeads = allLeads.filter(lead => !lead.deleted_at);
          
          // Filter leads matching the column/option
          const matchingLeads = activeLeads.filter(lead => {
            const fieldValue = lead.custom_fields?.[columnKey];
            if (Array.isArray(fieldValue)) {
              return fieldValue.includes(optionValue);
            }
            return fieldValue === optionValue;
          });
          
          // Count by time period
          let todayCount = 0;
          let weekCount = 0;
          let monthCount = 0;
          
          matchingLeads.forEach(lead => {
            const createdAt = new Date(lead.created_at);
            
            if (createdAt >= todayStart) {
              todayCount++;
            }
            if (createdAt >= weekStart) {
              weekCount++;
            }
            if (createdAt >= thirtyDaysAgo) {
              monthCount++;
            }
          });
          
          return {
            sheet_id: sheet.id,
            sheet_name: sheet.name,
            today: todayCount,
            this_week: weekCount,
            last_30_days: monthCount,
            total: matchingLeads.length,
          };
        })
      );
      
      // Sort by total count descending
      sheetData.sort((a, b) => b.total - a.total);
      
      res.json({
        column_key: columnKey,
        option_value: optionValue,
        sheets: sheetData,
        generated_at: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error("Get executive performance error:", error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // GET /api/company/executive-performance/drilldown - Get leads for a specific sheet/time period
  app.get("/api/company/executive-performance/drilldown", authMiddleware, async (req: AuthRequest, res) => {
    try {
      const sheetId = req.query.sheet_id as string;
      const columnKey = req.query.column_key as string;
      const optionValue = req.query.option_value as string;
      const timePeriod = req.query.time_period as string; // "today", "this_week", "last_30_days", "total"
      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 50;
      const offset = (page - 1) * limit;
      
      if (!sheetId || !columnKey || !optionValue) {
        return res.status(400).json({ 
          error: "Missing required parameters: sheet_id, column_key, option_value" 
        });
      }
      
      // Check sheet access
      const hasAccess = await hasSheetAccess(req.userId!, req.userRole!, req.companyId || null, sheetId);
      if (!hasAccess) {
        return res.status(403).json({ error: "Access denied to this sheet" });
      }
      
      // Get sheet for enrichment
      const sheet = await storage.getSheet(sheetId);
      
      // Calculate date boundaries
      const now = new Date();
      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      
      const dayOfWeek = now.getDay();
      const daysFromMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
      const weekStart = new Date(todayStart);
      weekStart.setDate(weekStart.getDate() - daysFromMonday);
      
      const thirtyDaysAgo = new Date(todayStart);
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
      
      // Get all leads for this sheet
      const allLeads = await storage.getLeadsBySheetId(sheetId);
      const activeLeads = allLeads.filter(lead => !lead.deleted_at);
      
      // Filter leads matching the column/option
      let matchingLeads = activeLeads.filter(lead => {
        const fieldValue = lead.custom_fields?.[columnKey];
        if (Array.isArray(fieldValue)) {
          return fieldValue.includes(optionValue);
        }
        return fieldValue === optionValue;
      });
      
      // Apply time period filter
      if (timePeriod === "today") {
        matchingLeads = matchingLeads.filter(lead => new Date(lead.created_at) >= todayStart);
      } else if (timePeriod === "this_week") {
        matchingLeads = matchingLeads.filter(lead => new Date(lead.created_at) >= weekStart);
      } else if (timePeriod === "last_30_days") {
        matchingLeads = matchingLeads.filter(lead => new Date(lead.created_at) >= thirtyDaysAgo);
      }
      // "total" or undefined: no additional date filter
      
      // Sort by created_at descending
      matchingLeads.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
      
      // Get total count before pagination
      const total = matchingLeads.length;
      const totalPages = Math.ceil(total / limit);
      
      // Apply pagination
      const paginatedLeads = matchingLeads.slice(offset, offset + limit);
      
      // Enrich leads with owner information
      const enrichedLeads = await Promise.all(
        paginatedLeads.map(async (lead) => {
          const owner = await storage.getUser(lead.owner_user_id);
          
          // Inject created_at into custom_fields for proper display
          const leadWithCreatedAt = injectSystemFieldsToCustomFields(lead);
          
          return {
            ...leadWithCreatedAt,
            sheet_name: sheet?.name || "Unknown",
            owner_name: owner?.name || "Unknown",
          };
        })
      );
      
      res.json({
        leads: enrichedLeads,
        total,
        page,
        limit,
        total_pages: totalPages,
      });
    } catch (error: any) {
      console.error("Get executive performance drilldown error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Helper functions for report data generation
  function generateLeadStatusDistribution(leads: any[]) {
    const statusCounts: Record<string, number> = {};
    leads.forEach(lead => {
      const status = lead.lead_status || "Unknown";
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });
    
    return Object.entries(statusCounts).map(([name, value]) => ({ name, value }));
  }

  function generateLeadsOverTime(leads: any[], config: any) {
    const groupBy = config?.group_by || "day"; // day, week, month
    const dateCounts: Record<string, number> = {};
    
    leads.forEach(lead => {
      const date = new Date(lead.created_at);
      let key: string;
      
      if (groupBy === "month") {
        key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      } else if (groupBy === "week") {
        const weekNum = Math.ceil((date.getDate()) / 7);
        key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-W${weekNum}`;
      } else {
        key = date.toISOString().split('T')[0];
      }
      
      dateCounts[key] = (dateCounts[key] || 0) + 1;
    });
    
    return Object.entries(dateCounts)
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([date, count]) => ({ date, count }));
  }

  function generateLeadSourceAnalysis(leads: any[], config: any) {
    const field = config?.group_by || "language";
    const sourceCounts: Record<string, number> = {};
    
    leads.forEach(lead => {
      const value = lead[field] || lead.custom_fields?.[field] || "Unknown";
      sourceCounts[value] = (sourceCounts[value] || 0) + 1;
    });
    
    return Object.entries(sourceCounts)
      .sort((a, b) => b[1] - a[1])
      .map(([name, value]) => ({ name, value }));
  }

  function generateConversionRate(leads: any[]) {
    const statuses = ["New", "Contacted", "Qualified", "Converted"];
    const statusCounts: Record<string, number> = {};
    
    leads.forEach(lead => {
      const status = lead.lead_status || "Unknown";
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });
    
    return statuses.map(status => ({
      stage: status,
      count: statusCounts[status] || 0,
    }));
  }

  async function generateUserPerformance(leads: any[], storage: any) {
    const userCounts: Record<string, { created: number; updated: number; name: string }> = {};
    
    for (const lead of leads) {
      if (lead.created_by_user_id) {
        if (!userCounts[lead.created_by_user_id]) {
          const user = await storage.getUser(lead.created_by_user_id);
          userCounts[lead.created_by_user_id] = { 
            created: 0, 
            updated: 0, 
            name: user?.name || "Unknown" 
          };
        }
        userCounts[lead.created_by_user_id].created++;
      }
      
      if (lead.updated_by_user_id && lead.updated_by_user_id !== lead.created_by_user_id) {
        if (!userCounts[lead.updated_by_user_id]) {
          const user = await storage.getUser(lead.updated_by_user_id);
          userCounts[lead.updated_by_user_id] = { 
            created: 0, 
            updated: 0, 
            name: user?.name || "Unknown" 
          };
        }
        userCounts[lead.updated_by_user_id].updated++;
      }
    }
    
    return Object.entries(userCounts).map(([userId, data]) => ({
      user: data.name,
      created: data.created,
      updated: data.updated,
      total: data.created + data.updated,
    }));
  }

  function generateLeadAgeDistribution(leads: any[]) {
    const now = new Date();
    const ageBuckets = {
      "0-7 days": 0,
      "8-14 days": 0,
      "15-30 days": 0,
      "31-60 days": 0,
      "61-90 days": 0,
      "90+ days": 0,
    };
    
    leads.forEach(lead => {
      const createdDate = new Date(lead.created_at);
      const ageInDays = Math.floor((now.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24));
      
      if (ageInDays <= 7) ageBuckets["0-7 days"]++;
      else if (ageInDays <= 14) ageBuckets["8-14 days"]++;
      else if (ageInDays <= 30) ageBuckets["15-30 days"]++;
      else if (ageInDays <= 60) ageBuckets["31-60 days"]++;
      else if (ageInDays <= 90) ageBuckets["61-90 days"]++;
      else ageBuckets["90+ days"]++;
    });
    
    return Object.entries(ageBuckets).map(([range, count]) => ({ range, count }));
  }

  function generateCustomFieldAnalysis(leads: any[], config: any) {
    const field = config?.metrics?.[0] || "occupation";
    const fieldCounts: Record<string, number> = {};
    
    leads.forEach(lead => {
      const value = lead[field] || lead.custom_fields?.[field] || "Unknown";
      fieldCounts[value] = (fieldCounts[value] || 0) + 1;
    });
    
    return Object.entries(fieldCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10) // Top 10
      .map(([name, value]) => ({ name, value }));
  }

  // Helper function to format dates for grouping (respects company timezone)
  function formatDateForGrouping(dateValue: Date | string | null, groupType: string, timezone: string = "Asia/Kolkata"): string {
    if (!dateValue) return "No Date";
    
    const date = typeof dateValue === 'string' ? new Date(dateValue) : dateValue;
    if (isNaN(date.getTime())) return "Invalid Date";
    
    // Use Intl.DateTimeFormat to get date parts in the company timezone
    const formatter = new Intl.DateTimeFormat("en-US", {
      timeZone: timezone,
      year: "numeric",
      month: "numeric",
      day: "numeric",
    });
    
    const parts = formatter.formatToParts(date);
    const year = parseInt(parts.find(p => p.type === "year")?.value || "2024");
    const month = parseInt(parts.find(p => p.type === "month")?.value || "1") - 1; // 0-indexed
    const day = parseInt(parts.find(p => p.type === "day")?.value || "1");
    
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    
    switch (groupType) {
      case "day":
        // Format: "Jan 15, 2024"
        return `${monthNames[month]} ${day}, ${year}`;
      case "week": {
        // Use date-fns-tz formatInTimeZone for proper ISO 8601 week in company timezone
        // 'I' gives ISO week number, 'R' gives ISO week year
        const isoWeek = formatInTimeZone(date, timezone, "I");
        const isoYear = formatInTimeZone(date, timezone, "RRRR");
        
        return `Week ${isoWeek}, ${isoYear}`;
      }
      case "month":
        // Format: "Jan 2024"
        return `${monthNames[month]} ${year}`;
      case "quarter": {
        // Format: "Q1 2024"
        const quarter = Math.floor(month / 3) + 1;
        return `Q${quarter} ${year}`;
      }
      case "year":
        // Format: "2024"
        return `${year}`;
      default:
        return date.toISOString().split('T')[0];
    }
  }
  
  // Shared helper to extract sortable date key from formatted string
  // Used for sorting date-based groupings chronologically in both dynamic reports and pivot tables
  function getDateSortKey(name: string, groupType: string): number {
    if (name === "No Date" || name === "Invalid Date") return Infinity;
    
    const monthMap: Record<string, number> = {
      "Jan": 0, "Feb": 1, "Mar": 2, "Apr": 3, "May": 4, "Jun": 5,
      "Jul": 6, "Aug": 7, "Sep": 8, "Oct": 9, "Nov": 10, "Dec": 11
    };
    
    switch (groupType) {
      case "day": {
        // Format: "Jan 15, 2024"
        const match = name.match(/^(\w+)\s+(\d+),\s+(\d+)$/);
        if (match) {
          const [, mon, day, year] = match;
          return new Date(parseInt(year), monthMap[mon] || 0, parseInt(day)).getTime();
        }
        return 0;
      }
      case "week": {
        // Format: "Week 3, 2024"
        const match = name.match(/^Week\s+(\d+),\s+(\d+)$/);
        if (match) {
          const [, week, year] = match;
          return parseInt(year) * 100 + parseInt(week);
        }
        return 0;
      }
      case "month": {
        // Format: "Jan 2024"
        const match = name.match(/^(\w+)\s+(\d+)$/);
        if (match) {
          const [, mon, year] = match;
          return parseInt(year) * 12 + (monthMap[mon] || 0);
        }
        return 0;
      }
      case "quarter": {
        // Format: "Q1 2024"
        const match = name.match(/^Q(\d)\s+(\d+)$/);
        if (match) {
          const [, q, year] = match;
          return parseInt(year) * 4 + parseInt(q);
        }
        return 0;
      }
      case "year": {
        // Format: "2024"
        return parseInt(name) || 0;
      }
      default:
        return 0;
    }
  }
  
  // Helper to sort an array of strings by date grouping
  function sortDateStrings(strings: string[], groupType: string): string[] {
    return [...strings].sort((a, b) => getDateSortKey(a, groupType) - getDateSortKey(b, groupType));
  }
  
  // Helper to detect if a string looks like a formatted date and parse it for sorting
  // Tries all known date formats from formatDateForGrouping
  function parseFormattedDateString(str: string): number | null {
    if (!str || str === "Unknown") return null;
    
    const monthMap: Record<string, number> = {
      "Jan": 0, "Feb": 1, "Mar": 2, "Apr": 3, "May": 4, "Jun": 5,
      "Jul": 6, "Aug": 7, "Sep": 8, "Oct": 9, "Nov": 10, "Dec": 11,
      "January": 0, "February": 1, "March": 2, "April": 3, "June": 5,
      "July": 6, "August": 7, "September": 8, "October": 9, "November": 10, "December": 11
    };
    
    // Match "Dec 12, 2025" or "Jan 1, 2024" format (short month)
    const dayMatch = str.match(/^(\w{3,9})\s+(\d{1,2}),\s+(\d{4})$/);
    if (dayMatch) {
      const [, mon, day, year] = dayMatch;
      if (monthMap[mon] !== undefined) {
        return new Date(parseInt(year), monthMap[mon], parseInt(day)).getTime();
      }
    }
    
    // Match "12 Dec 2025" or "1 Jan 2024" format (day first)
    const dayFirstMatch = str.match(/^(\d{1,2})\s+(\w{3,9})\s+(\d{4})$/);
    if (dayFirstMatch) {
      const [, day, mon, year] = dayFirstMatch;
      if (monthMap[mon] !== undefined) {
        return new Date(parseInt(year), monthMap[mon], parseInt(day)).getTime();
      }
    }
    
    // Match "2025-12-08" or similar ISO date format
    const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (isoMatch) {
      const [, year, month, day] = isoMatch;
      return new Date(parseInt(year), parseInt(month) - 1, parseInt(day)).getTime();
    }
    
    // Match "Jan 2024" or "January 2024" format (month grouping)
    const monthMatch = str.match(/^(\w{3,9})\s+(\d{4})$/);
    if (monthMatch) {
      const [, mon, year] = monthMatch;
      if (monthMap[mon] !== undefined) {
        return parseInt(year) * 12 + monthMap[mon];
      }
    }
    
    // Match "Week 3, 2024" format
    const weekMatch = str.match(/^Week\s+(\d+),\s+(\d{4})$/);
    if (weekMatch) {
      const [, week, year] = weekMatch;
      return parseInt(year) * 100 + parseInt(week);
    }
    
    // Match "Q1 2024" format
    const quarterMatch = str.match(/^Q(\d)\s+(\d{4})$/);
    if (quarterMatch) {
      const [, q, year] = quarterMatch;
      return parseInt(year) * 4 + parseInt(q);
    }
    
    // Match pure year "2024"
    if (/^\d{4}$/.test(str)) {
      return parseInt(str);
    }
    
    return null;
  }
  
  // Helper to intelligently sort an array - dates chronologically, text alphabetically
  function smartSortStrings(strings: string[]): string[] {
    const arr = [...strings];
    
    // Check how many values look like dates
    const dateScores = arr.filter(s => s && s !== "Unknown" && parseFormattedDateString(s) !== null);
    const nonUnknownCount = arr.filter(s => s && s !== "Unknown").length;
    
    // If majority of values are date-like, sort as dates
    if (nonUnknownCount > 0 && dateScores.length >= nonUnknownCount / 2) {
      return arr.sort((a, b) => {
        const aVal = parseFormattedDateString(a);
        const bVal = parseFormattedDateString(b);
        if (aVal === null && bVal === null) return a.localeCompare(b);
        if (aVal === null) return 1;
        if (bVal === null) return -1;
        return aVal - bVal;
      });
    }
    
    // Sort alphabetically
    return arr.sort((a, b) => a.localeCompare(b));
  }
  
  // Helper to sort object entries using smart sort (preserves all entries including duplicates)
  function smartSortEntries(entries: [string, any][]): [string, any][] {
    const keys = entries.map(e => e[0]);
    
    // Check if values are dates
    const dateScores = keys.filter(k => k && k !== "Unknown" && parseFormattedDateString(k) !== null);
    const nonUnknownCount = keys.filter(k => k && k !== "Unknown").length;
    const isDateSort = nonUnknownCount > 0 && dateScores.length >= nonUnknownCount / 2;
    
    return [...entries].sort((a, b) => {
      if (isDateSort) {
        const aVal = parseFormattedDateString(a[0]);
        const bVal = parseFormattedDateString(b[0]);
        if (aVal === null && bVal === null) return a[0].localeCompare(b[0]);
        if (aVal === null) return 1;
        if (bVal === null) return -1;
        return aVal - bVal;
      }
      return a[0].localeCompare(b[0]);
    });
  }
  
  // Dynamic report generation based on X and Y axis configuration
  function generateDynamicReport(leads: any[], config: any, timezone: string = "Asia/Kolkata") {
    const xAxis = config?.x_axis || "lead_status"; // Column to group by
    const yAxis = config?.y_axis || "count"; // Aggregation type: count, sum, avg
    const yAxisField = config?.y_axis_field; // Field to aggregate (for sum/avg)
    
    const grouped: Record<string, any[]> = {};
    
    // Check if x_axis is a date-based grouping
    const dateGroupingMatch = xAxis.match(/^(created_at|nfdt)_(day|week|month|quarter|year)$/);
    
    // Group leads by X-axis value
    leads.forEach(lead => {
      let xValue: string;
      
      if (dateGroupingMatch) {
        // Handle date-based grouping
        const [, dateField, groupType] = dateGroupingMatch;
        let dateValue: Date | string | null = null;
        
        if (dateField === "created_at") {
          dateValue = lead.created_at;
        } else if (dateField === "nfdt") {
          // NFDT can be in custom_fields or as a direct field
          dateValue = lead.custom_fields?.nfdt || lead.nfdt || null;
        }
        
        xValue = formatDateForGrouping(dateValue, groupType, timezone);
      } else {
        // Regular column grouping
        xValue = lead[xAxis] || lead.custom_fields?.[xAxis] || "Unknown";
        
        // Handle date fields for display
        if (xValue && typeof xValue === 'string' && xValue.match(/^\d{4}-\d{2}-\d{2}/)) {
          xValue = xValue.split('T')[0]; // Format dates consistently
        }
      }
      
      if (!grouped[xValue]) {
        grouped[xValue] = [];
      }
      grouped[xValue].push(lead);
    });
    
    // Calculate Y-axis values based on aggregation type
    const result = Object.entries(grouped).map(([name, groupLeads]) => {
      let value: number;
      
      switch (yAxis) {
        case "count":
          value = groupLeads.length;
          break;
        case "sum":
          if (!yAxisField) {
            value = groupLeads.length;
          } else {
            value = groupLeads.reduce((sum, lead) => {
              const fieldValue = parseFloat(lead[yAxisField] || lead.custom_fields?.[yAxisField] || 0);
              return sum + (isNaN(fieldValue) ? 0 : fieldValue);
            }, 0);
          }
          break;
        case "avg":
          if (!yAxisField) {
            value = groupLeads.length;
          } else {
            const sum = groupLeads.reduce((sum, lead) => {
              const fieldValue = parseFloat(lead[yAxisField] || lead.custom_fields?.[yAxisField] || 0);
              return sum + (isNaN(fieldValue) ? 0 : fieldValue);
            }, 0);
            value = groupLeads.length > 0 ? sum / groupLeads.length : 0;
          }
          break;
        default:
          value = groupLeads.length;
      }
      
      return { name, value: Math.round(value * 100) / 100 }; // Round to 2 decimals
    });
    
    // For date-based groupings, sort chronologically instead of by value
    if (dateGroupingMatch) {
      const [, , groupType] = dateGroupingMatch;
      return result.sort((a, b) => getDateSortKey(a.name, groupType) - getDateSortKey(b.name, groupType));
    }
    
    return result.sort((a, b) => b.value - a.value);
  }

  // Generate pivot table with multi-dimensional grouping
  function generatePivotTable(leads: any[], config: any, timezone: string = "Asia/Kolkata") {
    const rowFields = config?.row_fields || []; // Array of columns for row grouping
    const columnField = config?.column_field; // Optional column pivot field
    const valueField = config?.value_field; // Field to aggregate
    const aggregation = config?.aggregation || "count"; // count, sum, avg

    if (rowFields.length === 0) {
      return { rows: [], columns: [], data: [] };
    }

    // Helper function to get field value from lead (with date-based grouping support)
    const getFieldValue = (lead: any, field: string) => {
      // Check if field is a date-based grouping
      const dateGroupingMatch = field.match(/^(created_at|nfdt)_(day|week|month|quarter|year)$/);
      
      if (dateGroupingMatch) {
        const [, dateField, groupType] = dateGroupingMatch;
        let dateValue: Date | string | null = null;
        
        if (dateField === "created_at") {
          dateValue = lead.created_at;
        } else if (dateField === "nfdt") {
          dateValue = lead.custom_fields?.nfdt || lead.nfdt || null;
        }
        
        return formatDateForGrouping(dateValue, groupType, timezone);
      }
      
      // Get raw field value - check lead first, then custom_fields
      const rawValue = field in lead ? lead[field] : lead.custom_fields?.[field];
      if (rawValue === null || rawValue === undefined) return "Unknown";
      
      // If value looks like a datetime (ISO format), format it as date for grouping
      // This ensures datetime columns like attended_at are grouped by date, not exact timestamp
      if (typeof rawValue === 'string' && rawValue.match(/^\d{4}-\d{2}-\d{2}T/)) {
        return formatDateForGrouping(rawValue, "day", timezone);
      }
      
      // Handle Date objects
      if (rawValue instanceof Date) {
        return formatDateForGrouping(rawValue, "day", timezone);
      }
      
      return rawValue;
    };

    // Helper function to calculate aggregation
    const calculateAggregation = (leadsSubset: any[]) => {
      if (aggregation === "count") {
        return leadsSubset.length;
      }
      
      if (!valueField) return leadsSubset.length;
      
      const values = leadsSubset.map(l => parseFloat(getFieldValue(l, valueField) || 0)).filter(v => !isNaN(v));
      
      if (aggregation === "sum") {
        return values.reduce((sum, v) => sum + v, 0);
      }
      
      if (aggregation === "avg") {
        return values.length > 0 ? values.reduce((sum, v) => sum + v, 0) / values.length : 0;
      }
      
      return leadsSubset.length;
    };

    // Build row hierarchy
    const buildRowHierarchy = (leadsSubset: any[], fieldIndex: number): any => {
      if (fieldIndex >= rowFields.length) {
        return leadsSubset;
      }

      const field = rowFields[fieldIndex];
      const grouped: Record<string, any[]> = {};

      leadsSubset.forEach(lead => {
        const value = getFieldValue(lead, field);
        if (!grouped[value]) grouped[value] = [];
        grouped[value].push(lead);
      });

      const result: any = {};
      Object.entries(grouped).forEach(([key, groupLeads]) => {
        result[key] = buildRowHierarchy(groupLeads, fieldIndex + 1);
      });

      return result;
    };

    // If no column field, create simple row-grouped table
    if (!columnField) {
      const hierarchy = buildRowHierarchy(leads, 0);
      
      const flattenRows = (node: any, parentKeys: string[] = [], fieldIndex: number = 0): any[] => {
        if (Array.isArray(node)) {
          return [{
            keys: parentKeys,
            value: calculateAggregation(node),
            count: node.length
          }];
        }

        const currentField = rowFields[fieldIndex];
        const dateMatch = currentField?.match(/^(created_at|nfdt)_(day|week|month|quarter|year)$/);
        let entries = Object.entries(node);
        
        // Sort entries based on whether current row field is a date grouping
        if (dateMatch) {
          const [, , groupType] = dateMatch;
          entries = entries.sort((a, b) => getDateSortKey(a[0], groupType) - getDateSortKey(b[0], groupType));
        } else {
          // Use smart sort to detect formatted dates and sort chronologically, otherwise alphabetically
          entries = smartSortEntries(entries);
        }

        const rows: any[] = [];
        entries.forEach(([key, child]) => {
          rows.push(...flattenRows(child, [...parentKeys, key], fieldIndex + 1));
        });
        return rows;
      };

      const flatRows = flattenRows(hierarchy, [], 0);
      
      return {
        type: "simple",
        rowFields,
        aggregation,
        valueField,
        rows: flatRows
      };
    }

    // With column field - create full pivot table
    const columnValues = new Set<string>();
    leads.forEach(lead => {
      columnValues.add(getFieldValue(lead, columnField));
    });

    // Check if column field is a date-based grouping and apply appropriate sorting
    const columnDateMatch = columnField.match(/^(created_at|nfdt)_(day|week|month|quarter|year)$/);
    let columns: string[];
    if (columnDateMatch) {
      const [, , groupType] = columnDateMatch;
      columns = sortDateStrings(Array.from(columnValues), groupType);
    } else {
      // Use smart sort to detect formatted dates and sort chronologically, otherwise alphabetically
      columns = smartSortStrings(Array.from(columnValues));
    }
    
    const hierarchy = buildRowHierarchy(leads, 0);

    const flattenRowsWithColumns = (node: any, parentKeys: string[] = [], fieldIndex: number = 0): any[] => {
      if (Array.isArray(node)) {
        const row: any = { keys: parentKeys };
        
        columns.forEach(col => {
          const filtered = node.filter(l => getFieldValue(l, columnField) === col);
          row[col] = calculateAggregation(filtered);
        });
        
        row.total = calculateAggregation(node);
        return [row];
      }

      const currentField = rowFields[fieldIndex];
      const dateMatch = currentField?.match(/^(created_at|nfdt)_(day|week|month|quarter|year)$/);
      let entries = Object.entries(node);
      
      // Sort entries based on whether current row field is a date grouping
      if (dateMatch) {
        const [, , groupType] = dateMatch;
        entries = entries.sort((a, b) => getDateSortKey(a[0], groupType) - getDateSortKey(b[0], groupType));
      } else {
        // Use smart sort to detect formatted dates and sort chronologically, otherwise alphabetically
        entries = smartSortEntries(entries);
      }

      const rows: any[] = [];
      entries.forEach(([key, child]) => {
        rows.push(...flattenRowsWithColumns(child, [...parentKeys, key], fieldIndex + 1));
      });
      return rows;
    };

    const dataRows = flattenRowsWithColumns(hierarchy, [], 0);

    // Calculate column totals directly from leads data (handles count, sum, avg correctly)
    const columnTotals: Record<string, number> = {};
    columns.forEach(col => {
      const leadsInColumn = leads.filter(l => getFieldValue(l, columnField) === col);
      columnTotals[col] = calculateAggregation(leadsInColumn);
    });

    // Calculate grand total from all leads
    const grandTotal = calculateAggregation(leads);

    return {
      type: "pivot",
      rowFields,
      columnField,
      columns,
      aggregation,
      valueField,
      rows: dataRows,
      columnTotals,
      grandTotal
    };
  }

  // Sheet-scoped validation rules endpoints (for frontend integration)
  // GET /api/sheets/:sheetId/validation-rules - Fetch rules for a sheet (company-wide + sheet-specific)
  app.get("/api/sheets/:sheetId/validation-rules", authMiddleware, requireSheetAccess, async (req: AuthRequest, res) => {
    try {
      const sheetId = req.params.sheetId;
      
      // Get sheet to derive company_id
      const sheet = await storage.getSheet(sheetId);
      if (!sheet) {
        return res.status(404).json({ error: "Sheet not found" });
      }
      
      // Get validation rules for this sheet (both company-wide and sheet-specific)
      const rules = await storage.getValidationRules(sheet.company_id, sheetId);
      res.json(rules);
    } catch (error: any) {
      console.error("Get sheet validation rules error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // POST /api/sheets/:sheetId/validation-rules - Create rule for a sheet (Company Admin only)
  app.post("/api/sheets/:sheetId/validation-rules", authMiddleware, requireCompanyAdmin, requireSheetAccess, async (req: AuthRequest, res) => {
    try {
      const sheetId = req.params.sheetId;
      
      // Sheet access already verified by requireSheetAccess middleware
      // Get sheet to derive and validate company_id
      const sheet = await storage.getSheet(sheetId);
      if (!sheet) {
        return res.status(404).json({ error: "Sheet not found" });
      }
      
      // Explicit company_id validation to prevent cross-company injection
      // Company admins can only create rules for sheets in their company
      if (req.userRole === "company_admin") {
        if (!req.companyId) {
          return res.status(403).json({ error: "Company admin must belong to a company" });
        }
        if (sheet.company_id !== req.companyId) {
          return res.status(403).json({ error: "Cannot create rules for sheets in other companies" });
        }
      }
      // Super admins can create rules for any sheet, but we validate the sheet exists and is consistent
      else if (req.userRole === "super_admin") {
        if (!sheet.company_id) {
          return res.status(400).json({ error: "Sheet must belong to a company" });
        }
      }
      
      const { name, trigger_column_key, operator, trigger_value, required_fields, conditions, logical_operator, required_columns } = req.body;
      
      // Support new multi-condition format or legacy single condition format
      const hasNewFormat = conditions && Array.isArray(conditions) && conditions.length > 0;
      const hasLegacyFormat = trigger_column_key && operator && trigger_value;
      
      if (!name) {
        return res.status(400).json({ error: "Rule name is required" });
      }
      
      // Allow rule if it has required_fields OR required_columns (supports optional-field rules)
      const hasRequiredFields = required_fields && Array.isArray(required_fields) && required_fields.length > 0;
      const hasRequiredColumns = required_columns && Array.isArray(required_columns) && required_columns.length > 0;
      if (!hasRequiredFields && !hasRequiredColumns) {
        return res.status(400).json({ error: "At least one required or optional field must be specified" });
      }
      
      if (!hasNewFormat && !hasLegacyFormat) {
        return res.status(400).json({ error: "At least one condition is required (use either conditions array or trigger_column_key/operator/trigger_value)" });
      }
      
      // Create rule with company_id derived from the sheet
      const rule = await storage.createValidationRule({
        company_id: sheet.company_id,
        sheet_id: sheetId,
        name,
        trigger_column_key: hasLegacyFormat ? trigger_column_key : (conditions?.[0]?.column_key || undefined),
        operator: hasLegacyFormat ? operator : (conditions?.[0]?.operator || undefined),
        trigger_value: hasLegacyFormat ? trigger_value : (conditions?.[0]?.value || undefined),
        required_fields: required_fields || [],
        conditions: hasNewFormat ? conditions : undefined,
        logical_operator: (logical_operator || "and") as "and" | "or",
        required_columns: required_columns || [],
      });
      
      // Audit log
      await storage.createAuditLog({
        user_id: req.userId!,
        company_id: sheet.company_id,
        action: "create",
        model: "validation_rule",
        model_id: rule.id,
        payload: { name, trigger_column_key, operator, sheet_id: sheetId },
      });
      
      res.status(201).json(rule);
    } catch (error: any) {
      console.error("Create sheet validation rule error:", error);
      res.status(500).json({ error: error.message });
    }
  });

