  // Get PowerScore leaderboard for a period
  app.get("/api/powerscore/leaderboard", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const period = (req.query.period as string) || 'today';
      
      // Get company timezone for accurate date calculations
      const company = await storage.getCompany(req.companyId);
      const timezone = company?.settings?.timezone || 'Asia/Kolkata';
      
      // Use date-fns-tz for timezone-aware date calculations (EXACT same logic as breakdown endpoint)
      const now = new Date();
      const todayStr = formatInTimeZone(now, timezone, 'yyyy-MM-dd');
      
      const startOfTodayUtc = fromZonedTime(`${todayStr}T00:00:00`, timezone);
      
      const yesterdayDate = new Date(startOfTodayUtc);
      yesterdayDate.setDate(yesterdayDate.getDate() - 1);
      const yesterdayStr = formatInTimeZone(yesterdayDate, timezone, 'yyyy-MM-dd');
      const startOfYesterdayUtc = fromZonedTime(`${yesterdayStr}T00:00:00`, timezone);
      
      // Use toZonedTime for accurate day-of-week detection in company timezone
      const zonedNow = toZonedTime(now, timezone);
      const dayOfWeek = zonedNow.getDay();
      const daysToMonday = (dayOfWeek === 0 ? 6 : dayOfWeek - 1);
      const mondayDate = new Date(startOfTodayUtc);
      mondayDate.setDate(mondayDate.getDate() - daysToMonday);
      const mondayStr = formatInTimeZone(mondayDate, timezone, 'yyyy-MM-dd');
      const startOfThisWeekUtc = fromZonedTime(`${mondayStr}T00:00:00`, timezone);
      
      const firstOfMonth = `${todayStr.substring(0, 7)}-01`;
      const startOfThisMonthUtc = fromZonedTime(`${firstOfMonth}T00:00:00`, timezone);
      
      let startDate: Date;
      let endDate = new Date();

      switch (period) {
        case 'yesterday': {
          startDate = startOfYesterdayUtc;
          endDate = startOfTodayUtc;
          break;
        }
        case 'this_week': {
          startDate = startOfThisWeekUtc;
          break;
        }
        case 'this_month': {
          startDate = startOfThisMonthUtc;
          break;
        }
        case 'last_month': {
          // Calculate first and last day of previous month in company timezone
          const zonedNowForMonth = toZonedTime(now, timezone);
          const prevMonth = new Date(zonedNowForMonth.getFullYear(), zonedNowForMonth.getMonth() - 1, 1);
          const firstDayOfPrevMonth = `${prevMonth.getFullYear()}-${String(prevMonth.getMonth() + 1).padStart(2, '0')}-01`;
          const lastDayOfPrevMonth = new Date(zonedNowForMonth.getFullYear(), zonedNowForMonth.getMonth(), 0).getDate();
          const lastDayOfPrevMonthStr = `${prevMonth.getFullYear()}-${String(prevMonth.getMonth() + 1).padStart(2, '0')}-${String(lastDayOfPrevMonth).padStart(2, '0')}`;
          startDate = fromZonedTime(`${firstDayOfPrevMonth}T00:00:00`, timezone);
          endDate = fromZonedTime(`${lastDayOfPrevMonthStr}T23:59:59.999`, timezone);
          break;
        }
        case 'all_time': {
          startDate = new Date(0);
          break;
        }
        case 'today':
        default: {
          startDate = startOfTodayUtc;
          break;
        }
      }

      const cacheKey = `${req.companyId}:${period}`;
      const result = await powerScoreLeaderboardCache.getOrComputeSwr(cacheKey, async () => {
        const leaderboard = await storage.getPowerScoreLeaderboard(req.companyId, startDate, endDate);
        return { leaderboard, period };
      });
      res.json(result);
    } catch (error: any) {
      console.error("Error fetching PowerScore leaderboard:", error);
      res.status(500).json({ error: error.message });
    }
  });

