  app.get("/api/powerscore/pending-approvals", authMiddleware, requireCompanyAdmin, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const approvals = await storage.getPowerScorePendingApprovals(req.companyId);
      
      // Enrich approvals with user names, lead details, and updates
      const enrichedApprovals = await Promise.all(approvals.map(async (approval) => {
        let user_name = "Unknown User";
        let lead_details: any = null;
        let lead_updates: any[] = [];
        
        // Get user name
        if (approval.user_id) {
          const user = await storage.getUser(approval.user_id);
          if (user) {
            user_name = user.name;
          }
        }
        
        // Get full lead details and updates
        if (approval.lead_id) {
          const lead = await storage.getLead(approval.lead_id);
          if (lead) {
            // Lead data is stored in custom_fields, not as top-level properties
            const cf = lead.custom_fields || {};
            lead_details = {
              id: lead.id,
              full_name: cf.full_name || "",
              mobile: cf.mobile_no || cf.mobile || "",
              email: cf.email || "",
              status: cf.status || cf.lead_status || "",
              address: cf.address || "",
              custom_fields: cf,
              created_at: lead.created_at,
              updated_at: lead.updated_at,
            };
            
            // Get recent lead updates (last 10)
            const updates = await storage.getLeadUpdates(approval.lead_id);
            lead_updates = updates.slice(0, 10).map((update: any) => ({
              id: update.id,
              remark: update.remark,
              nfdt: update.nfdt,
              created_at: update.created_at,
              created_by_user_id: update.created_by_user_id,
            }));
          }
        }
        
        return {
          ...approval,
          user_name,
          lead_full_name: lead_details?.full_name || "",
          lead_mobile: lead_details?.mobile || "",
          lead_details,
          lead_updates,
        };
      }));
      
      res.json({ approvals: enrichedApprovals });
    } catch (error: any) {
      console.error("Error fetching pending approvals:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Approve or reject a pending approval (Company Admin only)
  app.post("/api/powerscore/pending-approvals/:approvalId/review", authMiddleware, requireCompanyAdmin, async (req: AuthRequest, res) => {
    try {
      const { approvalId } = req.params;
      const { action, rejection_reason } = req.body;

      if (!['approve', 'reject'].includes(action)) {
        return res.status(400).json({ error: "Action must be 'approve' or 'reject'" });
      }

      const approval = await storage.getPowerScorePendingApproval(approvalId);
      if (!approval) {
        return res.status(404).json({ error: "Approval not found" });
      }

      if (req.userRole !== "super_admin" && approval.company_id !== req.companyId) {
        return res.status(403).json({ error: "Not authorized" });
      }

      if (approval.status !== 'pending') {
        return res.status(400).json({ error: "Approval already processed" });
      }

      if (action === 'approve') {
        const result = await storage.approvePowerScoreApproval(approvalId, req.userId!);
        
        // Emit celebration for approved points
        const rule = await storage.getPowerScoreRule(approval.rule_id);
        const showAnimationTo = rule?.show_animation_to || "user_only";
        if (showAnimationTo !== "none") {
          const user = await storage.getUser(approval.user_id);
          const { emitPointsCelebration } = await import("./socket-manager");
          emitPointsCelebration({
            userId: approval.user_id,
            userName: user?.name || "User",
            points: approval.points,
            ruleName: rule?.name || "Points",
            actionType: approval.action_type,
            showAnimationTo,
            companyId: approval.company_id,
            timestamp: Date.now(),
          });
        }
        
        res.json(result);
      } else {
        const result = await storage.rejectPowerScoreApproval(approvalId, req.userId!, rejection_reason);
        res.json(result);
      }
    } catch (error: any) {
      console.error("Error reviewing approval:", error);
      res.status(500).json({ error: error.message });
    }
  });

