  // Get PowerFlow analytics
  app.get("/api/powerflow/analytics", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const { period = 'this_month', sheet_id, use_personal_data } = req.query;
      const isPersonalData = use_personal_data === 'true';
      
      // Get all company sheets, excluding personal/private sheets from analytics
      const allCompanySheets = await storage.getSheetsByCompanyId(req.companyId);
      const allSheets = allCompanySheets.filter(s => !s.is_personal);
      
      // Build user's accessible sheets list (for non-admins)
      let userAccessibleSheets = allSheets;
      const isAdmin = req.userRole === 'super_admin' || req.userRole === 'company_admin';
      
      if (!isAdmin) {
        userAccessibleSheets = [];
        for (const sheet of allSheets) {
          if (await hasSheetAccess(req.userId!, req.userRole!, req.companyId || null, sheet.id)) {
            userAccessibleSheets.push(sheet);
          }
        }
      }
      
      let sheetIds: string[];
      
      if (sheet_id) {
        // Specific sheet requested - ALWAYS enforce permission check
        // User must have access to view that specific sheet's analytics
        const hasAccess = userAccessibleSheets.some(s => s.id === sheet_id);
        if (!hasAccess) {
          return res.status(403).json({ error: "No access to this sheet" });
        }
        sheetIds = [sheet_id as string];
      } else {
        // All sheets aggregation
        if (isPersonalData) {
          // "Own Data" mode: only aggregate sheets user has access to
          sheetIds = userAccessibleSheets.map(s => s.id);
        } else {
          // "Company Data" mode: aggregate ALL company sheets (company-wide view)
          sheetIds = allSheets.map(s => s.id);
        }
      }

      if (sheetIds.length === 0) {
        return res.json({
          pipeline_name: 'No Access',
          stages: [],
          total_leads: 0,
          overall_conversion_rate: 0,
          period: period as string,
        });
      }

      // Get PowerFlow config
      const config = await storage.getPowerFlowConfig(req.companyId);
      
      if (!config || !config.stages || config.stages.length === 0) {
        return res.json({
          pipeline_name: 'Not Configured',
          stages: [],
          total_leads: 0,
          overall_conversion_rate: 0,
          period: period as string,
          needs_configuration: true,
        });
      }

      // Get company timezone for date calculations
      const company = await storage.getCompany(req.companyId);
      const companyTimezone = getCompanyTimezone(company);
      
      // Calculate date range based on period using timezone-aware date arithmetic
      // Strategy: Convert UTC now -> zoned time, do date math in zoned time, convert back to UTC
      const now = new Date();
      let startDate: Date;
      let endDate: Date;
      
      // Convert current UTC time to company's local time (as a "fake UTC" Date representing local time)
      const zonedNow = toZonedTime(now, companyTimezone);
      
      // Helper to convert a zoned date back to UTC
      const zonedToUtc = (zonedDate: Date): Date => {
        // fromZonedTime takes a date that represents local time and converts to UTC
        return fromZonedTime(zonedDate, companyTimezone);
      };
      
      switch (period) {
        case 'today':
          startDate = zonedToUtc(startOfDay(zonedNow));
          endDate = zonedToUtc(endOfDay(zonedNow));
          break;
        case 'yesterday':
          const zonedYesterday = subDays(zonedNow, 1);
          startDate = zonedToUtc(startOfDay(zonedYesterday));
          endDate = zonedToUtc(endOfDay(zonedYesterday));
          break;
        case 'last_7_days':
          const zoned7DaysAgo = subDays(zonedNow, 7);
          startDate = zonedToUtc(startOfDay(zoned7DaysAgo));
          endDate = zonedToUtc(endOfDay(zonedNow));
          break;
        case 'this_week':
          // Current calendar week (Monday to today) - weekStartsOn: 1 means Monday
          const zonedThisWeekStart = startOfWeek(zonedNow, { weekStartsOn: 1 });
          startDate = zonedToUtc(startOfDay(zonedThisWeekStart));
          endDate = zonedToUtc(endOfDay(zonedNow));
          break;
        case 'last_week':
          // Previous calendar week (Monday to Sunday) - weekStartsOn: 1 means Monday
          const zonedLastWeekStart = startOfWeek(subWeeks(zonedNow, 1), { weekStartsOn: 1 });
          const zonedLastWeekEnd = endOfWeek(subWeeks(zonedNow, 1), { weekStartsOn: 1 });
          startDate = zonedToUtc(startOfDay(zonedLastWeekStart));
          endDate = zonedToUtc(endOfDay(zonedLastWeekEnd));
          break;
        case 'last_30_days':
          const zoned30DaysAgo = subDays(zonedNow, 30);
          startDate = zonedToUtc(startOfDay(zoned30DaysAgo));
          endDate = zonedToUtc(endOfDay(zonedNow));
          break;
        case 'this_month':
          startDate = zonedToUtc(startOfMonth(zonedNow));
          endDate = zonedToUtc(endOfDay(zonedNow));
          break;
        case 'last_month':
          const zonedPrevMonth = subMonths(zonedNow, 1);
          startDate = zonedToUtc(startOfMonth(zonedPrevMonth));
          endDate = zonedToUtc(endOfMonth(zonedPrevMonth));
          break;
        default:
          // Default to last 30 days
          const defaultStart = subDays(zonedNow, 30);
          startDate = zonedToUtc(startOfDay(defaultStart));
          endDate = zonedToUtc(endOfDay(zonedNow));
      }

      // Query analytics from activity_logs (aggregated across all sheets)
      const analytics = await storage.getPowerFlowAnalytics(
        req.companyId,
        sheetIds,
        config.stages,
        startDate,
        endDate
      );

      // Get per-sheet breakdown only when:
      // 1. Viewing "All Sheets" (no specific sheet_id filter)
      // 2. User has access to multiple sheets
      const perSheetAnalytics: Array<{
        sheet_id: string;
        sheet_name: string;
        stages: typeof analytics.stages;
        total_leads: number;
        overall_conversion_rate: number;
      }> = [];
      
      // Only compute per-sheet when viewing all sheets and user has multiple sheets
      const isViewingAllSheets = !sheet_id;
      const allAccessibleSheetIds = userAccessibleSheets.map(s => s.id);
      
      if (isViewingAllSheets && allAccessibleSheetIds.length > 1) {
        // Get sheet names for display
        const sheetsMap = new Map<string, string>();
        for (const sheet of userAccessibleSheets) {
          sheetsMap.set(sheet.id, sheet.name);
        }
        
        // Get analytics for each accessible sheet
        for (const sheetId of allAccessibleSheetIds) {
          const sheetAnalytics = await storage.getPowerFlowAnalytics(
            req.companyId,
            [sheetId],
            config.stages,
            startDate,
            endDate
          );
          
          perSheetAnalytics.push({
            sheet_id: sheetId,
            sheet_name: sheetsMap.get(sheetId) || 'Unknown Sheet',
            stages: sheetAnalytics.stages,
            total_leads: sheetAnalytics.total_leads,
            overall_conversion_rate: sheetAnalytics.overall_conversion_rate,
          });
        }
      }

      res.json({
        pipeline_name: config.name,
        stages: analytics.stages,
        total_leads: analytics.total_leads,
        overall_conversion_rate: analytics.overall_conversion_rate,
        period: period as string,
        date_range: {
          start: startDate.toISOString(),
          end: endDate.toISOString(),
        },
        per_sheet_analytics: perSheetAnalytics,
      });
    } catch (error: any) {
      console.error("Error fetching PowerFlow analytics:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get PowerFlow simulation (backward calculation)
  app.post("/api/powerflow/simulate", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const { target_conversions, working_days = 25, sheet_id } = req.body;

      if (!target_conversions || target_conversions <= 0) {
        return res.status(400).json({ error: "target_conversions must be a positive number" });
      }

      // Get user's accessible sheets
      const allSheets = await storage.getSheetsByCompanyId(req.companyId);
      let accessibleSheets = allSheets;
      
      if (req.userRole !== 'super_admin' && req.userRole !== 'company_admin') {
        accessibleSheets = [];
        for (const sheet of allSheets) {
          if (await hasSheetAccess(req.userId!, req.userRole!, req.companyId || null, sheet.id)) {
            accessibleSheets.push(sheet);
          }
        }
      }
      
      const sheetIds = sheet_id 
        ? [sheet_id as string].filter(id => accessibleSheets.some(s => s.id === id))
        : accessibleSheets.map(s => s.id);

      // Get PowerFlow config
      const config = await storage.getPowerFlowConfig(req.companyId);
      
      if (!config || !config.stages || config.stages.length === 0) {
        return res.status(400).json({ error: "Pipeline not configured" });
      }

      // Get historical conversion rates (last 30 days for stable rates)
      const now = new Date();
      const thirtyDaysAgo = new Date(now.getTime() - 30 * 86400000);
      
      const analytics = await storage.getPowerFlowAnalytics(
        req.companyId,
        sheetIds,
        config.stages,
        thirtyDaysAgo,
        now
      );

      // Calculate required counts backward from target
      // The conversion_rate on each stage represents the rate FROM that stage TO the next stage
      // So when going backward, to find how many we need at stage[i-1] to get requiredCount at stage[i],
      // we divide by stages[i-1].conversion_rate (the rate from prev to current)
      const stages = [...config.stages].sort((a, b) => a.order - b.order);
      const requiredStages: { stage_name: string; required_count: number; daily_count: number; conversion_rate: number }[] = [];
      
      let requiredCount = target_conversions;
      
      // Work backward from last stage to first
      for (let i = stages.length - 1; i >= 0; i--) {
        const stage = stages[i];
        const analyticsStage = analytics.stages.find(s => s.stage_id === stage.id);
        const conversionRate = analyticsStage?.conversion_rate || 0;
        
        requiredStages.unshift({
          stage_name: stage.name,
          required_count: Math.ceil(requiredCount),
          daily_count: Math.ceil(requiredCount / working_days),
          conversion_rate: conversionRate,
        });
        
        // Calculate how many we need at the previous stage
        // Use the PREVIOUS stage's conversion_rate (rate from stages[i-1] to stages[i])
        if (i > 0) {
          const prevStage = stages[i - 1];
          const prevAnalyticsStage = analytics.stages.find(s => s.stage_id === prevStage.id);
          const prevConversionRate = prevAnalyticsStage?.conversion_rate || 0;
          
          if (prevConversionRate > 0) {
            requiredCount = requiredCount / (prevConversionRate / 100);
          } else {
            // Fallback to historical ratio if no conversion rate
            const prevCount = prevAnalyticsStage?.count || 0;
            const currentCount = analyticsStage?.count || 0;
            if (prevCount > 0 && currentCount > 0) {
              const ratio = prevCount / currentCount;
              requiredCount = requiredCount * ratio;
            }
          }
        }
      }

      res.json({
        target_conversions,
        working_days,
        required_stages: requiredStages,
        based_on_days: 30,
      });
    } catch (error: any) {
      console.error("Error running PowerFlow simulation:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get accessible sheets for PowerFlow
  app.get("/api/powerflow/sheets", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const allSheets = await storage.getSheets(req.companyId);
      let accessibleSheets = allSheets;
      
      if (req.userRole !== 'super_admin' && req.userRole !== 'company_admin') {
        accessibleSheets = [];
        for (const sheet of allSheets) {
          if (await hasSheetAccess(req.userId!, req.userRole!, req.companyId || null, sheet.id)) {
            accessibleSheets.push(sheet);
          }
        }
      }

      res.json(accessibleSheets.map(s => ({ id: s.id, name: s.name })));
    } catch (error: any) {
      console.error("Error fetching PowerFlow sheets:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // ============================================================================
  // VISION BOARD (Personal Goal Tracking)
  // ============================================================================

  // Helper: Check if user should see team vision board (admin or multi-sheet access)
  const shouldSeeTeamVisionBoard = async (userId: string, userRole: string | undefined, companyId: string | null): Promise<boolean> => {
    console.log('[shouldSeeTeamVisionBoard] userId:', userId, 'userRole:', userRole, 'companyId:', companyId);
    
    // Admins always see team view
    if (userRole === 'super_admin' || userRole === 'company_admin') {
      console.log('[shouldSeeTeamVisionBoard] User is admin, returning true');
      return true;
    }
    
    // Check if user has access to multiple sheets
    if (companyId) {
      const sheets = await storage.getSheetsByUserId(userId);
      // Filter to only company sheets (not personal)
      const companySheets = sheets.filter(s => s.company_id === companyId && !s.is_personal);
      console.log('[shouldSeeTeamVisionBoard] Multi-sheet check:', companySheets.length, 'sheets');
      return companySheets.length > 1;
    }
    
    console.log('[shouldSeeTeamVisionBoard] Returning false (no company or not enough sheets)');
    return false;
  };

  // Helper: Calculate aggregated team vision board metrics
  const getTeamVisionBoardAggregates = async (companyId: string) => {
    const allBoards = await storage.getVisionBoardsByCompany(companyId);
    
    if (allBoards.length === 0) {
      return null;
    }

    // Get earnings for all boards in parallel and calculate totals
    let boardCount = allBoards.length;
    
    const boardEarningsArrays = await Promise.all(
      allBoards.map(board => storage.getVisionBoardEarnings(board.id))
    );
    
    let totalEarnings = 0;
    let totalGoal = 0;
    const effortTotals = { sales: 0, visits: 0, leads_attended: 0, followups: 0 };
    const allImages: string[] = [];
    
    for (let i = 0; i < allBoards.length; i++) {
      const board = allBoards[i];
      totalGoal += board.goal_amount;
      
      const boardEarnings = boardEarningsArrays[i].reduce((sum, e) => sum + e.amount, 0);
      totalEarnings += boardEarnings;
      
      if (board.effort_targets) {
        effortTotals.sales += board.effort_targets.sales || 0;
        effortTotals.visits += board.effort_targets.visits || 0;
        effortTotals.leads_attended += board.effort_targets.leads_attended || 0;
        effortTotals.followups += board.effort_targets.followups || 0;
      }
      
      if (board.images && Array.isArray(board.images)) {
        allImages.push(...board.images.slice(0, 2));
      }
    }

    // Calculate averages
    const avgGoal = Math.round(totalGoal / boardCount);
    const avgEarnings = Math.round(totalEarnings / boardCount);
    const avgProgress = totalGoal > 0 ? Math.round((totalEarnings / totalGoal) * 100) : 0;
    
    const avgEffortTargets = {
      sales: Math.round(effortTotals.sales / boardCount),
      visits: Math.round(effortTotals.visits / boardCount),
      leads_attended: Math.round(effortTotals.leads_attended / boardCount),
      followups: Math.round(effortTotals.followups / boardCount),
    };

    // Find most common currency
    const currencyCount: Record<string, number> = {};
    allBoards.forEach(b => {
      const curr = b.currency || 'INR';
      currencyCount[curr] = (currencyCount[curr] || 0) + 1;
    });
    const dominantCurrency = Object.entries(currencyCount)
      .sort((a, b) => b[1] - a[1])[0]?.[0] || 'INR';

    // Find date range
    const targetDates = allBoards.map(b => new Date(b.target_date)).sort((a, b) => a.getTime() - b.getTime());
    const earliestStart = allBoards.map(b => b.start_date ? new Date(b.start_date) : new Date(b.created_at!))
      .sort((a, b) => a.getTime() - b.getTime())[0];
    const latestTarget = targetDates[targetDates.length - 1];

    // Calculate team effort achieved using lead-based counting (respects company timezone)
    const now = new Date();
    const company = await storage.getCompany(companyId);
    const companyTimezone = getCompanyTimezone(company);
    
    // Define period boundaries using company timezone
    // For yearly: Use earliest Vision Board start date to start_date + 1 year (not calendar year)
    const yearStart = getStartOfDayInTimezone(earliestStart, companyTimezone);
    const yearEndDate = new Date(earliestStart);
    yearEndDate.setFullYear(yearEndDate.getFullYear() + 1);
    const yearEnd = getEndOfDayInTimezone(yearEndDate, companyTimezone);
    
    const monthStart = getStartOfDayInTimezone(new Date(now.getFullYear(), now.getMonth(), 1), companyTimezone);
    const weekStartDate = new Date(now);
    weekStartDate.setDate(weekStartDate.getDate() - weekStartDate.getDay());
    const weekStart = getStartOfDayInTimezone(weekStartDate, companyTimezone);
    const dayStart = getStartOfDayInTimezone(now, companyTimezone);
    const dayEnd = getEndOfDayInTimezone(now, companyTimezone);
    
    // Yesterday boundaries
    const yesterdayDate = new Date(now);
    yesterdayDate.setDate(yesterdayDate.getDate() - 1);
    const yesterdayStart = getStartOfDayInTimezone(yesterdayDate, companyTimezone);
    const yesterdayEnd = getEndOfDayInTimezone(yesterdayDate, companyTimezone);
    
    // Last month boundaries
    const lastMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const lastMonthStart = getStartOfDayInTimezone(lastMonthDate, companyTimezone);
    const lastMonthEndDate = new Date(now.getFullYear(), now.getMonth(), 0); // Last day of previous month
    const lastMonthEnd = getEndOfDayInTimezone(lastMonthEndDate, companyTimezone);
    
    // Get all sheets for this company to count leads
    const companySheets = await db.select().from(dbSchema.sheets).where(eq(dbSchema.sheets.company_id, companyId));
    const companySheetIds = companySheets.map(s => s.id);
    
    // Count leads directly from leads table by created_at
    const countLeadsCreated = async (startDate: Date, endDate: Date): Promise<number> => {
      if (companySheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, companySheetIds),
          gte(dbSchema.leads.created_at, startDate),
          lte(dbSchema.leads.created_at, endDate),
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count visits: leads where visit_status='Visited' AND visit_date is within period
    const countVisitsInPeriod = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (companySheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, companySheetIds),
          sql`custom_fields->>'visit_status' = 'Visited'`,
          sql`custom_fields->>'visit_date' IS NOT NULL`,
          sql`custom_fields->>'visit_date' != ''`,
          sql`(custom_fields->>'visit_date')::timestamp >= ${periodStart}`,
          sql`(custom_fields->>'visit_date')::timestamp < ${periodEnd}`,
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count sales: leads where conversion_date (custom_fields) is within period
    const countSalesInPeriod = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (companySheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, companySheetIds),
          sql`custom_fields->>'conversion_date' IS NOT NULL`,
          sql`custom_fields->>'conversion_date' != ''`,
          sql`(custom_fields->>'conversion_date')::timestamp >= ${periodStart}`,
          sql`(custom_fields->>'conversion_date')::timestamp < ${periodEnd}`,
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count followups from followup_events table
    const countFollowupsInPeriod = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (companySheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.followup_events)
        .where(and(
          inArray(dbSchema.followup_events.sheet_id, companySheetIds),
          gte(dbSchema.followup_events.triggered_at, periodStart),
          lte(dbSchema.followup_events.triggered_at, periodEnd)
        ));
      return result[0]?.count || 0;
    };
    
    // Calculate team projected/actual incentives in parallel
    const dateFilter = { startDate: earliestStart, endDate: latestTarget };
    const teamMetricsResults = await Promise.all(
      allBoards.map(board => 
        getUserPipelineMetrics(companyId, board.user_id, dateFilter).catch(() => null)
      )
    );
    let teamProjectedIncentive = 0;
    let teamActualIncentive = 0;
    for (const metrics of teamMetricsResults) {
      if (metrics) {
        teamProjectedIncentive += metrics.total_projected_incentive || 0;
        teamActualIncentive += metrics.total_actual_incentive || 0;
      }
    }
    
    // Calculate team effort achieved using lead-based counting for all metrics
    // For yearly: cap at yearEnd if now is beyond Vision Board year, otherwise use now
    const yearlyPeriodEnd = now > yearEnd ? yearEnd : now;
    const [
      yearlyVisits, monthlyVisits, lastMonthVisits, weeklyVisits, dailyVisits, yesterdayVisits,
      yearlySales, monthlySales, lastMonthSales, weeklySales, dailySales, yesterdaySales,
      yearlyLeads, monthlyLeads, lastMonthLeads, weeklyLeads, dailyLeads, yesterdayLeads,
      yearlyFollowups, monthlyFollowups, lastMonthFollowups, weeklyFollowups, dailyFollowups, yesterdayFollowups
    ] = await Promise.all([
      countVisitsInPeriod(yearStart, yearlyPeriodEnd),
      countVisitsInPeriod(monthStart, now),
      countVisitsInPeriod(lastMonthStart, lastMonthEnd),
      countVisitsInPeriod(weekStart, now),
      countVisitsInPeriod(dayStart, dayEnd),
      countVisitsInPeriod(yesterdayStart, yesterdayEnd),
      countSalesInPeriod(yearStart, yearlyPeriodEnd),
      countSalesInPeriod(monthStart, now),
      countSalesInPeriod(lastMonthStart, lastMonthEnd),
      countSalesInPeriod(weekStart, now),
      countSalesInPeriod(dayStart, dayEnd),
      countSalesInPeriod(yesterdayStart, yesterdayEnd),
      countLeadsCreated(yearStart, yearlyPeriodEnd),
      countLeadsCreated(monthStart, now),
      countLeadsCreated(lastMonthStart, lastMonthEnd),
      countLeadsCreated(weekStart, now),
      countLeadsCreated(dayStart, dayEnd),
      countLeadsCreated(yesterdayStart, yesterdayEnd),
      countFollowupsInPeriod(yearStart, yearlyPeriodEnd),
      countFollowupsInPeriod(monthStart, now),
      countFollowupsInPeriod(lastMonthStart, lastMonthEnd),
      countFollowupsInPeriod(weekStart, now),
      countFollowupsInPeriod(dayStart, dayEnd),
      countFollowupsInPeriod(yesterdayStart, yesterdayEnd),
    ]);
    
    const teamEffortAchieved = {
      yearly: { sales: yearlySales, visits: yearlyVisits, leads_attended: yearlyLeads, followups: yearlyFollowups },
      monthly: { sales: monthlySales, visits: monthlyVisits, leads_attended: monthlyLeads, followups: monthlyFollowups },
      last_month: { sales: lastMonthSales, visits: lastMonthVisits, leads_attended: lastMonthLeads, followups: lastMonthFollowups },
      weekly: { sales: weeklySales, visits: weeklyVisits, leads_attended: weeklyLeads, followups: weeklyFollowups },
      daily: { sales: dailySales, visits: dailyVisits, leads_attended: dailyLeads, followups: dailyFollowups },
      yesterday: { sales: yesterdaySales, visits: yesterdayVisits, leads_attended: yesterdayLeads, followups: yesterdayFollowups },
    };

    return {
      mode: 'team' as const,
      board_count: boardCount,
      aggregate: {
        id: 'team-aggregate',
        company_id: companyId,
        goal_amount: avgGoal,
        total_goal: totalGoal,
        total_earnings: totalEarnings,
        currency: dominantCurrency,
        goal_description: `Team Average (${boardCount} members)`,
        target_date: latestTarget,
        start_date: earliestStart,
        images: allImages.slice(0, 5),
        effort_targets: effortTotals,
        is_active: true,
      },
      progress: {
        earnings: {
          total: avgEarnings,
          progress_percent: avgProgress,
          goal: avgGoal,
          remaining: Math.max(0, avgGoal - avgEarnings),
        },
        team_totals: {
          total_earnings: totalEarnings,
          total_goal: totalGoal,
          overall_progress_percent: totalGoal > 0 ? Math.round((totalEarnings / totalGoal) * 100) : 0,
          // Add team projected/actual incentives for unified UI
          projected_incentive: teamProjectedIncentive,
          actual_incentive: teamActualIncentive,
          // Projected progress percent is based ONLY on projected incentive (matches personal view logic)
          projected_progress_percent: totalGoal > 0 
            ? Math.min(100, (teamProjectedIncentive / totalGoal) * 100) 
            : 0,
        },
        team_effort_achieved: teamEffortAchieved,
      },
    };
  };

  // Helper: Calculate effort metrics from leads table for a user within date range
  // Counts visits by visit_date, sales by conversion_date (respects company timezone)
  // For single-sheet users: count by their one sheet
  // For multi-sheet users: sum across ALL their accessible sheets
  const calculateEffortMetrics = async (
    userId: string, 
    companyId: string, 
    startDate: Date, 
    endDate: Date,
    sheetIds: string[]  // Array of sheet IDs to sum across (or empty for legacy owner fallback)
  ): Promise<{
    yearly: { sales: number; visits: number; leads_attended: number; followups: number };
    monthly: { sales: number; visits: number; leads_attended: number; followups: number };
    last_month: { sales: number; visits: number; leads_attended: number; followups: number };
    weekly: { sales: number; visits: number; leads_attended: number; followups: number };
    daily: { sales: number; visits: number; leads_attended: number; followups: number };
    yesterday: { sales: number; visits: number; leads_attended: number; followups: number };
  }> => {
    const now = new Date();
    
    // Get company timezone for proper date boundaries
    const company = await storage.getCompany(companyId);
    const companyTimezone = getCompanyTimezone(company);
    
    // Define period boundaries using company timezone
    // For yearly: Use Vision Board start_date to start_date + 1 year (not calendar year)
    const yearStart = getStartOfDayInTimezone(startDate, companyTimezone);
    const yearEndDate = new Date(startDate);
    yearEndDate.setFullYear(yearEndDate.getFullYear() + 1);
    const yearEnd = getEndOfDayInTimezone(yearEndDate, companyTimezone);
    
    const monthStart = getStartOfDayInTimezone(new Date(now.getFullYear(), now.getMonth(), 1), companyTimezone);
    const weekStartDate = new Date(now);
    weekStartDate.setDate(weekStartDate.getDate() - weekStartDate.getDay()); // Sunday
    const weekStart = getStartOfDayInTimezone(weekStartDate, companyTimezone);
    const dayStart = getStartOfDayInTimezone(now, companyTimezone);
    const dayEnd = getEndOfDayInTimezone(now, companyTimezone);
    
    // Yesterday boundaries
    const yesterdayDate = new Date(now);
    yesterdayDate.setDate(yesterdayDate.getDate() - 1);
    const yesterdayStart = getStartOfDayInTimezone(yesterdayDate, companyTimezone);
    const yesterdayEnd = getEndOfDayInTimezone(yesterdayDate, companyTimezone);
    
    // Last month boundaries
    const lastMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const lastMonthStart = getStartOfDayInTimezone(lastMonthDate, companyTimezone);
    const lastMonthEndDate = new Date(now.getFullYear(), now.getMonth(), 0); // Last day of previous month
    const lastMonthEnd = getEndOfDayInTimezone(lastMonthEndDate, companyTimezone);
    
    // Count visits: leads where visit_status='Visited' AND visit_date is within period
    // Only count leads with valid visit_date set
    const countVisitsInPeriod = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (sheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, sheetIds),
          sql`custom_fields->>'visit_status' = 'Visited'`,
          sql`custom_fields->>'visit_date' IS NOT NULL`,
          sql`custom_fields->>'visit_date' != ''`,
          sql`(custom_fields->>'visit_date')::timestamp >= ${periodStart}`,
          sql`(custom_fields->>'visit_date')::timestamp < ${periodEnd}`,
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count sales: leads where conversion_date (custom_fields) is within period
    const countSalesInPeriod = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (sheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, sheetIds),
          sql`custom_fields->>'conversion_date' IS NOT NULL`,
          sql`custom_fields->>'conversion_date' != ''`,
          sql`(custom_fields->>'conversion_date')::timestamp >= ${periodStart}`,
          sql`(custom_fields->>'conversion_date')::timestamp < ${periodEnd}`,
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count leads across ALL sheets by created_at
    const countLeadsAcrossSheets = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (sheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.leads)
        .where(and(
          inArray(dbSchema.leads.sheet_id, sheetIds),
          gte(dbSchema.leads.created_at, periodStart),
          lte(dbSchema.leads.created_at, periodEnd),
          isNull(dbSchema.leads.deleted_at)
        ));
      return result[0]?.count || 0;
    };
    
    // Count followups across ALL sheets
    const countFollowupsAcrossSheets = async (periodStart: Date, periodEnd: Date): Promise<number> => {
      if (sheetIds.length === 0) return 0;
      const result = await db.select({ count: sql<number>`count(*)::int` })
        .from(dbSchema.followup_events)
        .where(and(
          inArray(dbSchema.followup_events.sheet_id, sheetIds),
          gte(dbSchema.followup_events.triggered_at, periodStart),
          lte(dbSchema.followup_events.triggered_at, periodEnd)
        ));
      return result[0]?.count || 0;
    };
    
    // Query all metrics in parallel for each period
    // For yearly: cap at yearEnd if now is beyond Vision Board year, otherwise use now
    const yearlyPeriodEnd = now > yearEnd ? yearEnd : now;
    const [
      yearlyVisits, monthlyVisits, lastMonthVisits, weeklyVisits, dailyVisits, yesterdayVisits,
      yearlySales, monthlySales, lastMonthSales, weeklySales, dailySales, yesterdaySales,
      yearlyLeads, monthlyLeads, lastMonthLeads, weeklyLeads, dailyLeads, yesterdayLeads,
      yearlyFollowups, monthlyFollowups, lastMonthFollowups, weeklyFollowups, dailyFollowups, yesterdayFollowups
    ] = await Promise.all([
      countVisitsInPeriod(yearStart, yearlyPeriodEnd),
      countVisitsInPeriod(monthStart, now),
      countVisitsInPeriod(lastMonthStart, lastMonthEnd),
      countVisitsInPeriod(weekStart, now),
      countVisitsInPeriod(dayStart, dayEnd),
      countVisitsInPeriod(yesterdayStart, yesterdayEnd),
      countSalesInPeriod(yearStart, yearlyPeriodEnd),
      countSalesInPeriod(monthStart, now),
      countSalesInPeriod(lastMonthStart, lastMonthEnd),
      countSalesInPeriod(weekStart, now),
      countSalesInPeriod(dayStart, dayEnd),
      countSalesInPeriod(yesterdayStart, yesterdayEnd),
      countLeadsAcrossSheets(yearStart, yearlyPeriodEnd),
      countLeadsAcrossSheets(monthStart, now),
      countLeadsAcrossSheets(lastMonthStart, lastMonthEnd),
      countLeadsAcrossSheets(weekStart, now),
      countLeadsAcrossSheets(dayStart, dayEnd),
      countLeadsAcrossSheets(yesterdayStart, yesterdayEnd),
      countFollowupsAcrossSheets(yearStart, yearlyPeriodEnd),
      countFollowupsAcrossSheets(monthStart, now),
      countFollowupsAcrossSheets(lastMonthStart, lastMonthEnd),
      countFollowupsAcrossSheets(weekStart, now),
      countFollowupsAcrossSheets(dayStart, dayEnd),
      countFollowupsAcrossSheets(yesterdayStart, yesterdayEnd),
    ]);
    
    return {
      yearly: { sales: yearlySales, visits: yearlyVisits, leads_attended: yearlyLeads, followups: yearlyFollowups },
      monthly: { sales: monthlySales, visits: monthlyVisits, leads_attended: monthlyLeads, followups: monthlyFollowups },
      last_month: { sales: lastMonthSales, visits: lastMonthVisits, leads_attended: lastMonthLeads, followups: lastMonthFollowups },
      weekly: { sales: weeklySales, visits: weeklyVisits, leads_attended: weeklyLeads, followups: weeklyFollowups },
      daily: { sales: dailySales, visits: dailyVisits, leads_attended: dailyLeads, followups: dailyFollowups },
      yesterday: { sales: yesterdaySales, visits: yesterdayVisits, leads_attended: yesterdayLeads, followups: yesterdayFollowups },
    };
  };

  // Get current user's vision board (or team aggregates for admins/multi-sheet users)
