  // Get user's closed sales (converted leads) for incentive tracking
  app.get("/api/vision-board/closed-sales", authMiddleware, async (req: AuthRequest, res) => {
    try {
      const companyId = getAuthCompanyId(req);
      if (!companyId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }
      
      const user = await storage.getUser(req.userId!);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      
      // Get user's sheet access
      const sheetUsers = await storage.getUserSheetAccess(req.userId!);
      const accessibleSheetIds = sheetUsers.map(su => su.sheet_id);
      
      if (accessibleSheetIds.length === 0) {
        return res.json([]);
      }
      
      // Fetch leads owned by user with "Converted" status (sequential to avoid connection exhaustion)
      const sheetLeadArrays: any[][] = [];
      for (const sheetId of accessibleSheetIds) {
        sheetLeadArrays.push(await storage.getLeadsBySheetId(sheetId));
      }
      const allLeads: any[] = sheetLeadArrays.flat().filter((lead: any) => {
        const isOwner = lead.owner_user_id === req.userId;
        const canonicalStatus = (lead.status || '').toLowerCase();
        const customStatus = (lead.custom_fields?.lead_status || '').toLowerCase();
        const convertedStatuses = ['converted', 'closed', 'won', 'booked', 'sold'];
        const isConverted = convertedStatuses.includes(canonicalStatus) || 
                           convertedStatuses.includes(customStatus);
        return isOwner && isConverted;
      });
      
      // Get vision board to check which leads already have earnings recorded
      const board = await storage.getVisionBoard(req.userId!);
      let existingLeadEarnings: Set<string> = new Set();
      if (board) {
        const earnings = await storage.getVisionBoardEarnings(board.id);
        existingLeadEarnings = new Set(earnings.filter(e => e.source_lead_id).map(e => e.source_lead_id!));
      }
      
      // Return leads with their earning status
      const closedSales = allLeads.map(lead => ({
        id: lead.id,
        name: lead.custom_fields?.name || lead.custom_fields?.client_name || lead.custom_fields?.lead_name || 'Unknown',
        mobile_no: lead.custom_fields?.mobile_no || '',
        status: lead.custom_fields?.lead_status || '',
        converted_at: lead.updated_at,
        has_earning: existingLeadEarnings.has(lead.id),
      }));
      
      res.json(closedSales);
    } catch (error: any) {
      console.error("Error fetching closed sales:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get vision board progress with auto-calculated effort metrics
  app.get("/api/vision-board/:visionBoardId/progress", authMiddleware, async (req: AuthRequest, res) => {
    try {
      const { visionBoardId } = req.params;
      const board = await storage.getVisionBoard(req.userId!);
      if (!board || board.id !== visionBoardId) {
        return res.status(404).json({ error: "Vision board not found" });
      }

      const earnings = await storage.getVisionBoardEarnings(visionBoardId);
      const totalEarned = earnings.reduce((sum, e) => sum + e.amount, 0);
      const progressPercent = board.goal_amount > 0 ? (totalEarned / board.goal_amount) * 100 : 0;

      const now = new Date();
      const targetDate = new Date(board.target_date);
      // Use start_date if set, otherwise fall back to created_at
      const startDate = board.start_date ? new Date(board.start_date) : new Date(board.created_at);
      const totalDays = Math.ceil((targetDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
      const daysElapsed = Math.ceil((now.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
      const daysRemaining = Math.max(0, Math.ceil((targetDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)));

      // Calculate period breakdowns for efforts (auto-calculated from yearly targets)
      const yearlyTargets = board.effort_targets;
      const overrides = board.effort_overrides || {};
      
      const calculatePeriodTargets = (yearly: number, period: 'monthly' | 'weekly' | 'daily') => {
        const override = overrides[period];
        if (override) return override;
        
        if (period === 'monthly') return Math.ceil(yearly / 12);
        if (period === 'weekly') return Math.ceil(yearly / 52);
        if (period === 'daily') return Math.ceil(yearly / 365);
        return yearly;
      };

      const periodBreakdowns = {
        yearly: yearlyTargets,
        monthly: {
          sales: calculatePeriodTargets(yearlyTargets.sales, 'monthly'),
          visits: calculatePeriodTargets(yearlyTargets.visits, 'monthly'),
          leads_attended: calculatePeriodTargets(yearlyTargets.leads_attended, 'monthly'),
          followups: calculatePeriodTargets(yearlyTargets.followups, 'monthly'),
        },
        weekly: {
          sales: calculatePeriodTargets(yearlyTargets.sales, 'weekly'),
          visits: calculatePeriodTargets(yearlyTargets.visits, 'weekly'),
          leads_attended: calculatePeriodTargets(yearlyTargets.leads_attended, 'weekly'),
          followups: calculatePeriodTargets(yearlyTargets.followups, 'weekly'),
        },
        daily: {
          sales: calculatePeriodTargets(yearlyTargets.sales, 'daily'),
          visits: calculatePeriodTargets(yearlyTargets.visits, 'daily'),
          leads_attended: calculatePeriodTargets(yearlyTargets.leads_attended, 'daily'),
          followups: calculatePeriodTargets(yearlyTargets.followups, 'daily'),
        },
      };

      // Determine sheet IDs for counting metrics:
      // For admins: Get ALL company sheets (they should see summed metrics across all sheets)
      // For regular users: Get only sheets they have access to via sheet_users
      let accessibleSheetIds: string[] = [];
      if (req.companyId) {
        if (req.userRole === "super_admin" || req.userRole === "company_admin") {
          // Admins see ALL non-personal company sheets
          const allCompanySheets = await storage.getSheetsByCompanyId(req.companyId);
          accessibleSheetIds = allCompanySheets
            .filter(s => !s.deleted_at && !s.is_personal)
            .map(s => s.id);
        } else {
          // Regular users see only sheets they're assigned to
          const userSheets = await storage.getSheetsByUserId(req.userId!);
          const companySheets = userSheets.filter(s => s.company_id === req.companyId && !s.is_personal);
          accessibleSheetIds = companySheets.map(s => s.id);
        }
      }

      // Calculate effort achievements from activity_logs with date filtering
      // Sum across ALL accessible sheets (single-sheet users get their 1 sheet, multi-sheet users get all)
      const effortAchieved = await calculateEffortMetrics(
        req.userId!, 
        req.companyId!, 
        startDate, 
        targetDate,
        accessibleSheetIds  // Sum metrics across ALL accessible sheets
      );

      // Use SHARED HELPER for projected/actual incentive (same formula as Conversion Settings)
      // getUserPipelineMetrics already aggregates across ALL user's accessible sheets
      // Projected: All-time, no date filter, middle stages only with cascading multipliers
      // Actual: Date-filtered using Vision Board dates, last stage only
      let projectedIncentive = 0;
      let actualIncentive = 0;
      let projectedProgressPercent = 0;
      let pipelineStages: PipelineStageMetric[] = [];
      
      if (req.companyId && req.userId) {
        try {
          // Use Vision Board dates for actual incentive filter
          const actualDateFilter = { startDate, endDate: targetDate };
          // getUserPipelineMetrics already handles multi-sheet aggregation internally
          const metrics = await getUserPipelineMetrics(req.companyId, req.userId, actualDateFilter);
          
          if (metrics) {
            projectedIncentive = metrics.total_projected_incentive;
            actualIncentive = metrics.total_actual_incentive;
            pipelineStages = metrics.stages;
            
            // Calculate projected progress percent against goal
            const totalPipelineIncentive = projectedIncentive + actualIncentive;
            projectedProgressPercent = board.goal_amount > 0 ? (totalPipelineIncentive / board.goal_amount) * 100 : 0;
          }
        } catch (err) {
          console.error("Error fetching incentives from shared helper:", err);
        }
      }

      const progressResult = {
        board,
        earnings: {
          total: totalEarned,
          progress_percent: Math.min(100, progressPercent),
          goal: board.goal_amount,
          remaining: Math.max(0, board.goal_amount - totalEarned),
          projected_incentive: Math.round(projectedIncentive * 100) / 100,
          actual_incentive: Math.round(actualIncentive * 100) / 100,
          projected_progress_percent: Math.min(100, projectedProgressPercent),
        },
        timeline: {
          total_days: totalDays,
          days_elapsed: daysElapsed,
          days_remaining: daysRemaining,
          time_progress_percent: totalDays > 0 ? Math.min(100, (daysElapsed / totalDays) * 100) : 0,
        },
        effort_targets: periodBreakdowns,
        effort_achieved: effortAchieved,
      };

      res.json(progressResult);
    } catch (error: any) {
      console.error("Error calculating progress:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get current user's pipeline projected incentive (for Vision Board dual-ring)
  // This is accessible by any authenticated user (not just admins)
