  // Migrate existing vision boards to admin-controlled tables
  app.post("/api/admin/vision-board/migrate", authMiddleware, requireCompanyAdmin, async (req: AuthRequest, res) => {
    console.log("[Migration] Starting vision board migration...");
    try {
      if (!req.companyId || !req.userId) {
        console.log("[Migration] Error: Must belong to a company");
        return res.status(403).json({ error: "Must belong to a company" });
      }
      
      console.log("[Migration] Company ID:", req.companyId, "User ID:", req.userId);
      const currentYear = new Date().getFullYear();
      
      // Get all users in company with their vision boards
      const companyUsers = await storage.getUsersByCompanyId(req.companyId!);
      const results = {
        migrated: 0,
        skipped: 0,
        errors: [] as string[],
        details: [] as { userId: string; userName: string; status: string; goalAmount?: number }[],
      };
      
      for (const user of companyUsers) {
        try {
          // Check if admin target already exists
          const existingAdminTarget = await storage.getUserVisionAdminTarget(user.id, currentYear);
          if (existingAdminTarget) {
            results.skipped++;
            results.details.push({ userId: user.id, userName: user.name, status: 'skipped (already has admin target)' });
            continue;
          }
          
          // Get user's personal vision board
          const visionBoard = await storage.getVisionBoard(user.id);
          if (!visionBoard) {
            results.skipped++;
            results.details.push({ userId: user.id, userName: user.name, status: 'skipped (no personal vision board)' });
            continue;
          }
          
          // Create admin target from vision board data
          const adminTarget = await storage.createUserVisionAdminTarget({
            user_id: user.id,
            company_id: req.companyId,
            year: currentYear,
            goal_amount: visionBoard.goal_amount,
            currency: visionBoard.currency || 'INR',
            goal_description: visionBoard.goal_description,
            images: visionBoard.images || [],
            annual_targets: visionBoard.effort_targets || { sales: 0, visits: 0, leads_attended: 0, followups: 0 },
            is_active: true,
            created_by: req.userId,
          });
          
          // Auto-distribute monthly targets from annual targets
          if (adminTarget.id) {
            await storage.autoDistributeUserVisionMonthly(
              adminTarget.id, 
              user.id, 
              req.companyId, 
              currentYear, 
              visionBoard.effort_targets || { sales: 0, visits: 0, leads_attended: 0, followups: 0 }
            );
          }
          
          results.migrated++;
          results.details.push({ 
            userId: user.id, 
            userName: user.name, 
            status: 'migrated', 
            goalAmount: visionBoard.goal_amount 
          });
        } catch (err: any) {
          results.errors.push(`${user.name}: ${err.message}`);
          results.details.push({ userId: user.id, userName: user.name, status: `error: ${err.message}` });
        }
      }
      
      console.log("[Migration] Complete:", results);
      res.json(results);
    } catch (error: any) {
      console.error("Error migrating vision boards:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // ============================================================================
  // WORK REPORT - Time-wise work summary (lead updates per time slot per user)
  // ============================================================================

  // Define fixed time slots
  function getWorkReportSlots(): Array<{ label: string; start: number; end: number }> {
    const slots = [{ label: "12am–9am", start: 0, end: 9 }];
    for (let h = 9; h < 21; h++) {
      const startLabel = h < 12 ? `${h}am` : h === 12 ? "12pm" : `${h - 12}pm`;
      const endLabel = (h + 1) < 12 ? `${h + 1}am` : (h + 1) === 12 ? "12pm" : `${h + 1 - 12}pm`;
      slots.push({ label: `${startLabel}–${endLabel}`, start: h, end: h + 1 });
    }
    slots.push({ label: "9pm–12am", start: 21, end: 24 });
    return slots;
  }

  // GET /api/work-report - summary grid (slots × users), slot-centric response
  app.get("/api/work-report", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId || !req.userId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const { date, startDate: qStartDate, endDate: qEndDate, userId: queryUserId } = req.query as {
        date?: string; startDate?: string; endDate?: string; userId?: string;
      };
      const company = await storage.getCompany(req.companyId);
      const timezone = (company?.settings?.timezone) || "UTC";

      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      const isCalendarValid = (d: string) => {
        const dt = new Date(d + "T12:00:00Z");
        return !isNaN(dt.getTime()) && dt.toISOString().slice(0, 10) === d;
      };
      const today = getTodayDateString(timezone);

      // Resolve startDate / endDate — support both legacy ?date= and new ?startDate=&endDate=
      let resolvedStart: string;
      let resolvedEnd: string;
      if (qStartDate && qEndDate) {
        if (!dateRegex.test(qStartDate) || !dateRegex.test(qEndDate)) {
          return res.status(400).json({ error: "startDate and endDate must be in YYYY-MM-DD format" });
        }
        if (!isCalendarValid(qStartDate) || !isCalendarValid(qEndDate)) {
          return res.status(400).json({ error: "startDate or endDate is not a valid calendar date" });
        }
        resolvedStart = qStartDate;
        resolvedEnd = qEndDate;
      } else if (date) {
        if (!dateRegex.test(date)) {
          return res.status(400).json({ error: "date must be in YYYY-MM-DD format" });
        }
        if (!isCalendarValid(date)) {
          return res.status(400).json({ error: "date is not a valid calendar date" });
        }
        resolvedStart = date;
        resolvedEnd = date;
      } else {
        resolvedStart = today;
        resolvedEnd = today;
      }
      // Validate range ordering and length
      const startMs = new Date(resolvedStart + "T12:00:00Z").getTime();
      const endMs = new Date(resolvedEnd + "T12:00:00Z").getTime();
      if (endMs < startMs) {
        return res.status(400).json({ error: "endDate must not be before startDate" });
      }
      const diffDays = Math.round((endMs - startMs) / 86400000);
      if (diffDays > 30) {
        return res.status(400).json({ error: "Date range must not exceed 31 days" });
      }

      // Parse date range for the report in UTC
      const dayStart = getStartOfDayInTimezone(new Date(resolvedStart + "T12:00:00Z"), timezone);
      const dayEnd = getEndOfDayInTimezone(new Date(resolvedEnd + "T12:00:00Z"), timezone);

      // Load all active users for name mapping and eligibility filtering
      const allUsers = await storage.getUsersByCompanyId(req.companyId);
      const userMap = new Map(allUsers.map(u => [u.id, u]));

      // Eligible users: active role='user' (not company_admin) AND single-sheet (≤1 non-personal company sheet)
      const regularActiveUsers = allUsers.filter(u => u.is_active && u.role === 'user');
      let eligibleUserIds: string[] = [];
      if (regularActiveUsers.length > 0) {
        const regularUserIds = regularActiveUsers.map(u => u.id);
        const sheetCountRows = await db
          .select({
            user_id: dbSchema.sheet_users.user_id,
            sheet_count: sql<number>`count(${dbSchema.sheet_users.sheet_id})::int`,
          })
          .from(dbSchema.sheet_users)
          .innerJoin(dbSchema.sheets, eq(dbSchema.sheets.id, dbSchema.sheet_users.sheet_id))
          .where(
            and(
              eq(dbSchema.sheets.company_id, req.companyId),
              eq(dbSchema.sheets.is_personal, false),
              inArray(dbSchema.sheet_users.user_id, regularUserIds)
            )
          )
          .groupBy(dbSchema.sheet_users.user_id);
        const multiSheetUserIds = new Set(
          sheetCountRows.filter(r => r.sheet_count > 1).map(r => r.user_id)
        );
        eligibleUserIds = regularUserIds.filter(id => !multiSheetUserIds.has(id));
      }

      // Determine which users to include in the report
      const isAdmin = req.userRole === "company_admin";
      let targetUserIds: string[];

      if (isAdmin && !queryUserId) {
        targetUserIds = eligibleUserIds;
      } else if (queryUserId && (isAdmin || queryUserId === req.userId)) {
        targetUserIds = eligibleUserIds.includes(queryUserId) ? [queryUserId] : [];
      } else {
        targetUserIds = eligibleUserIds.includes(req.userId) ? [req.userId] : [];
      }

      const slots = getWorkReportSlots();
      const CAP_PER_LEAD = 4; // minutes per lead, capped at slot duration

      // Build the full eligible user list for the dropdown (always included regardless of userId filter)
      const eligibleUsersInfo = eligibleUserIds
        .filter(uid => userMap.has(uid))
        .map(uid => ({ id: uid, name: userMap.get(uid)!.name }));

      if (targetUserIds.length === 0) {
        return res.json({
          startDate: resolvedStart,
          endDate: resolvedEnd,
          eligibleUsers: eligibleUsersInfo,
          users: [],
          slots: slots.map(s => ({ label: s.label, slotMinutes: (s.end - s.start) * 60, data: {} })),
        });
      }

      // Build the slot CASE expression parts using Drizzle sql tag.
      // slot.start and slot.end are integers 0-24 from server-hardcoded getWorkReportSlots().
      // We use sql.raw() only for these integer bounds (server constants) and bind all other values.
      const slotWhenParts = slots.map(s =>
        sql`WHEN EXTRACT(HOUR FROM lu.created_at AT TIME ZONE 'UTC' AT TIME ZONE ${timezone})::int >= ${sql.raw(String(s.start))} AND EXTRACT(HOUR FROM lu.created_at AT TIME ZONE 'UTC' AT TIME ZONE ${timezone})::int < ${sql.raw(String(s.end))} THEN ${s.label}`
      );
      const slotCaseFragment = sql`CASE ${sql.join(slotWhenParts, sql` `)} ELSE NULL END`;

      // Parameterize user IDs and manual update types
      const userIdParams = sql.join(targetUserIds.map(id => sql`${id}`), sql`, `);
      const manualTypeParams = sql.join(dbSchema.MANUAL_UPDATE_TYPES.map(t => sql`${t}`), sql`, `);

      // Two-level CTE:
      // 1. "bucketed" assigns each update a slot label and its local activity_date
      // 2. "daily_counts" counts DISTINCT leads per (user, slot, day) — prevents double-counting
      //    leads touched multiple times in the same slot on the same day
      // 3. Outer aggregates across days, returning daily_leads_array for per-day capping in app code
      const aggRows = await db.execute(sql`
        WITH bucketed AS (
          SELECT
            lu.created_by_user_id AS user_id,
            lu.lead_id,
            (lu.created_at AT TIME ZONE 'UTC' AT TIME ZONE ${timezone})::date AS activity_date,
            ${slotCaseFragment} AS slot_label
          FROM lead_updates lu
          WHERE
            lu.created_by_user_id = ANY(ARRAY[${userIdParams}])
            AND lu.created_at >= ${dayStart}
            AND lu.created_at <= ${dayEnd}
            AND lu.created_by_user_id IS NOT NULL
            AND lu.update_via = ANY(ARRAY[${manualTypeParams}])
        ),
        daily_counts AS (
          SELECT
            user_id,
            slot_label,
            activity_date,
            COUNT(DISTINCT lead_id)::int AS daily_leads
          FROM bucketed
          WHERE slot_label IS NOT NULL
          GROUP BY user_id, slot_label, activity_date
        )
        SELECT
          user_id,
          slot_label,
          SUM(daily_leads)::int AS total_leads,
          array_agg(daily_leads ORDER BY activity_date) AS daily_leads_array
        FROM daily_counts
        GROUP BY user_id, slot_label
      `);

      // Map aggregated data: userId → slotLabel → { totalLeads, dailyLeadsArray }
      const aggMap = new Map<string, Map<string, { totalLeads: number; dailyLeadsArray: number[] }>>();
      for (const row of aggRows.rows as Array<{ user_id: string; slot_label: string; total_leads: number; daily_leads_array: number[] }>) {
        if (!aggMap.has(row.user_id)) aggMap.set(row.user_id, new Map());
        aggMap.get(row.user_id)!.set(row.slot_label, {
          totalLeads: Number(row.total_leads),
          dailyLeadsArray: Array.isArray(row.daily_leads_array) ? row.daily_leads_array.map(Number) : [Number(row.total_leads)],
        });
      }

      // Build slot-centric response
      const usersInfo = targetUserIds
        .filter(uid => userMap.has(uid))
        .map(uid => ({ id: uid, name: userMap.get(uid)!.name }));

      const slotsResult = slots.map(slot => {
        const slotMinutes = (slot.end - slot.start) * 60;
        const data: Record<string, { uniqueLeads: number; activityMinutes: number }> = {};

        for (const { id: uid } of usersInfo) {
          const entry = aggMap.get(uid)?.get(slot.label);
          const uniqueLeads = entry?.totalLeads || 0;
          // Apply 4-min/lead cap per day then sum — correct for multi-day ranges
          const activityMinutes = entry
            ? entry.dailyLeadsArray.reduce((sum, dl) => sum + Math.min(dl * CAP_PER_LEAD, slotMinutes), 0)
            : 0;
          data[uid] = { uniqueLeads, activityMinutes };
        }

        return { label: slot.label, slotMinutes, start: slot.start, end: slot.end, data };
      });

      res.json({
        startDate: resolvedStart,
        endDate: resolvedEnd,
        eligibleUsers: eligibleUsersInfo,
        users: usersInfo,
        slots: slotsResult,
      });
    } catch (error: any) {
      console.error("Error fetching work report:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/work-report/slot-leads - leads updated by a user in a specific time slot
  app.get("/api/work-report/slot-leads", authMiddleware, async (req: AuthRequest, res) => {
    try {
      if (!req.companyId || !req.userId) {
        return res.status(403).json({ error: "Must belong to a company" });
      }

      const { date, startDate: qSD, endDate: qED, slotStart, slotEnd, userId: queryUserId } = req.query as {
        date?: string; startDate?: string; endDate?: string;
        slotStart?: string; slotEnd?: string; userId?: string;
      };

      const isAdmin = req.userRole === "company_admin";
      const targetUserId = queryUserId && (isAdmin || queryUserId === req.userId)
        ? queryUserId
        : req.userId;

      if (!slotStart || !slotEnd) {
        return res.status(400).json({ error: "slotStart, slotEnd are required" });
      }

      const company = await storage.getCompany(req.companyId);
      const timezone = (company?.settings?.timezone) || "UTC";

      const dateRegexSL = /^\d{4}-\d{2}-\d{2}$/;
      const isCalendarValidSL = (d: string) => {
        const dt = new Date(d + "T12:00:00Z");
        return !isNaN(dt.getTime()) && dt.toISOString().slice(0, 10) === d;
      };
      let slResolvedStart: string;
      let slResolvedEnd: string;
      if (qSD && qED) {
        if (!dateRegexSL.test(qSD) || !dateRegexSL.test(qED)) {
          return res.status(400).json({ error: "startDate and endDate must be in YYYY-MM-DD format" });
        }
        if (!isCalendarValidSL(qSD) || !isCalendarValidSL(qED)) {
          return res.status(400).json({ error: "startDate or endDate is not a valid calendar date" });
        }
        slResolvedStart = qSD;
        slResolvedEnd = qED;
      } else if (date) {
        if (!dateRegexSL.test(date)) {
          return res.status(400).json({ error: "date must be in YYYY-MM-DD format" });
        }
        if (!isCalendarValidSL(date)) {
          return res.status(400).json({ error: "date is not a valid calendar date" });
        }
        slResolvedStart = date;
        slResolvedEnd = date;
      } else {
        return res.status(400).json({ error: "date (or startDate+endDate) is required" });
      }
      // Validate range ordering and max 31 days
      const slStartMs = new Date(slResolvedStart + "T12:00:00Z").getTime();
      const slEndMs = new Date(slResolvedEnd + "T12:00:00Z").getTime();
      if (slEndMs < slStartMs) {
        return res.status(400).json({ error: "endDate must not be before startDate" });
      }
      const slDiffDays = Math.round((slEndMs - slStartMs) / 86400000);
      if (slDiffDays > 30) {
        return res.status(400).json({ error: "Date range must not exceed 31 days" });
      }

      const dayStart = getStartOfDayInTimezone(new Date(slResolvedStart + "T12:00:00Z"), timezone);
      const dayEnd = getEndOfDayInTimezone(new Date(slResolvedEnd + "T12:00:00Z"), timezone);

      const slotStartHour = parseInt(slotStart, 10);
      const slotEndHour = parseInt(slotEnd, 10);

      // Fetch updates in the slot time range for this user — manual only
      const updates = await db
        .select({
          lead_id: dbSchema.lead_updates.lead_id,
          created_at: dbSchema.lead_updates.created_at,
        })
        .from(dbSchema.lead_updates)
        .where(
          and(
            eq(dbSchema.lead_updates.created_by_user_id, targetUserId),
            gte(dbSchema.lead_updates.created_at, dayStart),
            lte(dbSchema.lead_updates.created_at, dayEnd),
            inArray(dbSchema.lead_updates.update_via, [...dbSchema.MANUAL_UPDATE_TYPES])
          )
        );

      // Filter by local hour
      const leadIdsInSlot = new Set<string>();
      for (const upd of updates) {
        const localHour = parseInt(formatInTimeZone(upd.created_at, timezone, "H"), 10);
        if (localHour >= slotStartHour && localHour < slotEndHour) {
          leadIdsInSlot.add(upd.lead_id);
        }
      }

      if (leadIdsInSlot.size === 0) {
        return res.json({ leads: [], sheets: [], count: 0 });
      }

      // Fetch the actual leads
      const leadIds = [...leadIdsInSlot];
      const leadsResult = await db
        .select()
        .from(dbSchema.leads)
        .where(
          and(
            inArray(dbSchema.leads.id, leadIds),
            isNull(dbSchema.leads.deleted_at)
          )
        );

      // Check that these leads belong to this company via sheets
      const sheetIds = [...new Set(leadsResult.map(l => l.sheet_id))];
      const companySheets = await storage.getSheetsByCompanyId(req.companyId);
      const companySheetIds = new Set(companySheets.map(s => s.id));

      const authorizedLeads = leadsResult.filter(l => companySheetIds.has(l.sheet_id));
      const authorizedSheetIds = [...new Set(authorizedLeads.map(l => l.sheet_id))];
      const sheetsForLeads = companySheets.filter(s => authorizedSheetIds.includes(s.id));

      res.json({
        leads: authorizedLeads,
        sheets: sheetsForLeads,
        count: authorizedLeads.length,
      });
    } catch (error: any) {
      console.error("Error fetching work report slot leads:", error);
      res.status(500).json({ error: error.message });
    }
  });

